def _offh_coerce_br_strings(d):
	if isinstance(d, dict):
		res = {}
		for k, v in d.items():
			k_out = str(k) if isinstance(k, (int, long)) else k
			if k_out in ('arenaStr', 'mapName', 'winText', 'finishReasonStr', 'playerName', 'clanAbbrev', 'vehicleName', 'userName', 'killerName', 'time', 'date', 'arenaCreateTimeStr') and isinstance(v, (int, long, float)):
				res[k_out] = str(v)
			else:
				res[k_out] = _offh_coerce_br_strings(v)
		return res
	elif isinstance(d, list):
		return [_offh_coerce_br_strings(x) for x in d]
	elif isinstance(d, tuple):
		return tuple(_offh_coerce_br_strings(x) for x in d)
	return d

