def _offh_crew_level_time_factor(crew_level):
	"""Turn a crew_level (0.5-1.1) into a TIME multiplier (>1 = slower), the same
	convention _crew_factor/_module_factor already use for damage-based crew and
	module maluses. A stock 0.5-trained crew comes out to 1.3x (30% slower); a
	1.1 veteran crew comes out to 0.94x (6% faster). Clamped defensively - this
	must never invert (crew_level <=0 blowing the multiplier up) or go negative.
	"""
	try:
		crew_level = float(crew_level)
	except Exception:
		return 1.0
	if crew_level != crew_level:  # NaN guard
		return 1.0
	factor = 1.0 + (1.0 - crew_level) * 0.6
	if factor < 0.5:
		factor = 0.5
	elif factor > 2.0:
		factor = 2.0
	return factor


def _offh_upgrade_bot_components(td, tier):
	"""Point 12 (v8.9 Modular): Delegate to combat.bot_loadout.upgrade_bot_components."""
	try:
		from gui.mods.offhangar.combat.bot_loadout import upgrade_bot_components as _ub_comp
		return _ub_comp(td, tier)
	except Exception:
		pass
	if td is None or getattr(td, 'type', None) is None:
		return
	import random
	vtype = td.type
	_vname = str(getattr(vtype, 'name', 'unknown'))
	try:
		ch_list = getattr(vtype, 'chassis', ()) or ()
		eng_list = getattr(vtype, 'engines', ()) or ()
		rad_list = getattr(vtype, 'radios', ()) or ()
		tur_slots = getattr(vtype, 'turrets', ()) or ()
		tur_list = tur_slots[0] if (tur_slots and len(tur_slots) > 0) else ()
		if tier == 'easy':
			# Easy bots drive pure stock tanks (80%) or stock with only 2nd gun on stock turret (20%)
			if random.random() < 0.20 and ch_list and tur_list:
				try: td.installComponent(ch_list[-1]['compactDescr'])
				except Exception: pass
				st_tur = tur_list[0]
				guns = st_tur.get('guns', ()) or ()
				if len(guns) > 1:
					try: td.installTurret(st_tur['compactDescr'], guns[min(1, len(guns) - 1)]['compactDescr'])
					except Exception: pass
			LOG_DEBUG('BOT_LOADOUT_MODULES veh=%s tier=easy config=stock gun=%s hp=%d' % (
				_vname, str((getattr(td, 'gun', None) or {}).get('name', '?')), int(getattr(td, 'maxHealth', 0) or 0)))
			return
		# For medium and hard: install top chassis first so maxWeight supports heavier turrets/guns/engines
		if len(ch_list) > 1:
			try: td.installComponent(ch_list[-1]['compactDescr'])
			except Exception: pass
		if tier == 'medium':
			if len(eng_list) > 1:
				eng_idx = max(0, len(eng_list) // 2)
				try: td.installComponent(eng_list[eng_idx]['compactDescr'])
				except Exception: pass
			if len(rad_list) > 1:
				rad_idx = max(0, len(rad_list) // 2)
				try: td.installComponent(rad_list[rad_idx]['compactDescr'])
				except Exception: pass
			def _score_bot_gun(_g, _vtags=()):
				try:
					_shots = _g.get('shots', ()) or ()
					if not _shots:
						return 0.0
					_s0 = _shots[0]
					_pp = _s0.get('piercingPower', (100, 100))
					try:
						_pen0 = float(_pp[0])
					except Exception:
						_pen0 = float(_pp or 100.0)
					_sh0 = _s0.get('shell', {})
					_dmg = _sh0.get('damage', (100, 100))
					try:
						_dmg0 = float(_dmg[0])
					except Exception:
						_dmg0 = float(_dmg or 100.0)
					_cal = float(_sh0.get('caliber', 75.0) or 75.0)
					_spd = float(_s0.get('speed', 600.0) or 600.0)
					_rld = max(1.5, float(_g.get('reloadTime', 6.0) or 6.0))
					_lvl = float(_g.get('level', 1) or 1)
					if 'SPG' in _vtags and 'AT-SPG' not in _vtags:
						return _lvl * 120.0 + _dmg0 * 0.5 + _cal
					_is_low_pen_derp = (_cal >= 75.0 and _pen0 <= 70.0 and _spd <= 500.0)
					_score = _lvl * 60.0 + _pen0 * 2.8 + _dmg0 * 0.65 + (_dmg0 / _rld) * 8.0 + _spd * 0.08
					if _is_low_pen_derp:
						_score -= 220.0
					return _score
				except Exception:
					return 0.0
			_vtags = getattr(vtype, 'tags', ()) or ()
			if tur_list:
				if len(tur_list) > 1 and random.random() < 0.70:
					tur = tur_list[-1]
				else:
					tur = tur_list[0]
				guns = list(tur.get('guns', ()) or ())
				if guns:
					_sorted_guns = sorted(guns, key=lambda _gg: _score_bot_gun(_gg, _vtags))
					gun = _sorted_guns[-1] if (len(_sorted_guns) == 1 or random.random() < 0.65) else _sorted_guns[-2]
				else:
					gun = None
				if tur is not None and gun is not None:
					try: td.installTurret(tur['compactDescr'], gun['compactDescr'])
					except Exception: pass
			LOG_DEBUG('BOT_LOADOUT_MODULES veh=%s tier=medium config=partial gun=%s hp=%d' % (
				_vname, str((getattr(td, 'gun', None) or {}).get('name', '?')), int(getattr(td, 'maxHealth', 0) or 0)))
		else:
			# Hard: full Elite top modules (top chassis, top engine, top radio, top turret, best high-effectiveness gun)
			def _score_bot_gun_hard(_g, _vtags=()):
				try:
					_shots = _g.get('shots', ()) or ()
					if not _shots:
						return 0.0
					_s0 = _shots[0]
					_pp = _s0.get('piercingPower', (100, 100))
					try:
						_pen0 = float(_pp[0])
					except Exception:
						_pen0 = float(_pp or 100.0)
					_sh0 = _s0.get('shell', {})
					_dmg = _sh0.get('damage', (100, 100))
					try:
						_dmg0 = float(_dmg[0])
					except Exception:
						_dmg0 = float(_dmg or 100.0)
					_cal = float(_sh0.get('caliber', 75.0) or 75.0)
					_spd = float(_s0.get('speed', 600.0) or 600.0)
					_rld = max(1.5, float(_g.get('reloadTime', 6.0) or 6.0))
					_lvl = float(_g.get('level', 1) or 1)
					if 'SPG' in _vtags and 'AT-SPG' not in _vtags:
						return _lvl * 120.0 + _dmg0 * 0.5 + _cal
					_is_low_pen_derp = (_cal >= 75.0 and _pen0 <= 70.0 and _spd <= 500.0)
					_score = _lvl * 60.0 + _pen0 * 2.8 + _dmg0 * 0.65 + (_dmg0 / _rld) * 8.0 + _spd * 0.08
					if _is_low_pen_derp:
						_score -= 220.0
					return _score
				except Exception:
					return 0.0
			_vtags = getattr(vtype, 'tags', ()) or ()
			if len(eng_list) > 1:
				try: td.installComponent(eng_list[-1]['compactDescr'])
				except Exception: pass
			if len(rad_list) > 1:
				try: td.installComponent(rad_list[-1]['compactDescr'])
				except Exception: pass
			if tur_list:
				tur = tur_list[-1]
				guns = list(tur.get('guns', ()) or ())
				gun = max(guns, key=lambda _gg: _score_bot_gun_hard(_gg, _vtags)) if guns else None
				if tur is not None and gun is not None:
					try: td.installTurret(tur['compactDescr'], gun['compactDescr'])
					except Exception: pass
			LOG_DEBUG('BOT_LOADOUT_MODULES veh=%s tier=hard config=top_elite gun=%s hp=%d' % (
				_vname, str((getattr(td, 'gun', None) or {}).get('name', '?')), int(getattr(td, 'maxHealth', 0) or 0)))
	except Exception as _mod_err:
		LOG_DEBUG('BOT_LOADOUT_MODULES err veh=%s tier=%s: %s' % (_vname, tier, str(_mod_err)))


def _offh_pick_bot_optional_devices(td, tier):
	"""Point 12: Assign class-appropriate optional equipment to medium (1-2 slots) and hard (3 slots) bots
	without mutating C++ optionalDevices array (zero deadlock risk), and apply real gameplay bonuses
	(rammer -10% reload, aimingStabilizer -20% move bloom, enhancedAimDrives -10% aim time,
	improvedVentilation +5% crew level, coatedOptics +10% vision, camouflageNet +12% camo)."""
	if td is None:
		return
	import random
	_veh_name = 'unknown'
	try:
		_veh_name = str(getattr(getattr(td, 'type', None), 'name', 'unknown'))
	except Exception:
		pass
	if tier == 'easy':
		td._offh_equipment = ()
		td._offh_equip_reload_mult = 1.0
		td._offh_equip_aim_mult = 1.0
		td._offh_equip_stab_mult = 1.0
		td._offh_equip_crew_bonus = 0.0
		LOG_DEBUG('BOT_LOADOUT_EQUIP veh=%s tier=easy installed=0/3 slots -> none (freshly bought)' % _veh_name)
		return
	tags = getattr(getattr(td, 'type', None), 'tags', None) or ()
	if 'SPG' in tags:
		pool = ('rammer', 'enhancedAimDrives', 'camouflageNet')
	elif 'AT-SPG' in tags:
		pool = ('rammer', 'enhancedAimDrives', 'coatedOptics', 'camouflageNet')
	elif 'lightTank' in tags:
		pool = ('coatedOptics', 'aimingStabilizer', 'improvedVentilation', 'rammer')
	else:
		pool = ('rammer', 'aimingStabilizer', 'improvedVentilation', 'coatedOptics', 'enhancedAimDrives')
	if tier == 'medium':
		n_slots = 1 if random.random() < 0.60 else 2
		chosen = tuple(random.sample(pool, min(n_slots, len(pool))))
	else:
		chosen = tuple(pool[:3])
	td._offh_equipment = chosen
	td._offh_equip_reload_mult = 0.90 if 'rammer' in chosen else 1.0
	td._offh_equip_aim_mult = 0.90 if 'enhancedAimDrives' in chosen else 1.0
	td._offh_equip_stab_mult = 0.80 if 'aimingStabilizer' in chosen else 1.0
	td._offh_equip_crew_bonus = 0.05 if 'improvedVentilation' in chosen else 0.0
	LOG_DEBUG('BOT_LOADOUT_EQUIP veh=%s tier=%s installed=%d/3 slots -> %s' % (
		_veh_name, tier, len(chosen), ', '.join(chosen)))
	return
	try:
		import items.vehicles as iv
		num_slots = len(getattr(td, 'optionalDevices', ()) or ())
		if num_slots <= 0:
			LOG_DEBUG('BOT_LOADOUT_EQUIP veh=%s tier=%s: 0 optionalDevices slots on this '
				'descriptor, nothing to install' % (_veh_name, tier))
			return
		device_cache = iv.g_cache.optionalDevices()
		if not device_cache:
			LOG_DEBUG('BOT_LOADOUT_EQUIP veh=%s tier=%s: g_cache.optionalDevices() came '
				'back empty - client cache not ready yet?' % (_veh_name, tier))
			return
		# Preference order: the classic "veteran loadout" pieces, cheapest and
		# most universally mountable first so an easy mayInstall check succeeds
		# on as many tanks as possible before falling back to whatever else fits.
		# v4.60: an SPG puts the camo net FIRST - a real veteran arty player's
		# top equipment priority is staying unseen, not optics it barely needs
		# from a static firing position. The old flat order put camo net 4th
		# for everyone, so a medium-tier arty (which only fills 1 slot) would
		# get coated_optics instead and never see a net at all; hard tier (all
		# slots) eventually got there anyway, but only by luck of slot count.
		_is_spg_td = False
		try:
			_is_spg_td = 'SPG' in (getattr(getattr(td, 'type', None), 'tags', None) or ())
		except Exception:
			pass
		if _is_spg_td:
			_preferred_name_tokens = (
				'camouflagenet', 'coated_optics', 'binocular', 'stereoscope',
				'toolbox', 'improvedvent', 'ventilation', 'improvedaiming')
		else:
			_preferred_name_tokens = (
				'coated_optics', 'binocular', 'stereoscope', 'camouflagenet',
				'toolbox', 'improvedvent', 'ventilation', 'improvedaiming')
		import random
		candidate_ids = list(device_cache.keys())
		random.shuffle(candidate_ids)
		def _device_sort_key(dev_id):
			try:
				dev_name = str(getattr(device_cache[dev_id], 'name', '') or '').lower()
			except Exception:
				dev_name = ''
			for _rank, _token in enumerate(_preferred_name_tokens):
				if _token in dev_name:
					return _rank
			return len(_preferred_name_tokens)
		candidate_ids.sort(key=_device_sort_key)
		slots_to_fill = 1 if tier == 'medium' else num_slots
		installed = 0
		installed_names = []
		used_slots = set()
		_mayinstall_rejections = 0
		for dev_id in candidate_ids:
			if installed >= slots_to_fill:
				break
			try:
				device = device_cache[dev_id]
				compact_descr = getattr(device, 'compactDescr', None)
				if compact_descr is None:
					continue
				placed = False
				for slot_idx in range(num_slots):
					if slot_idx in used_slots:
						continue
					try:
						if not td.mayInstallOptionalDevice(compact_descr, slot_idx):
							_mayinstall_rejections += 1
							continue
						td.installOptionalDevice(compact_descr, slot_idx)
						used_slots.add(slot_idx)
						placed = True
						break
					except Exception as _install_err:
						LOG_DEBUG('BOT_LOADOUT_EQUIP install err dev=%s slot=%s: %s' % (
							str(dev_id), str(slot_idx), str(_install_err)))
						continue
				if placed:
					installed += 1
					try:
						installed_names.append(str(getattr(device, 'name', dev_id)))
					except Exception:
						installed_names.append(str(dev_id))
			except Exception as _dev_err:
				LOG_DEBUG('BOT_LOADOUT_EQUIP candidate err dev=%s: %s' % (str(dev_id), str(_dev_err)))
				continue
		if installed > 0:
			LOG_DEBUG('BOT_LOADOUT_EQUIP veh=%s tier=%s installed=%d/%d slots -> %s '
				'(mayInstall rejections=%d)' % (
					_veh_name, tier, installed, num_slots, ', '.join(installed_names),
					_mayinstall_rejections))
		else:
			LOG_DEBUG('BOT_LOADOUT_EQUIP veh=%s tier=%s: 0 devices installed out of %d '
				'candidates tried (mayInstall rejections=%d) - bot stays bare' % (
					_veh_name, tier, len(candidate_ids), _mayinstall_rejections))
	except Exception as _equip_err:
		# No g_cache, no optionalDevices() API, anything - stay bare rather than
		# risk the mutation half-succeeding on an inconsistent td.
		LOG_DEBUG('BOT_LOADOUT_EQUIP veh=%s tier=%s: top-level failure, bot stays bare: %s' % (
			_veh_name, tier, str(_equip_err)))


def _offh_pick_bot_camouflage(td, tier):
	"""Best-effort td.setCamouflage() for a bot's VehicleDescr, driven by tier:
	easy never gets camo (just bought), medium ~40% chance, hard ~90% chance.
	Whether this is actually visible on the bot's model depends on the bot's
	own model-build path picking td.camouflages up (see the v4.43 changelog
	entry - the ONLY existing camo-drawing code in this file is the player's
	hangar-build block, which the bots never go through); setting it here is
	still correct and cheap even where nothing draws it, and costs nothing if
	the draw path never appears.
	"""
	_veh_name = 'unknown'
	try:
		_veh_name = str(getattr(getattr(td, 'type', None), 'name', 'unknown'))
	except Exception:
		pass
	try:
		import random
		if tier == 'easy':
			LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=easy -> no camo (no roll attempted)' % _veh_name)
			return
		elif tier == 'medium':
			_camo_roll = random.random()
			if _camo_roll >= 0.40:
				LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=medium roll=%.2f >= 0.40 -> no camo' % (
					_veh_name, _camo_roll))
				return
		else:
			_camo_roll = random.random()
			if _camo_roll >= 0.90:
				LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=hard roll=%.2f >= 0.90 -> no camo' % (
					_veh_name, _camo_roll))
				return
		import items.vehicles as iv
		nation_id = td.type.id[0]
		cust = iv.g_cache.customization(nation_id)
		if not cust:
			LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=%s: g_cache.customization(%s) came back '
				'empty' % (_veh_name, tier, str(nation_id)))
			return
		camos = cust.get('camouflages')
		if not camos:
			LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=%s: nation %s customization has no '
				"'camouflages' key" % (_veh_name, tier, str(nation_id)))
			return
		own_compact = td.type.compactDescr
		candidate_ids = []
		for camo_id, descr in camos.items():
			try:
				allow = descr.get('allow') or frozenset()
				deny = descr.get('deny') or frozenset()
				if own_compact in deny:
					continue
				if allow and own_compact not in allow:
					continue
				candidate_ids.append(camo_id)
			except Exception:
				continue
		if not candidate_ids:
			LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=%s: 0 of %d nation camos allow this '
				'vehicle (allow/deny lists) - no camo applied' % (
					_veh_name, tier, len(camos)))
			return
		try:
			num_seasons = len(getattr(td, 'camouflages', ()) or ())
		except Exception:
			num_seasons = 3
		_seasons_set = 0
		_applied_camos = []
		for kind in range(max(1, num_seasons)):
			kind_candidates = [cid for cid in candidate_ids if camos.get(cid, {}).get('kind') == kind]
			if not kind_candidates:
				continue
			cid = random.choice(kind_candidates)
			try:
				# 0.8.2 VehicleDescr.setCamouflage requires:
				# 1) position == descr['kind'] (season 0=winter, 1=summer, 2=desert)
				# 2) startTime >= _CUSTOMIZATION_EPOCH (1306886400)
				# 3) 0 <= durationDays <= 255 (0 = permanent)
				td.setCamouflage(kind, cid, 1306886400, 0)
				_seasons_set += 1
				_applied_camos.append(cid)
			except Exception as _season_err:
				LOG_DEBUG('BOT_LOADOUT_CAMO setCamouflage err veh=%s kind=%s camo=%s: %s' % (
					_veh_name, str(kind), str(cid), str(_season_err)))
		LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=%s applied to %d/%d season slots (camos=%s, candidates=%d)' % (
			_veh_name, tier, _seasons_set, max(1, num_seasons), str(_applied_camos),
			len(candidate_ids)))
	except Exception as _camo_err:
		LOG_DEBUG('BOT_LOADOUT_CAMO veh=%s tier=%s: top-level failure, no camo applied: %s' % (
			_veh_name, tier, str(_camo_err)))


def _offh_apply_bot_loadout(td, forced_tier=None):
	"""Master entry point (v4.43): roll a tier for this bot descriptor and, if
	bot_loadout_by_difficulty is on, dress it up (equipment + camo) to match -
	an easy bot stays a bare just-bought tank, a hard bot gets a veteran's
	kit. Call this ONCE, right after a bot VehicleDescr is constructed (both
	spawn sites: manual O/P/L and the auto-spawn lineup), before the descriptor
	is handed to anything that builds a model or caches it. Stashes the tier on
	the descriptor itself (td._offh_tier) so the first-shot skill roll and the
	per-bot crew_level roll can read it back later instead of re-rolling.

	Descriptors are cached and REUSED across every bot that drives the same
	tank in a given battle (see _offh_vehicle_descriptors) - this function only
	runs the first time a given td is built, so every bot sharing that tank
	type shares one tier/equipment/camo loadout. Per-bot variety still comes
	from the aim/reload jitter (bot_skill_variety) and from each bot's own
	crew_level roll, both of which are per-MOCK, not per-descriptor.
	"""
	if td is None:
		LOG_DEBUG('BOT_LOADOUT called with td=None - nothing to do')
		return
	_veh_name = 'unknown'
	try:
		_veh_name = str(getattr(getattr(td, 'type', None), 'name', 'unknown'))
	except Exception:
		pass
	_bgen_ld = int(globals().get('g_offh_battle_gen', 0) or 0)
	_max_bt_ld = int(globals().get('g_offh_max_battle_tier', 0) or 0)
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _CFG_LD0
		_cfg_d_ld = 'hard'
	except Exception:
		_cfg_d_ld = 'hard'
	_ld_stamp = (_bgen_ld, _cfg_d_ld, _max_bt_ld, str(forced_tier or ''))
	if getattr(td, '_offh_tier', None) is not None and getattr(td, '_offh_tier_stamp', None) == _ld_stamp:
		LOG_DEBUG('BOT_LOADOUT veh=%s: descriptor already loaded out (tier=%s), skipping '
			're-roll - this td is shared/cached' % (_veh_name, str(td._offh_tier)))
		return  # already loaded out for this battle & difficulty
	_veh_lvl = getattr(getattr(td, 'type', None), 'level', None) or getattr(td, 'level', 5)
	tier = 'hard'
	try:
		td._offh_tier = tier
		td._offh_tier_stamp = _ld_stamp
	except Exception as _stash_err:
		# Some VehicleDescr builds may not allow new attributes; without a
		# place to stash the tier there's nothing further worth doing here.
		LOG_NOTE('BOT_LOADOUT veh=%s tier=%s: could not stash td._offh_tier (%s) - '
			'this bot will re-roll its tier lazily on first shot instead, and gets '
			'no equipment/camo pass at all' % (_veh_name, tier, str(_stash_err)))
		return
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _CFG_LOADOUT
		loadout_enabled = bool(_CFG_LOADOUT.get('bot_loadout_by_difficulty', True))
	except Exception:
		loadout_enabled = True
	if not loadout_enabled:
		LOG_NOTE('BOT_LOADOUT veh=%s tier=%s: bot_loadout_by_difficulty is off - tier '
			'stashed for gunnery, no equipment/camo pass' % (_veh_name, tier))
		return
	try:
		_offh_upgrade_bot_components(td, tier)
	except Exception as _upg_err:
		LOG_DEBUG('BOT_LOADOUT upgrade err: %s' % str(_upg_err))
	try:
		_offh_pick_bot_optional_devices(td, tier)
	except Exception as _equip_call_err:
		LOG_NOTE('BOT_LOADOUT veh=%s tier=%s: _offh_pick_bot_optional_devices raised '
			'past its own guard: %s' % (_veh_name, tier, str(_equip_call_err)))
	try:
		_offh_pick_bot_camouflage(td, tier)
	except Exception as _camo_call_err:
		LOG_NOTE('BOT_LOADOUT veh=%s tier=%s: _offh_pick_bot_camouflage raised past '
			'its own guard: %s' % (_veh_name, tier, str(_camo_call_err)))
	LOG_DEBUG('BOT_LOADOUT DONE veh=%s tier=%s (see BOT_LOADOUT_EQUIP/BOT_LOADOUT_CAMO '
		'lines above for the actual equipment/camo outcome)' % (_veh_name, tier))


def _offh_native_eligible(mock):
	return (mock is not None and not (
		bool(getattr(mock, '_network_remote', False)) and
		not bool(getattr(mock, '_network_shared_bot', False))))


def _offh_native_movement_required(player, mock, role=None):
	"""Latch strict native movement only after this process owns the bot."""
	if mock is None:
		return False
	try:
		if _offh_is_sandbox_machinima_mode():
			_rm_nm = _get_replay_machinima().get_replay_manager()
			if _rm_nm.playing_replay or _rm_nm.has_pending_cli_autostart():
				return False
	except Exception:
		pass
	if bool(getattr(mock, '_offh_native_movement_required', False)):
		return True
	if not _offh_native_mode_enabled() or not _offh_native_eligible(mock):
		return False
	if role is None:
		role = _offh_network_bot_role(player)
	if role not in ('local', 'authority'):
		return False
	position = getattr(mock, 'position', None)
	try:
		fail_pose = (
			float(position.x), float(position.y), float(position.z),
			float(getattr(mock, 'yaw', 0.0) or 0.0),
			float(getattr(mock, 'pitch', 0.0) or 0.0),
			float(getattr(mock, 'roll', 0.0) or 0.0))
		setattr(mock, '_offh_native_fail_pose', fail_pose)
	except Exception:
		fail_pose = None
	# A relay proxy may have been created before this client was promoted. Remove
	# its legacy static shape before attaching the native rigid body.
	try:
		mock._collision_obstacle = None
	except Exception:
		pass
	setattr(mock, '_offh_native_movement_required', True)
	return True


def _offh_python_movement_allowed(player, mock, role=None):
	"""The native experiment never authorizes legacy bot kinematics."""
	return False


def release_native_bots_for_replica(player):
	"""Synchronously release native owners before one demotion snapshot applies."""
	try:
		from gui.mods.offhangar import physics_core as manager
	except Exception:
		return False
	try:
		mocks = globals().get('G_MOCK_VEHICLES', {}) or {}
		# Release every claimed body before refreshing any relay presentation.
		# A partial pass must not re-fashion early bots and then fail on a later
		# native owner while the authority role is still unchanged.
		targets = list(mocks.values())
		try:
			targets.sort(key=lambda item: int(getattr(item, 'id', 0) or 0))
		except Exception:
			pass
		for mock in targets:
			if not getattr(mock, '_network_shared_bot', False):
				continue
			claimed = bool(manager.claims_movement(mock))
			if claimed and manager.is_prepared(mock):
				mock._offh_native_replica_refresh_pending = True
			if claimed and not manager.stop_mock(mock, True):
				return False
		for mock in targets:
			if not bool(getattr(
					mock, '_offh_native_replica_refresh_pending', False)):
				continue
			refresh_fashion = getattr(mock, '_offh_attach_bot_fashion', None)
			if callable(refresh_fashion):
				refresh_fashion()
			mock._offh_native_replica_refresh_pending = False
		# The expanded range belongs to the simulation authority. Restore it only
		# after every native owner has been released; a partial demotion must retain
		# collision for the bodies that are still authoritative on this client.
		streaming_bootstrap = getattr(
			player, '_offh_spawn_streaming_bootstrap', None)
		if (streaming_bootstrap is not None and
				streaming_bootstrap.stop() is not True):
			return False
		player._offh_spawn_streaming_bootstrap = None
		player._offh_spawn_streaming_monitor_active = False
		player._offhangar_native_replica_released = True
		return True
	except Exception as error:
		try:
			from gui.mods.offhangar.logging import LOG_ERROR as _release_error
			_release_error('NATIVE_BOT_PHYSICS demotion failed: %s' % str(error))
		except Exception:
			pass
		return False


# Wreck release strategy (config: wreck_freeze_mode, wreck_defer_seconds).
#
# 'guard' (shipped) - guard_fault() freezes the body AND faults it, which starts
#   the wreck/detach transaction.  Crashed natively on 01.10 right after the
#   'wreck freeze' line: 0xC0000005 @ 0x00E78498, a NULL-owner smart-pointer
#   assignment (refcount +/- at +0x4 into [this+0x18], this == NULL).  An
#   earlier session already lost the pushable-wreck variant the same way
#   (0x0090A3EA, see the dead `if False:` switch below).
# 'idle'   - physics_core.mark_wreck(): the documented pushable-wreck primitive.
#   Zero drive inputs, WGVehiclePhysics2 stays LIVE in the batch (shovable, can
#   fall and slide), the entity's WGVehicleFilter2 is detached (that detach is
#   what prevents 0x00E78498 per mark_wreck's own docstring) and state['wreck']
#   is set, which enables wreck_pose() -> the per-frame Servo sync that makes the
#   visible wreck follow the body.  THIS IS THE MODE TO USE.
# 'sleep'  - physics_core.sleep_mock(): isFrozen = True, phase stays 'active',
#   nothing is faulted or detached, and the body keeps its exact pose (the 1:1
#   requirement: no re-seed, so the tank cannot jump when it dies).  Wake is
#   physics_core.wake_mock(), after which gravity/suspension/collision act
#   again, so a wreck can be pushed, fall and slide.  Falls back to 'guard' if
#   the sleep readback fails.
# 'defer'  - the same 'guard' freeze, but only after wreck_defer_seconds: this
#   function returns False until the delay passes and
#   _offh_wreck_release_or_retry keeps re-asking every 0.1 s (20 attempts).
#   Tests whether the crash is a race with the death FX / model swap.
# 'stop'   - skip the freeze and hand the body to stop_mock().  Documented cost:
#   the wreck snaps to the bind pose and loses collision.  Diagnostic value: it
#   says whether the crash belongs to the freeze or to the swap.
_OFFH_MARKER_REASONS = {'gen': None, 'on': False, 'idx': {}}


def _offh_marker_reasons_on():
	st = _OFFH_MARKER_REASONS
	gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	if st['gen'] != gen:
		st['gen'] = gen
		try:
			from gui.mods.offhangar._constants import CONFIG_OPTIONS as _MR_CFG
			st['on'] = bool(_MR_CFG.get('marker_damage_reasons', False))
		except Exception:
			st['on'] = False
		idx = {'shot': 0, 'fire': 1, 'ramming': 2, 'world_collision': 3}
		src = 'fallback'
		try:
			import constants as _MR_C
			reasons = tuple(getattr(_MR_C, 'ATTACK_REASONS', ()) or ())
			for name in ('shot', 'fire', 'ramming', 'world_collision'):
				if name in reasons:
					idx[name] = reasons.index(name)
			if reasons:
				src = 'constants:%s' % ','.join([str(r) for r in reasons])
		except Exception:
			pass
		st['idx'] = idx
		LOG_DEBUG('MARKER_REASONS_CFG on=%s fire=%d ramming=%d src=%s' % (
			'yes' if st['on'] else 'no', idx['fire'], idx['ramming'], src))
	return st['on']


def _offh_marker_reason(kind):
	"""attackReasonID for the marker: 0 unless the flag is on and kind is known."""
	try:
		if _offh_marker_reasons_on():
			return int(_OFFH_MARKER_REASONS['idx'].get(kind, 0))
	except Exception:
		pass
	return 0


def _offh_marker_hp(mock, hp=None):
	"""Health for vMarkersManager.onVehicleHealthChanged: max(0, hp), but -1 for an
	ammo-rack kill (flag on) so the swf draws the blow-up symbol, sent once."""
	try:
		value = getattr(mock, 'health', 0) if hp is None else hp
		value = int(value or 0)
		if (value <= 0 and getattr(mock, '_ammo_rack_death', False) and
				not getattr(mock, '_offh_marker_blowup_sent', False) and
				_offh_marker_reasons_on()):
			mock._offh_marker_blowup_sent = True
			LOG_NOTE('MARKER_BLOWUP id=%s' % str(getattr(mock, 'id', '?')))
			return -1
		return max(0, value)
	except Exception:
		try:
			return max(0, int(getattr(mock, 'health', 0) or 0))
		except Exception:
			return 0


_OFFH_WRECK_CFG = {}


_OFFH_WRECK_TRACE = [None]


def _offh_wreck_trace(step):
	"""Bisect the wreck swap after a native crash (config: wreck_step_trace).

	The client died at 0xC0000005 @ 0x00E78498 right after WRECK_SWAP in both
	'guard' and 'idle' modes, so the freeze was NOT the culprit - something in the
	model swap is.  A native crash takes the log buffer with it, so each step is
	written AND flushed: the last WRECK_STEP line in python.log names the step
	that killed the client.  Same method that located the hangar-exit crash.
	"""
	if _OFFH_WRECK_TRACE[0] is None:
		try:
			from gui.mods.offhangar._constants import CONFIG_OPTIONS as _WT_CFG
			_OFFH_WRECK_TRACE[0] = bool(_WT_CFG.get('wreck_step_trace', False))
		except Exception:
			_OFFH_WRECK_TRACE[0] = False
	if not _OFFH_WRECK_TRACE[0]:
		return
	try:
		LOG_NOTE('WRECK_STEP %s' % step)
		import BigWorld as _BWt
		_BWt.flushPythonLog()
	except Exception:
		pass


_OFFH_GUI_TRACE = {'gen': None, 'on': False, 'n': 0}


def _offh_gui_trace_on():
	''' flag `gui_step_trace`, cached per battle generation (the
	`wreck_step_trace` idiom, `_offh_wreck_trace` at :617-641).'''
	st = _OFFH_GUI_TRACE
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if st.get('gen') == gen:
		return st['on']
	on = False
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _GT_CFG
		on = bool(_GT_CFG.get('gui_step_trace', False))
	except Exception:
		on = False
	st['gen'] = gen
	st['on'] = on
	if on:
		try:
			LOG_DEBUG('GUI_TRACE_CFG on=yes gen=%d' % gen)
		except Exception:
			pass
	return on


def _offh_gui_step(tag, flush=True):
	'''bisect a native crash by bracketing GUI/native calls.
	
	A native crash takes the log buffer with it - that is documented in the
	`wreck_step_trace` docstring at :618-625 ("A native crash takes the log
	buffer with it, so each step is written AND flushed"), and it is how the
	hangar-exit crash was located. So after a crash the last `GUI_STEP pre=...`
	without its `post=` names the call that killed the client.
	
	Log only: no behaviour change, never raises. Cheap by construction - one dict
	lookup when the flag is off, and it sits on EVENTS (chat, markers, minimap,
	camera shake, the per-battle sway setup), never inside the frame loop.
	'''
	try:
		if not _offh_gui_trace_on():
			return
		_OFFH_GUI_TRACE['n'] = int(_OFFH_GUI_TRACE.get('n', 0) or 0) + 1
		LOG_NOTE('GUI_STEP %s n=%d' % (tag, _OFFH_GUI_TRACE['n']))
		if flush:
			import BigWorld as _BWg
			_BWg.flushPythonLog()
	except Exception:
		pass

_OFFH_SHOP_DEFER = {'gen': None, 'on': False}


def _offh_shop_cb_defer():
	''' flag `shop_cb_defer`, cached per battle generation.
	
	Off (shipped default) the stock requester callback runs exactly where it runs
	today. On, it is handed to the next frame with BigWorld.callback(0.0, ...) so a
	crash inside the stock GUI code that processes a shop response cannot happen
	inside the requester's response path. Diagnostic step K, not a fix.'''
	st = _OFFH_SHOP_DEFER
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if st.get('gen') == gen:
		return st['on']
	on = False
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _SD_CFG
		on = bool(_SD_CFG.get('shop_cb_defer', False))
	except Exception:
		on = False
	st['gen'] = gen
	st['on'] = on
	if on:
		try:
			LOG_DEBUG('SHOP_CB_DEFER_CFG on=yes gen=%d' % gen)
		except Exception:
			pass
	return on


def _offh_shop_cb_info(label, a, k):
	'''b: one cheap line describing what the stock callback is about to get.
	
	Reads only the top level of the first dict argument (responseCode / item type),
	never walks into the payload, never raises: a diagnostic must not be able to
	change what it measures.'''
	try:
		parts = ['lbl=%s argc=%d' % (label, len(a))]
		for v in list(a)[:2]:
			if isinstance(v, dict):
				for key in ('responseCode', 'code', 'resCode'):
					if key in v:
						parts.append('%s=%r' % (key, v[key]))
				for key in ('itemType', 'type', 'cd', 'vehTypeCompDescr'):
					if key in v:
						parts.append('%s=%s' % (key, type(v[key]).__name__))
				break
			parts.append('t=%s' % type(v).__name__)
		return ' '.join(parts)
	except Exception:
		return 'info=err'


_OFFH_MARKER_FIX = {'gen': None, 'on': False, 'skipped_vmk': 0, 'skipped_vmm': 0}


def _offh_marker_fix_on():
	""" flag `marker_lifecycle_once`, cached per battle generation.

	Measured balance of the carousel: createMarker 2605 x type=vmk against
	destroyMarker 2604 x type=spvm.  `_vmk` looks at the spot flag only, `_spvm`
	at spot AND distance <= max_draw_distance, so every spotted bot further than
	450 m is created by one manager and destroyed by the other, every tick, and
	the handles that `_vmk` wrote into `m_veh.marker` are lost.  With this flag
	the `_vmk` block is skipped whole and the marker half of the `_vmm` block is
	skipped apart - its minimap sync stays, because `_spmm` is idempotent and the
	icons must keep moving.  `_spvm` then owns create/destroy alone.
	Skips are counted, so "flag on" and "the branch was really skipped" are two
	different statements in the log (РЕЦЕНЗИЯ_d98_d99 §5.4).
	"""
	st = _OFFH_MARKER_FIX
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if st.get('gen') == gen:
		return st['on']
	on = False
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _MLF_CFG
		on = bool(_MLF_CFG.get('marker_lifecycle_once', True))
	except Exception:
		on = True
	st['gen'] = gen
	st['on'] = on
	try:
		LOG_DEBUG('MARKER_FIX_CFG on=%s gen=%d skipped_vmk=%d skipped_vmm=%d' % (
			('yes' if on else 'no'), gen, st.get('skipped_vmk', 0), st.get('skipped_vmm', 0)))
	except Exception:
		pass
	return on


_OFFH_MK_LIVE = {}
_OFFH_MK_SEEN = {'create': 0, 'destroy': 0, 'stray': 0, 'double': 0}
_OFFH_MK_GEN = [-1]
