def _offh_bot_disp_tick(m_veh, td, now, aim_time_mult=1.0):
	"""advance one bot's dispersion factor (1.0 = fully aimed). Returns it."""
	import math
	t_prev = getattr(m_veh, '_offh_bd_t', None)
	pos = getattr(m_veh, 'position', None)
	yaw = float(getattr(m_veh, 'yaw', 0.0) or 0.0)
	tyaw = float(getattr(m_veh, '_turret_yaw', 0.0) or 0.0)
	cur = float(getattr(m_veh, '_offh_bd_f', 1.35) or 1.35)
	if pos is None:
		return cur
	p = (float(pos[0]), float(pos[1]), float(pos[2]))
	if t_prev is None:
		m_veh._offh_bd_t, m_veh._offh_bd_p, m_veh._offh_bd_y, m_veh._offh_bd_ty = now, p, yaw, tyaw
		m_veh._offh_bd_f = cur
		return cur
	dt = float(now) - float(t_prev)
	if dt <= 1e-3:
		return cur
	dt = min(dt, 0.5)
	pp = m_veh._offh_bd_p
	v = math.sqrt((p[0] - pp[0]) ** 2 + (p[2] - pp[2]) ** 2) / dt
	def _ad(a, b):
		d = a - b
		while d > math.pi: d -= 2.0 * math.pi
		while d < -math.pi: d += 2.0 * math.pi
		return abs(d)
	rv = _ad(yaw, m_veh._offh_bd_y) / dt
	tv = _ad(tyaw, m_veh._offh_bd_ty) / dt
	m_veh._offh_bd_t, m_veh._offh_bd_p, m_veh._offh_bd_y, m_veh._offh_bd_ty = now, p, yaw, tyaw
	if v > 60.0 or v < 0.25:
		v = 0.0
	if rv < 0.05:
		rv = 0.0
	if tv < 0.05:
		tv = 0.0
	cm, cr, gt, aim_time = 0.12, 0.12, 0.10, 2.0
	try:
		cm, cr = td.chassis['shotDispersionFactors']
		g = td.gun
		gdf = g['shotDispersionFactors'] if isinstance(g, dict) else g.shotDispersionFactors
		gt = float(gdf['turretRotation'])
		aim_time = float(g.get('aimingTime', 2.0) if isinstance(g, dict) else getattr(g, 'aimingTime', 2.0))
	except Exception:
		pass
	# items/vehicles.pyc already converts cm (per m/s), cr (per rad/s), and gt (per rad/s).
	# For SPGs aiming from stationary ambush, fine tracking traverse should not blow dispersion to 6.5x!
	_is_spg_bd = False
	try:
		_is_spg_bd = ('SPG' in getattr(td.type, 'tags', ()))
	except Exception:
		pass
	# v7.6: Genuine hull & turret traverse bloom (and target-switch bloom) for SPGs and all bots!
	_cur_tid_bd = getattr(m_veh, '_ai_target_id', None)
	_prev_tid_bd = getattr(m_veh, '_offh_bd_tid', None)
	if _cur_tid_bd != _prev_tid_bd:
		m_veh._offh_bd_tid = _cur_tid_bd
		if _cur_tid_bd is not None:
			cur = max(float(cur), 2.4 if _is_spg_bd else 1.38)
	if _is_spg_bd:
		if v < 0.85:
			cr = float(cr) * (0.30 if rv < 0.08 else 0.95)
			gt = float(gt) * (0.30 if tv < 0.08 else 0.95)
	else:
		cm = float(cm) * 0.65
		cr = float(cr) * (0.25 if (v < 0.85 and rv < 0.15) else 0.52)
		gt = float(gt) * (0.22 if (v < 0.85 and tv < 0.18) else 0.48)
	target = min(4.8 if _is_spg_bd else 2.35, math.sqrt(1.0 + (v * float(cm)) ** 2 + (rv * float(cr)) ** 2 + (tv * float(gt)) ** 2))
	eff_aim = max(0.26, aim_time * (0.55 if _is_spg_bd else 0.38) * float(aim_time_mult or 1.0))
	if cur > target:
		cur = target + (cur - target) * math.exp(-dt / eff_aim)
	else:
		cur = min(4.8 if _is_spg_bd else 2.35, target)
	m_veh._offh_bd_f = cur
	m_veh._offh_bd_tgt = target
	m_veh._offh_bd_v = v
	return cur


def _offh_bot_disp_after_shot(m_veh, td):
	try:
		g = td.gun
		gdf = g['shotDispersionFactors'] if isinstance(g, dict) else g.shotDispersionFactors
		after = float(gdf.get('afterShot', 1.5) if hasattr(gdf, 'get') else 1.5)
	except Exception:
		after = 1.5
	m_veh._offh_bd_f = min(6.0, float(getattr(m_veh, '_offh_bd_f', 1.0) or 1.0) * max(1.0, after))


def _offh_reaction_blocks(m_veh, target_id, fire_allowed, now):
	"""True while this bot is still 'noticing' its target (flag `bot_reaction_time`).

	State on the mock: _offh_react_tid (target the delay belongs to),
	_offh_react_until (trigger unlocks), _offh_react_seen (last time firing was
	allowed on that target), _offh_react_bias (personal 0.85-1.2).
	"""
	try:
		on, profiles = _offh_reaction_cfg()
		if not on or target_id is None:
			return False
		if not fire_allowed:
			return False
		last_tid = getattr(m_veh, '_offh_react_tid', None)
		last_seen = float(getattr(m_veh, '_offh_react_seen', -999.0))
		fresh = last_tid != target_id
		reacquire = (not fresh) and (now - last_seen >= 2.0)
		if fresh or reacquire:
			import random
			bias = getattr(m_veh, '_offh_react_bias', None)
			if bias is None:
				bias = random.uniform(0.85, 1.2)
				m_veh._offh_react_bias = bias
			tier = str(getattr(m_veh, '_offh_skill', {}).get('tier', 'hard')).lower()
			lo, hi = profiles.get(tier, profiles['medium'])
			delay = random.uniform(lo, hi) * bias
			if reacquire:
				delay *= 0.6
			m_veh._offh_react_tid = target_id
			m_veh._offh_react_until = now + delay
			LOG_NOTE('REACT id=%s tier=%s tid=%s kind=%s delay=%.2f' % (
				str(getattr(m_veh, 'id', '?')), tier, str(target_id),
				'fresh' if fresh else 'reacquire', delay))
		m_veh._offh_react_seen = now
		return now < float(getattr(m_veh, '_offh_react_until', 0.0))
	except Exception:
		return False


_OFFH_HAZARD_CFG = {}
_OFFH_HAZARD_CD_CFG = {}


def _offh_hazard_timeout():
	"""Seconds a hazard recovery may hold a bot before we give up (0 = never).

	Cached per battle generation like the other tunables.
	"""
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if _OFFH_HAZARD_CFG.get('gen') == gen:
		return _OFFH_HAZARD_CFG['secs']
	secs = 0.0
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _HZ_CFG
		secs = float(_HZ_CFG.get('hazard_timeout_seconds', 0.0) or 0.0)
	except Exception:
		secs = 0.0
	if secs < 0.0:
		secs = 0.0
	elif secs > 120.0:
		secs = 120.0
	_OFFH_HAZARD_CFG['gen'] = gen
	_OFFH_HAZARD_CFG['secs'] = secs
	try:
		LOG_DEBUG('HAZARD_CFG timeout_seconds=%.1f (%s)' % (
			secs, 'off, old behaviour' if secs <= 0.0 else 'give up and drive on'))
	except Exception:
		pass
	return secs


def _offh_hazard_cooldown():
	"""Seconds a bot ignores hazards after a recovery TIMEOUT (0 = off).

	A timeout only resets the BOT's own state - the baked navigation grid still
	reports the same cell as unsafe - so without a cooldown the bot re-enters
	recovery on the very next frame and is held for another full timeout.
	Cached per battle generation like _offh_hazard_timeout().
	"""
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if _OFFH_HAZARD_CD_CFG.get('gen') == gen:
		return _OFFH_HAZARD_CD_CFG['secs']
	secs = 0.0
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _HZ_CD_CFG
		secs = float(_HZ_CD_CFG.get('hazard_retrigger_cooldown_seconds', 0.0) or 0.0)
	except Exception:
		secs = 0.0
	if secs < 0.0:
		secs = 0.0
	elif secs > 60.0:
		secs = 60.0
	_OFFH_HAZARD_CD_CFG['gen'] = gen
	_OFFH_HAZARD_CD_CFG['secs'] = secs
	try:
		LOG_DEBUG('HAZARD_CD_CFG retrigger_cooldown_seconds=%.1f (%s)' % (
			secs, 'off, old behaviour' if secs <= 0.0 else 'ignore hazards after a timeout'))
	except Exception:
		pass
	return secs


def _offh_tilt_text(obj):
	"""'p=.. r=..' from anything exposing pitch/roll, else its type name.

	A motor-driven chassis returns a MatrixProvider from model.matrix, which has
	neither - reading .pitch blindly lost the whole WRECK_TILT reading.
	"""
	try:
		if obj is None:
			return 'none'
		return 'p=%.4f r=%.4f' % (float(obj.pitch), float(obj.roll))
	except Exception:
		try:
			return type(obj).__name__
		except Exception:
			return 'err'


def _offh_tilt_text6(seq):
	"""'p=.. r=..' from a (x, y, z, yaw, pitch, roll) pose tuple."""
	try:
		if seq is not None and len(seq) >= 6:
			return 'p=%.4f r=%.4f' % (float(seq[4]), float(seq[5]))
	except Exception:
		pass
	return 'none'


def _offh_wreck_cfg():
	"""Return (mode, defer_seconds, detach_filter) for this battle."""
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if _OFFH_WRECK_CFG.get('gen') == gen:
		return _OFFH_WRECK_CFG['params']
	mode = 'guard'
	delay = 0.6
	detach = True
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _WRECK_CFG
		mode = str(_WRECK_CFG.get('wreck_freeze_mode', 'guard') or 'guard')
		delay = float(_WRECK_CFG.get('wreck_defer_seconds', 0.6) or 0.0)
		detach = bool(_WRECK_CFG.get('wreck_detach_filter', True))
	except Exception:
		mode = 'guard'
		delay = 0.6
		detach = True
	if mode not in ('guard', 'sleep', 'idle', 'defer', 'stop'):
		mode = 'guard'
	if delay < 0.0:
		delay = 0.0
	elif delay > 5.0:
		delay = 5.0
	_OFFH_WRECK_CFG['gen'] = gen
	_OFFH_WRECK_CFG['params'] = (mode, delay, detach)
	try:
		LOG_DEBUG('WRECK_CFG mode=%s defer_seconds=%.2f detach_filter=%s' % (
			mode, delay, 'yes' if detach else 'no'))
	except Exception:
		pass
	return _OFFH_WRECK_CFG['params']


_OFFH_FALL_METER = {'gen': None, 'on': False}


def _offh_bot_fall_meter_on():
	st = _OFFH_FALL_METER
	gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	if st['gen'] != gen:
		st['gen'] = gen
		try:
			from gui.mods.offhangar._constants import CONFIG_OPTIONS as _FM_CFG
			st['on'] = bool(_FM_CFG.get('bot_fall_meter', True))
		except Exception:
			st['on'] = False
		LOG_DEBUG('BOT_FALL_METER_CFG on=%s' % ('yes' if st['on'] else 'no'))
	return st['on']


def _offh_bot_fall_meter(m_veh, y, now, pitch=0.0, roll=0.0):
	"""Free-fall meter for an 'active' bot.  Returns the impact dict it stored in
	m_veh._offh_native_fall_impact (or None).  Never overwrites a pending impact."""
	try:
		if not _offh_bot_fall_meter_on():
			return None
		y = float(y)
		now = float(now)
		st = getattr(m_veh, '_offh_fm', None)
		if st is None:
			st = {'y': y, 't': now, 'vy': 0.0, 'ff': 0.0, 'vmin': 0.0, 'peak_y': y}
			m_veh._offh_fm = st
			return None
		dt = now - st['t']
		if dt <= 0.008:
			return None
		if dt > 0.25:
			st.update({'y': y, 't': now, 'vy': 0.0, 'ff': 0.0, 'vmin': 0.0, 'peak_y': y})
			return None
		vy = max(-35.0, min(35.0, (y - st['y']) / dt))
		acc = (vy - st['vy']) / dt
		result = None
		if acc < -8.2 and vy < -5.2:
			if st['ff'] <= 0.001:
				st['peak_y'] = max(y, float(st.get('y', y)))
			st['ff'] += dt
			st['vmin'] = min(st['vmin'], vy)
		elif st['ff'] >= 0.42 and (acc > 28.0 or vy > -1.0):
			import math as _fm_math
			actual_drop = max(0.0, float(st.get('peak_y', y)) - y)
			max_phys_impact = _fm_math.sqrt(2.0 * 9.81 * actual_drop)
			impact = min(-min(st['vmin'], st['vy']), max_phys_impact)
			st['ff'] = 0.0
			st['vmin'] = 0.0
			st['peak_y'] = y
			if actual_drop >= 2.6 and impact > 7.2 and not getattr(m_veh, '_offh_native_fall_impact', None):
				up = _fm_math.cos(float(pitch or 0.0)) * _fm_math.cos(float(roll or 0.0))
				att = 1.0 if up > 0.8 else (1.35 if up > 0.15 else 1.6)
				result = {'impact': impact, 'drop': actual_drop,
					'attitude': att, 'source': 'meter'}
				m_veh._offh_native_fall_impact = result
				LOG_NOTE('BOT_FALL_METER id=%s impact=%.1f drop=%.1f att=%.2f' % (
					str(getattr(m_veh, 'id', '?')), impact, result['drop'], att))
		elif vy > -1.0:
			st['ff'] = 0.0
			st['vmin'] = 0.0
			st['peak_y'] = y
		st['y'] = y
		st['t'] = now
		st['vy'] = vy
		return result
	except Exception:
		return None


def _offh_bot_fall_marker(m_veh):
	"""Push the bot's new HP to its marker after fall damage (flag bot_fall_meter)."""
	try:
		if not _offh_bot_fall_meter_on():
			return
		marker = getattr(m_veh, 'marker', None)
		if marker in (None, -1):
			return
		from gui import WindowsManager as _FM_WM
		bw = getattr(_FM_WM.g_windowsManager, 'battleWindow', None)
		if bw is not None and getattr(bw, 'vMarkersManager', None):
			_offh_vmm_update_health(
				bw.vMarkersManager, m_veh, max(0, int(getattr(m_veh, 'health', 0) or 0)), -1,
				_offh_marker_reason('world_collision'))
	except Exception:
		pass


_OFFH_WRECK_REBIND_CFG = {}


def _offh_wreck_rebind_cfg():
	"""Marker-rebind mode for the wreck model swap: 'immediate' or 'off'.

	'immediate' fires appearance.onModelChanged() right after the swap (today's
	behaviour, and the shipped default). 'off' skips it. Reason: session 03.10
	12:4x died with `0xC0000005 @ 0x00E78498 (Read @ 0x00000000)` and the last line
	in python.log was `WRECK_STEP 7_mock_rebound`; between that marker and
	`8_appearance_notified` the onModelChanged() call is the ONLY statement, and
	`try/except Exception` cannot catch a native access violation. An earlier wreck
	in the same battle (id=1025) survived its swap, so the crash is intermittent -
	the 01.10 "wrecks are fixed" result was not absolute.
	"""
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if _OFFH_WRECK_REBIND_CFG.get('gen') == gen:
		return _OFFH_WRECK_REBIND_CFG['mode']
	mode = 'off'
	_OFFH_WRECK_REBIND_CFG['gen'] = gen
	_OFFH_WRECK_REBIND_CFG['mode'] = mode
	try:
		LOG_DEBUG('WRECK_REBIND_CFG mode=%s' % mode)
	except Exception:
		pass
	return mode


def _offh_wreck_detach_after_swap_cfg():
	"""Detach the wreck entity from its native filter AFTER the model swap.

	mark_wreck() runs with detach_filter=False because detaching at mark time
	crashed (0xC0000005 @ 0x0090A3EA right after 1_swap_start). But the swap then
	nulls bw_entity.model and never reassigns it, leaving a live WGVehicleFilter2
	on a model-less entity for the rest of the battle - the documented AV hazard
	(0x00E78498 / 0xC66B43): one crash lottery ticket per wreck, which is what
	read as a "random mid-battle crash" (20th wreck, 12.10). Once the new wreck
	model is fully bound, detaching hits neither window: the entity goes inert,
	the body stays live+pushable in the shared batch, the python Servo drives
	the visual. Default true. Markers: WRECK_STEP 7b_detach_start/7c_detach_done.
	"""
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _DA_CFG
		return bool(_DA_CFG.get('wreck_detach_after_swap', True))
	except Exception:
		return True


def _offh_wreck_entity_model_cfg():
	"""Keep the wreck entity whole: give bw_entity the new wreck model at swap time.

	The swap nulls bw_entity.model (entity-owned chassis, delModel needs the null)
	and never reassigned it - a live WGVehicleFilter2 on a model-less entity for the
	rest of the battle was the 0xC66B43/0x00E78498 AV window (one lottery ticket per
	wreck; 12.10 died on the 20th). Detaching the filter instead is lethal at ANY
	timing (0x0090A3EA right after the swap, 13.10): the batch body still expects the
	entity binding. This flag takes the third road: nothing is detached, nothing is
	null - the entity gets the wreck model, so the native filter drives the wreck
	visual from the batch pose exactly like a live bot (fashion path), and the python
	Servo drive is skipped so they cannot fight. Default true. Marker: WRECK_STEP
	7x_entity_rebound. false = the old null-model behaviour (crash lottery).
	"""
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _EM_CFG
		return bool(_EM_CFG.get('wreck_entity_model', True))
	except Exception:
		return True


def _offh_release_native_for_wreck(mock):
	"""Keep a dead native body LIVE as a pushable wreck (fallback: freeze in place).

	A stop_mock() release handed the wreck back to the legacy Servo: the model
	snapped to the bind pose ("T-pose") and the corpse lost all collision, so
	live tanks drove straight through it. guard_fault() freezes the rigid body
	at its last validated pose and keeps it in the shared batch as a static
	obstacle; the wreck swap then only replaces the visuals. The PLAYER is
	exempt: his wreck swap strips chassis motors (native Servo included), so he
	still needs the full stop_mock() BEFORE the swap (the soft-lock fix).
	"""
	if mock is None:
		return True
	required = bool(getattr(mock, '_offh_native_movement_required', False))
	try:
		from gui.mods.offhangar import physics_core as manager
	except Exception:
		return not required
	try:
		if not manager.claims_movement(mock):
			return True
		_is_player_mock = False
		try:
			_pl = BigWorld.player()
			_is_player_mock = (getattr(mock, 'id', None) ==
				getattr(_pl, 'playerVehicleID', -2))
		except Exception:
			pass
		_wreck_mode, _wreck_delay, _wreck_detach = _offh_wreck_cfg()
		if not _is_player_mock:
			if _wreck_mode == 'defer':
				# Let DEATH_FX / the wreck model swap finish before freezing: the
				# 01.10 crash landed immediately after 'wreck freeze', and
				# physics_core:2536-2545 documents that wg_fashion dies with the
				# OLD model inside exactly this window.  Returning False makes
				# _offh_wreck_release_or_retry ask again in 0.1 s.
				try:
					_now_wr = float(BigWorld.time())
				except Exception:
					_now_wr = 0.0
				_asked_wr = getattr(mock, '_offh_wreck_release_asked_at', None)
				if _asked_wr is None:
					try:
						mock._offh_wreck_release_asked_at = _now_wr
					except Exception:
						pass
					_asked_wr = _now_wr
				try:
					_elapsed_wr = _now_wr - float(_asked_wr or 0.0)
				except Exception:
					_elapsed_wr = 0.0
				if _wreck_delay > 0.0 and _elapsed_wr < _wreck_delay:
					_offh_probe_note('wreck_deferred')
					return False
			elif _wreck_mode == 'stop':
				_offh_probe_note('wreck_stop_mode')
				return bool(manager.stop_mock(mock, False))
			elif _wreck_mode == 'idle':
				# The documented pushable-wreck primitive: physics_core.mark_wreck().
				# It zeroes the drive inputs, keeps WGVehiclePhysics2 LIVE in the
				# shared batch so a heavier tank can shove the corpse (and so it can
				# fall or slide), detaches the entity from its WGVehicleFilter2 - its
				# own docstring names our exact crash, 0x00E78498, as what happens
				# when a live filter meets a NULL model after the swap - and sets
				# state['wreck'], which is what enables wreck_pose() and therefore
				# the per-frame Servo sync (~17304) that makes the VISIBLE wreck
				# follow the physical body.  Without that flag the body stayed
				# touchable while the model stood still: "толкать дух трупа" (01.10).
				# mark_wreck existed with NO callers at all until this line.
				try:
					# detach_filter=False keeps WGVehicleFilter2/wgPhysics attached:
					# with the detach the client died at 0x0090A3EA inside the swap
					# (right after WRECK_STEP 1_swap_start, log 19:43), while the run
					# without it survived three deaths (log 19:09).
					if manager.mark_wreck(mock, _wreck_detach):
						_offh_probe_note('wreck_mark_ok')
						return True
					_offh_probe_note('wreck_mark_fail')
				except Exception:
					_offh_probe_note('wreck_mark_exc')
			elif _wreck_mode == 'sleep':
				# Experimental, kept for A/B only: isFrozen holds the pose bit-exact,
				# but a frozen body stopped colliding (the player drove through it on
				# 01.10) and sleep_mock does NOT do mark_wreck's filter detach, so it
				# keeps the 0x00E78498 risk.  Do not ship this mode.
				try:
					if manager.sleep_mock(mock, 'wreck', True):
						_offh_probe_note('wreck_sleep_ok')
						return True
					_offh_probe_note('wreck_sleep_fail')
				except Exception:
					_offh_probe_note('wreck_sleep_exc')
			# Pushable wreck first: the rigid body stays LIVE in the shared batch
			# with zeroed drive inputs - it keeps colliding and can be shoved.
			# guard_fault (frozen static obstacle) is only the fallback.
			try:
				if False:  # pushable-wreck disabled (crash 0x0090A3EA on first wreck)
					return True
			except Exception:
				pass
			try:
				if manager.guard_fault(mock, 'wreck freeze'):
					_offh_probe_note('wreck_guard_ok')
					return True
			except Exception:
				_offh_probe_note('wreck_guard_exc')
		return bool(manager.stop_mock(mock, False))
	except Exception:
		return False


def _offh_wreck_release_or_retry(mock, callback):
	"""Retry a native owner release without ever attaching a second wreck root."""
	if _offh_release_native_for_wreck(mock):
		try:
			mock._offh_wreck_release_attempts = 0
		except Exception:
			pass
		return True
	attempts = int(getattr(
		mock, '_offh_wreck_release_attempts', 0) or 0) + 1
	try:
		mock._offh_wreck_release_attempts = attempts
	except Exception:
		pass
	if attempts < 20:
		_offh_battle_callback(0.1, callback)
	elif not bool(getattr(mock, '_offh_wreck_release_error_logged', False)):
		try:
			mock._offh_wreck_release_error_logged = True
		except Exception:
			pass
		try:
			from gui.mods.offhangar.logging import LOG_ERROR as _wreck_error
			_wreck_error('NATIVE_BOT_PHYSICS wreck swap blocked id=%s '
				'reason=native owner release failed' % (
					getattr(mock, 'id', '?'),))
		except Exception:
			pass
	return False


def _stop_dead_native_bot(mock, restore_filter=False):
	"""Compatibility name for the central kill ownership barrier."""
	return _offh_release_native_for_wreck(mock)


def _offh_native_failed_pose(mock):
	"""Return an immobile current pose when the native manager is unavailable."""
	pose = getattr(mock, '_offh_native_fail_pose', None)
	if isinstance(pose, tuple) and len(pose) >= 6:
		return {
			'position': pose[:3], 'yaw': pose[3], 'pitch': pose[4],
			'roll': pose[5], 'velocity': 0.0, 'turn_velocity': 0.0,
			'failed': True,
		}
	position = getattr(mock, 'position', None)
	try:
		point = (float(position.x), float(position.y), float(position.z))
	except Exception:
		return None
	return {
		'position': point,
		'yaw': float(getattr(mock, 'yaw', 0.0) or 0.0),
		'pitch': float(getattr(mock, 'pitch', 0.0) or 0.0),
		'roll': float(getattr(mock, 'roll', 0.0) or 0.0),
		'velocity': 0.0,
		'turn_velocity': 0.0,
		'failed': True,
	}

# Temporary low-overhead battle profiler.  It samples one render callback in
# four, then writes one aggregate NOTE every five seconds.  Sampling matters on
# this Python 2.6 client: timing every tiny operation would become part of the
# performance problem we are trying to measure.
