def _offh_chat_cfg():
	st = _OFFH_CHAT
	gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	if st['gen'] != gen:
		st['gen'] = gen
		st['seen'] = {}
		st['dups'] = 0
		st['cd'] = {}
		st['last'] = 0.0
		st['lowhp'] = set()
		st['greet_at'] = None
		st['replies'] = 0
		st['next_banter_at'] = 0.0
		try:
			from gui.mods.offhangar._constants import CONFIG_OPTIONS as _CH_CFG
			st['dedup'] = bool(_CH_CFG.get('chat_dedup', True))
			st['chatter'] = bool(_CH_CFG.get('bot_chatter', True))
			st['adv'] = bool(_CH_CFG.get('player_advisory_fix', True))
		except Exception:
			st['dedup'] = st['chatter'] = st['adv'] = True
		LOG_DEBUG('CHAT_CFG dedup=%s chatter=%s adv_fix=%s' % (
			'yes' if st['dedup'] else 'no', 'yes' if st['chatter'] else 'no',
			'yes' if st['adv'] else 'no'))
	return st


def _offh_chat_once(kind, data, now=None):
	"""Display gate.  True = show this line; False = the same line (kind, channel,
	payload) was already shown < 0.6 s ago by another delivery path."""
	try:
		st = _offh_chat_cfg()
		if not st['dedup']:
			return True
		if now is None:
			import time as _cd_time
			now = _cd_time.time()
		ch = data.get('channel', 0) or 0
		try:
			ch = int(ch)
		except Exception:
			ch = 1
		if ch <= 0:
			ch = 1
		payload = data.get('data')
		if isinstance(payload, list):
			payload = tuple(payload)
		key = (kind, ch, repr(payload))
		seen = st['seen']
		if len(seen) > 64:
			for k in [k for k, t in seen.items() if now - t > 2.0]:
				del seen[k]
		t = seen.get(key)
		if t is not None and 0.0 <= now - t < 0.6:
			st['dups'] += 1
			if st['dups'] <= 5 or st['dups'] % 50 == 0:
				LOG_NOTE('CHAT_DEDUP kind=%s dropped=%d' % (kind, st['dups']))
			return False
		seen[key] = now
		return True
	except Exception:
		return True


def _offh_adv_player_health(player, mock_vehicles, player_vehicle_id):
	"""Player HP for player_advisory().  Flag off = the old read (0 on PlayerAccount)."""
	try:
		if _offh_chat_cfg()['adv']:
			pm = mock_vehicles.get(player_vehicle_id) if mock_vehicles else None
			if pm is not None:
				return getattr(pm, 'health', 0) or 0
	except Exception:
		pass
	return getattr(player, 'health', 0) or 0


def _offh_chat_veh(arena, vid):
	try:
		return arena.vehicles.get(vid) or {}
	except Exception:
		return {}


def _offh_chat_vname(vinfo):
	try:
		vt = vinfo.get('vehicleType')
		t = getattr(vt, 'type', None)
		n = getattr(t, 'shortUserString', None) or getattr(t, 'userString', None)
		if n:
			return n if isinstance(n, unicode) else unicode(str(n), 'utf-8', 'replace')
	except Exception:
		pass
	n = vinfo.get('name') or 'Bot'
	return n if isinstance(n, unicode) else unicode(str(n), 'utf-8', 'replace')


