def _offh_chat_style():
	try:
		style, fresh = _offh_flag('bot_chat_style', 'text', 'str', ('text', 'commands'))
	except Exception:
		return 'text'
	if fresh:
		LOG_NOTE('BOT_CHAT_STYLE %s' % style)
	return style


def _offh_chat_send_command(vid, event, target=None):
	"""a bot event as a native radio command (icon + standard line)."""
	cmd = _OFFH_CHAT_EVENT_COMMANDS.get(str(event))
	if cmd is None:
		return False
	try:
		import BigWorld, time as _cc_time
		from chat_shared import CHAT_ACTIONS, CHAT_RESPONSES
		from gui import WindowsManager as _cwm
		if getattr(_cwm.g_windowsManager, 'battleWindow', None) is None:
			return False
		pl = BigWorld.player()
		arena = getattr(pl, 'arena', None)
		if arena is None or getattr(arena, 'period', 3) != 3:
			return False
		vinfo = _offh_chat_veh(arena, vid)
		try:
			from ChatManager import chatManager as _cc_cm
			ch = getattr(_cc_cm, 'battleTeamChannelID', 1) or 1
		except Exception:
			ch = 1
		now = _cc_time.time()
		data = {'requestID': 0, 'action': CHAT_ACTIONS.userChatCommand.index(),
			'actionResponse': CHAT_RESPONSES.success.index(), 'channel': ch,
			'originator': vinfo.get('accountDBID', 10000 + int(vid)),
			'originatorNickName': vinfo.get('name', 'Bot_%s' % vid),
			'data': [cmd, int(target or 0), 0], 'time': now, 'sentTime': now, 'group': 0, 'flags': 0}
		fn = globals().get('g_offh_onUserChatCommand')
		if fn is not None:
			fn(data)
		elif hasattr(pl, 'onChatAction'):
			pl.onChatAction(data)
		else:
			return False
		LOG_NOTE('BOT_CMD id=%s ev=%s cmd=%s' % (str(vid), event, cmd))
		# the bot's own call may draw ONE ally (soft rules in bot_ai).
		if str(event) in ('low_hp', 'advance'):
			try:
				_rd = globals().get('g_offh_bot_director')
				_ra = _rd.agents.get(int(vid)) if _rd is not None else None
				if _ra is not None and _ra.get('position') is not None:
					_took = _rd.apply_radio_command(cmd, int(vid), int(_ra['team']),
						tuple(_ra['position']), BigWorld.time())
					LOG_NOTE('RADIO_BOT cmd=%s id=%s took=%r' % (cmd, str(vid), _took))
			except Exception as _rb_err:
				LOG_NOTE('RADIO_BOT_ERR %r' % (_rb_err,))
		return True
	except Exception as _cc_err:
		LOG_NOTE('BOT_CMD_ERR %r' % (_cc_err,))
		return False


def _offh_chat_send(vid, text, common=False, event='?', target=None):
	"""One bot line through the single display path (g_offh_onBroadcast)."""
	if _offh_chat_style() == 'commands':
		return _offh_chat_send_command(vid, event, target)
	try:
		import BigWorld, time as _cs_time
		from chat_shared import CHAT_ACTIONS, CHAT_RESPONSES
		from gui import WindowsManager as _cwm
		if getattr(_cwm.g_windowsManager, 'battleWindow', None) is None:
			return False
		pl = BigWorld.player()
		arena = getattr(pl, 'arena', None)
		if arena is None or getattr(arena, 'period', 3) != 3:
			return False
		vinfo = _offh_chat_veh(arena, vid)
		try:
			from ChatManager import chatManager as _cs_cm
		except Exception:
			_cs_cm = None
		if common:
			ch = getattr(_cs_cm, 'battleCommonChannelID', None) if _cs_cm is not None else None
			if not ch:
				return False
		else:
			ch = (getattr(_cs_cm, 'battleTeamChannelID', 1) if _cs_cm is not None else 1) or 1
		if isinstance(text, unicode):
			text = text.encode('utf-8')
		now = _cs_time.time()
		bc = {'requestID': 0, 'action': CHAT_ACTIONS.broadcast.index(),
			'actionResponse': CHAT_RESPONSES.success.index(), 'channel': ch,
			'originator': vinfo.get('accountDBID', 10000 + int(vid)),
			'originatorNickName': vinfo.get('name', 'Bot_%s' % vid),
			'data': text, 'time': now, 'sentTime': now, 'group': 0, 'flags': 0}
		fn = globals().get('g_offh_onBroadcast')
		if fn is None:
			return False
		st = _OFFH_CHAT
		st['sending'] = True
		try:
			fn(bc)
		finally:
			st['sending'] = False
		LOG_NOTE('BOT_CHAT id=%s ev=%s common=%s text=%r' % (str(vid), event, str(bool(common)), text))
		return True
	except Exception as _cs_err:
		LOG_NOTE('BOT_CHAT_ERR %r' % (_cs_err,))
		return False


def _offh_chat_say(vid, event, fmt=None, delay=None, common=False, force=False, now=None, target=None):
	"""Rate-limited, delayed line for bot `vid`.  Returns True if scheduled."""
	try:
		import random as _cy_rand, time as _cy_time
		st = _offh_chat_cfg()
		if not st['chatter'] or vid is None:
			return False
		if now is None:
			now = _cy_time.time()
		if not force:
			if now - st['last'] < 4.5:
				return False
			if now - st['cd'].get(vid, -1e9) < 18.0:
				return False
		_chat_tbl = _OFFH_CHAT_LINES
		try:
			from gui.mods.offhangar import cbt_profiles_and_locale as _cbt_cl
			if not _cbt_cl.is_ru_locale() and event != '_reply':
				_chat_tbl = _cbt_cl.CHAT_LINES_EN
		except Exception:
			pass
		lines = list(_chat_tbl.get(event) or _OFFH_CHAT_LINES.get(event) or [event])
		if fmt and fmt.get('killer') in (None, '', u'?', '?'):
			_no_k = [_l for _l in lines if '%(killer)s' not in _l]
			if _no_k:
				lines = _no_k
		text = _cy_rand.choice(lines)
		try:
			text = text % (fmt or {})
		except Exception:
			pass
		st['last'] = now
		st['cd'][vid] = now
		if delay is None:
			delay = _cy_rand.uniform(0.6, 2.0)
		try:
			import BigWorld
			BigWorld.callback(float(delay), lambda: _offh_chat_send(vid, text, common, event, target))
		except Exception:
			_offh_chat_send(vid, text, common, event, target)
		return True
	except Exception:
		return False


def _offh_chat_allies(arena, team, exclude=(), alive=True):
	out = []
	try:
		mvs = globals().get('G_MOCK_VEHICLES', {}) or {}
		import BigWorld as _ca_bw
		pvid = getattr(_ca_bw.player(), 'playerVehicleID', None)
		for vid, vinfo in arena.vehicles.items():
			if vid in exclude or vid == pvid:
				continue
			if vinfo.get('team') != team:
				continue
			if alive and not vinfo.get('isAlive', True):
				continue
			if vid not in mvs:
				continue
			out.append(vid)
	except Exception:
		pass
	return out


def _offh_chat_maybe_ack(arena, team, speaker, now=None):
	"""Another ally answers a bot line now and then ('bots react to each other')."""
	import random as _ak_rand
	if _ak_rand.random() >= 0.25:
		return
	others = _offh_chat_allies(arena, team, exclude=(speaker,))
	if others:
		_offh_chat_say(_ak_rand.choice(others), 'ack', delay=_ak_rand.uniform(2.6, 4.0), force=True, now=now)


def _offh_bot_chatter_kill(victim_id, killer_id, reason=0):
	"""Hooked into the central arena.onVehicleKilled wrapper (first death only)."""
	try:
		import random as _ck_rand, BigWorld
		st = _offh_chat_cfg()
		if not st['chatter']:
			return
		pl = BigWorld.player()
		arena = getattr(pl, 'arena', None)
		if arena is None:
			return
		pvid = getattr(pl, 'playerVehicleID', None)
		pinfo = _offh_chat_veh(arena, pvid)
		pteam = pinfo.get('team', getattr(pl, '_offhangar_team', 1))
		vinfo = _offh_chat_veh(arena, victim_id)
		kinfo = _offh_chat_veh(arena, killer_id) if (killer_id not in (None, -1, 0) and killer_id != victim_id) else {}
		fmt = {'victim': _offh_chat_vname(vinfo), 'killer': _offh_chat_vname(kinfo) if kinfo else u'?',
			'player': unicode(str(pinfo.get('name') or getattr(pl, 'name', 'Player')), 'utf-8', 'replace')}
		vteam = vinfo.get('team')
		allies = _offh_chat_allies(arena, pteam, exclude=(victim_id,))
		said = None
		if victim_id == pvid:
			if allies and _ck_rand.random() < 0.6:
				said = _ck_rand.choice(allies)
				_offh_chat_say(said, 'player_died', fmt)
			if kinfo and kinfo.get('team') != pteam and _ck_rand.random() < 0.25:
				_offh_chat_say(killer_id, 'taunt', fmt, delay=_ck_rand.uniform(1.0, 2.5), common=True, force=True)
		elif vteam is not None and vteam != pteam:
			if killer_id == pvid:
				if allies and _ck_rand.random() < 0.6:
					said = _ck_rand.choice(allies)
					_offh_chat_say(said, 'player_frag', fmt)
			elif killer_id in allies and _ck_rand.random() < 0.5:
				said = killer_id
				_offh_chat_say(said, 'frag', fmt)
		elif vteam == pteam:
			if _ck_rand.random() < 0.3:
				said = victim_id
				_offh_chat_say(said, 'died', fmt)
			elif allies and _ck_rand.random() < 0.4:
				said = _ck_rand.choice(allies)
				_offh_chat_say(said, 'ally_lost', fmt)
		if said is not None:
			_offh_chat_maybe_ack(arena, pteam, said)
	except Exception as _ck_err:
		LOG_NOTE('BOT_CHAT_KILL_ERR %r' % (_ck_err,))


def _offh_bot_chatter_tick(player, mock_vehicles, player_vehicle_id, now):
	"""Per AI tick: battle-start greeting, low-HP calls, and periodic live bot-to-bot tactical banter."""
	try:
		import random as _ct_rand
		st = _offh_chat_cfg()
		if not st['chatter']:
			return
		arena = getattr(player, 'arena', None)
		if arena is None or getattr(arena, 'period', 3) < 3:
			return
		pinfo = _offh_chat_veh(arena, player_vehicle_id)
		pteam = pinfo.get('team', getattr(player, '_offhangar_team', 1))
		if st['greet_at'] is None:
			st['greet_at'] = now + _ct_rand.uniform(1.2, 3.2)
			st['next_banter_at'] = now + _ct_rand.uniform(18.0, 26.0)
		elif st['greet_at'] > 0 and now >= st['greet_at']:
			st['greet_at'] = -1.0
			allies = _offh_chat_allies(arena, pteam)
			enemies = _offh_chat_allies(arena, 3 - int(pteam))
			_ct_rand.shuffle(allies)
			_ct_rand.shuffle(enemies)
			if allies:
				_offh_chat_say(allies[0], 'greet_common', delay=0.4, common=True, force=True)
				if len(allies) >= 2:
					_offh_chat_say(allies[1], 'greet', delay=_ct_rand.uniform(1.8, 3.2), common=False, force=True)
			if enemies:
				_sp_name = unicode(str(_offh_chat_veh(arena, allies[0]).get('name', 'Танкист')), 'utf-8', 'replace') if allies else u'Танкист'
				_ev_en = 'greet_common_reply' if (allies and _ct_rand.random() < 0.65) else 'greet_common'
				_offh_chat_say(enemies[0], _ev_en, fmt={'speaker': _sp_name}, delay=_ct_rand.uniform(2.6, 4.5), common=True, force=True)
		allies_list = _offh_chat_allies(arena, pteam)
		for vid in allies_list:
			if vid in st['lowhp']:
				continue
			m = mock_vehicles.get(vid)
			if m is None:
				continue
			hp = float(getattr(m, 'health', 0) or 0)
			mx = float(getattr(m, 'maxHealth', 0) or 0)
			if mx > 0 and 0 < hp < 0.3 * mx:
				st['lowhp'].add(vid)
				if _ct_rand.random() < 0.65:
					_offh_chat_say(vid, 'low_hp')
		# v5.9: Calm, context-verified bot-to-bot communication (45..65s cadence, nearby/LOS allies only)
		_next_b = float(st.get('next_banter_at', 0.0) or 0.0)
		if _next_b <= 0.0:
			st['next_banter_at'] = now + _ct_rand.uniform(38.0, 52.0)
		elif now >= _next_b and len(allies_list) >= 2:
			st['next_banter_at'] = now + _ct_rand.uniform(45.0, 65.0)
			_said_banter = False
			# 1) Check if an allied bot is on a long reload (>7.5s left) with a nearby ally (<= 70m) holding the same corner
			for _bvid in allies_list:
				_bm = mock_vehicles.get(_bvid)
				if _bm is None or getattr(_bm, 'position', None) is None:
					continue
				_r_full = float(getattr(_bm, '_offh_last_reload_time', getattr(_bm, '_ai_reload_full', 4.0)) or 4.0)
				_raw_st_bm = getattr(_bm, '_ai_shoot_timer', None)
				_s_tmr = 999.0 if _raw_st_bm is None else float(_raw_st_bm)
				_r_left = _r_full - _s_tmr
				if _r_left >= 7.5 and getattr(_bm, '_offh_ai_targeted', False):
					_bp = _bm.position
					_near_allies = [
						x for x in allies_list
						if x != _bvid and mock_vehicles.get(x) is not None and getattr(mock_vehicles[x], 'position', None) is not None and
						((mock_vehicles[x].position.x - _bp.x) ** 2 + (mock_vehicles[x].position.z - _bp.z) ** 2) <= 4900.0
					]
					if _near_allies:
						_ally_pick = _ct_rand.choice(_near_allies)
						_ally_nm = unicode(str(_offh_chat_veh(arena, _ally_pick).get('name', 'Брат')), 'utf-8', 'replace')
						_bvid_nm = unicode(str(_offh_chat_veh(arena, _bvid).get('name', 'Брат')), 'utf-8', 'replace')
						if _offh_chat_say(_bvid, 'banter_reload', fmt={'sec': int(round(_r_left)), 'ally': _ally_nm}, delay=0.3, force=False):
							_offh_chat_say(_ally_pick, 'banter_reload_ack', fmt={'ally': _bvid_nm}, delay=_ct_rand.uniform(2.0, 3.4), force=True)
							_said_banter = True
							break
			# 2) Check if an allied bot is engaging a visible enemy that a nearby teammate also has a clear shot on
			if not _said_banter:
				_dir_b = globals().get('g_offh_bot_director')
				if _dir_b is not None:
					for _bvid in allies_list:
						_bag = _dir_b.agents.get(int(_bvid))
						_btid = (_bag or {}).get('target_id')
						_t_cont = (_dir_b.contacts.get(pteam) or {}).get(_btid) if _btid is not None else None
						if _btid is not None and _t_cont is not None and _t_cont.get('visible'):
							_shooters = set(int(s) for s in (_t_cont.get('shootable_by_ids') or ()))
							_able_allies = [x for x in allies_list if x != _bvid and int(x) in _shooters]
							if _able_allies:
								_ally_pick2 = _ct_rand.choice(_able_allies)
								_ally_nm2 = unicode(str(_offh_chat_veh(arena, _ally_pick2).get('name', 'Союзник')), 'utf-8', 'replace')
								_evi = _offh_chat_veh(arena, _btid)
								_enm = u'%s (%s)' % (_evi.get('name', u'Враг'), _offh_chat_vname(_evi))
								if _ct_rand.random() < 0.35:
									_bvid_nm2 = unicode(str(_offh_chat_veh(arena, _bvid).get('name', 'Танкист')), 'utf-8', 'replace')
									if _offh_chat_say(_bvid, 'common_banter', fmt={'enemy': _offh_chat_vname(_evi)}, delay=0.4, common=True, force=False):
										_offh_chat_say(_btid, 'common_banter_reply', fmt={'speaker': _bvid_nm2}, delay=_ct_rand.uniform(2.4, 4.0), common=True, force=True)
										_said_banter = True
										break
								elif _offh_chat_say(_bvid, 'banter_flank', fmt={'enemy': _enm, 'ally': _ally_nm2}, delay=0.4, force=False):
									_offh_chat_say(_ally_pick2, 'banter_flank_ack', fmt={'enemy': _offh_chat_vname(_evi)}, delay=_ct_rand.uniform(2.2, 3.6), force=True)
									_said_banter = True
									break
			# 3) Score momentum exchange between two allies
			if not _said_banter:
				_af, _ef = _offh_team_score(player)
				if abs(_af - _ef) >= 2:
					_sp1 = _ct_rand.choice(allies_list)
					_ev_m = 'banter_winning' if _af > _ef else 'banter_losing'
					_offh_chat_say(_sp1, _ev_m, delay=0.4, force=True)
					_others = [x for x in allies_list if x != _sp1]
					if _others:
						_offh_chat_say(_ct_rand.choice(_others), 'ack', delay=_ct_rand.uniform(2.2, 3.8), force=True)
	except Exception as _ct_err:
		LOG_NOTE('BOT_CHAT_TICK_ERR %r' % (_ct_err,))


def _offh_bot_chatter_events(director, player_team):
	"""v5.1: Handle squad & tactical callout events from bot_ai with full enemy/ally/reload context."""
	try:
		ev = getattr(director, 'chat_events', None)
		if not ev:
			return
		items = list(ev)
		del ev[:]
		if not _offh_chat_cfg()['chatter']:
			return
		import BigWorld as _co_bw
		_co_ar = getattr(_co_bw.player(), 'arena', None)
		if _co_ar is None or getattr(_co_ar, 'period', 3) < 3:
			return
		for _item in items:
			if len(_item) >= 4:
				kind, speaker, extra, why = _item[0], _item[1], _item[2], str(_item[3] or '')
			else:
				kind, speaker, extra, why = _item[0], _item[1], _item[2], ''
			ag = director.agents.get(speaker) if speaker is not None else None
			if ag is None or ag.get('team') != player_team:
				continue
			if kind in _OFFH_CALLOUT_KINDS:
				try:
					_co_vi = _offh_chat_veh(_co_ar, extra) if _co_ar is not None else {}
					_co_nm = unicode(str(_co_vi.get('name') or _offh_chat_vname(_co_vi)), 'utf-8', 'replace')
					_co_vtype = _offh_chat_vname(_co_vi)
					if _co_vtype and _co_vtype not in _co_nm:
						_target_full = u'%s (%s)' % (_co_nm, _co_vtype)
					else:
						_target_full = _co_nm
				except Exception:
					_co_nm = u'Союзник'
					_target_full = u'цель'
				_enemy_label = u'тяж'
				_ally_label = u'союзник'
				_sec_label = u'8'
				try:
					if why.startswith('enemy:'):
						_eid_w = int(why.split(':', 1)[1])
						_evi_w = _offh_chat_veh(_co_ar, _eid_w) if _co_ar is not None else {}
						_enemy_label = _offh_chat_vname(_evi_w) or u'противник'
					elif why.startswith('ally:'):
						_aid_w = int(why.split(':', 1)[1])
						_avi_w = _offh_chat_veh(_co_ar, _aid_w) if _co_ar is not None else {}
						_ally_label = unicode(str(_avi_w.get('name') or _offh_chat_vname(_avi_w)), 'utf-8', 'replace')
					elif why.startswith('rld:'):
						_sec_label = unicode(why.split(':', 1)[1])
				except Exception:
					pass
				_fmt = {
					'target': _co_nm if kind.startswith('warn_') else _target_full,
					'enemy': _enemy_label,
					'ally': _ally_label,
					'sec': _sec_label,
				}
				_delay = 1.6 if kind in ('warn_ack', 'arty_bait_ack') else 0.45
				_force = kind in ('arty_bait_request', 'arty_pie_hunt')
				_sent = _offh_chat_say(speaker, kind, fmt=_fmt, target=extra, delay=_delay, force=_force)
				if _sent and kind in ('warn_stop', 'warn_strong', 'warn_back', 'warn_arty') and extra in director.agents:
					if ((int(extra) + int(_co_bw.time())) % 3) == 0:
						_offh_chat_say(extra, 'warn_ack', fmt=_fmt, target=speaker, delay=2.1, force=True)
				continue
			_offh_chat_say(speaker, kind, force=True,
				delay=(0.5 if kind == 'help_call' else 2.2))
	except Exception:
		pass


def _offh_notify_ai_whiff_or_bounce(shooter_id, start_pt, impact_pt, hit_bot_id=None, outcome='miss'):
	"""v5.1: Notify tactical AI when a shot misses near a bot or bounces off a bot's armor."""
	try:
		import BigWorld, math, random as _wb_rand
		pl = BigWorld.player()
		director = globals().get('g_offh_bot_director')
		if director is None or not hasattr(director, 'note_enemy_whiff_or_bounce'):
			return
		mvs = globals().get('G_MOCK_VEHICLES', {}) or {}
		pvid = getattr(pl, 'playerVehicleID', -1)
		pteam = getattr(pl, '_offhangar_team', 1) or 1
		shooter_team = pteam if int(shooter_id or -1) == int(pvid) else getattr(mvs.get(shooter_id), '_bot_team', 0)
		now = float(BigWorld.time())
		if hit_bot_id is not None:
			director.note_enemy_whiff_or_bounce(int(hit_bot_id), int(shooter_id), outcome, now)
			# Invalidate order cache so bot reacts on the very next frame!
			_hmv = mvs.get(int(hit_bot_id))
			if _hmv is not None:
				_hmv._offh_ai_order_cache = (_hmv._offh_ai_order_cache[0], 0.0, _hmv._offh_ai_order_cache[2]) if isinstance(getattr(_hmv, '_offh_ai_order_cache', None), tuple) and len(_hmv._offh_ai_order_cache) == 3 else None
			return
		if start_pt is None or impact_pt is None:
			return
		sx, sy, sz = float(start_pt.x), float(start_pt.y), float(start_pt.z)
		ex, ey, ez = float(impact_pt.x), float(impact_pt.y), float(impact_pt.z)
		sdx, sdz = ex - sx, ez - sz
		slen_sq = sdx * sdx + sdz * sdz
		if slen_sq < 1.0:
			return
		for vid, mv in mvs.items():
			if vid == shooter_id or mv is None or getattr(mv, 'health', 0) <= 0:
				continue
			if getattr(mv, '_bot_team', 0) == shooter_team:
				continue
			vp = getattr(mv, 'position', None)
			if vp is None:
				continue
			bx, bz = float(vp.x), float(vp.z)
			# Check distance to impact point OR closest point on trajectory segment
			d_imp_sq = (bx - ex) ** 2 + (bz - ez) ** 2
			t_proj = max(0.0, min(1.0, ((bx - sx) * sdx + (bz - sz) * sdz) / slen_sq))
			cx, cz = sx + sdx * t_proj, sz + sdz * t_proj
			d_seg_sq = (bx - cx) ** 2 + (bz - cz) ** 2
			if d_imp_sq <= 900.0 and hasattr(director, 'note_artillery_impact'):
				_is_spg_sh = False
				try:
					_sh_ag = director.agents.get(int(shooter_id or -1))
					if _sh_ag is not None:
						_is_spg_sh = ((_sh_ag.get('profile') or {}).get('class_tag') == 'SPG')
					elif int(shooter_id or -1) == int(pvid):
						_p_td_sh = getattr(pl, 'vehicleTypeDescriptor', None) or (globals().get('G_LOADED_MODELS', {}) or {}).get('td')
						_p_tags_sh = getattr(getattr(_p_td_sh, 'type', None), 'tags', ()) if _p_td_sh is not None else ()
						_is_spg_sh = ('SPG' in (_p_tags_sh or ()) and 'AT-SPG' not in (_p_tags_sh or ()))
				except Exception:
					_is_spg_sh = False
				if _is_spg_sh:
					director.note_artillery_impact(int(vid), int(shooter_id), (sx, sy, sz), (ex, ey, ez), now)
					mv._offh_ai_order_cache = (mv._offh_ai_order_cache[0], 0.0, mv._offh_ai_order_cache[2]) if isinstance(getattr(mv, '_offh_ai_order_cache', None), tuple) and len(mv._offh_ai_order_cache) == 3 else None
			if d_imp_sq <= 225.0 or d_seg_sq <= 169.0:
				director.note_enemy_whiff_or_bounce(int(vid), int(shooter_id), 'miss', now)
				mv._offh_ai_order_cache = (mv._offh_ai_order_cache[0], 0.0, mv._offh_ai_order_cache[2]) if isinstance(getattr(mv, '_offh_ai_order_cache', None), tuple) and len(mv._offh_ai_order_cache) == 3 else None
				# If an enemy hard bot baited the player's shot and has long reload window to punish, occasionally taunt in common chat!
				if int(shooter_id) == int(pvid):
					_ag_w = director.agents.get(int(vid))
					if _ag_w and str(_ag_w.get('skill_tier', '')).lower() == 'hard' and _wb_rand.random() < 0.35:
						_est_l, _, _ = director.estimate_target_reload_left(_ag_w, pvid, now)
						if _est_l >= 5.0:
							_pname = unicode(str(getattr(pl, 'name', 'Player')), 'utf-8', 'replace')
							_offh_chat_say(vid, 'enemy_punish_taunt', fmt={'player': _pname}, delay=_wb_rand.uniform(0.6, 1.4), common=True)
	except Exception:
		pass


def _offh_bot_chatter_advice(advisory):
	"""player_advisory() result -> the speaker also writes it in team chat."""
	try:
		import BigWorld as _adv_bw
		_adv_ar = getattr(_adv_bw.player(), 'arena', None)
		if _adv_ar is not None and getattr(_adv_ar, 'period', 3) < 3:
			return
		if advisory and advisory.get('mode') in ('hold', 'advance', 'advance_cleanup', 'cant_pen'):
			_offh_chat_say(advisory.get('speaker_id'), advisory['mode'], force=False)
	except Exception:
		pass


def _offh_bot_chatter_player_text(bc):
	"""The player typed something in team chat -> 1 ally answers (70%)."""
	try:
		import random as _cp_rand, BigWorld
		st = _offh_chat_cfg()
		if not st['chatter'] or st['sending']:
			return
		pl = BigWorld.player()
		arena = getattr(pl, 'arena', None)
		if arena is None:
			return
		pvid = getattr(pl, 'playerVehicleID', None)
		pinfo = _offh_chat_veh(arena, pvid)
		nick = bc.get('originatorNickName')
		if nick not in (pinfo.get('name'), getattr(pl, 'name', None)):
			return
		text = bc.get('data') or ''
		if not isinstance(text, basestring):
			return
		if not isinstance(text, unicode):
			text = unicode(text, 'utf-8', 'replace')
		low = text.lower()
		_rep_tbl = _OFFH_CHAT_REPLIES
		try:
			from gui.mods.offhangar import cbt_profiles_and_locale as _cbt_cr
			if not _cbt_cr.is_ru_locale():
				_rep_tbl = _cbt_cr.CHAT_REPLIES_EN
		except Exception:
			pass
		replies = _rep_tbl[-1][1]
		for keys, rep in _rep_tbl:
			if not keys or [k for k in keys if k in low]:
				replies = rep
				break
		if _cp_rand.random() >= 0.7:
			return
		allies = _offh_chat_allies(arena, pinfo.get('team', 1))
		if not allies:
			return
		vid = _cp_rand.choice(allies)
		_OFFH_CHAT_LINES['_reply'] = replies
		st['replies'] += 1
		_offh_chat_say(vid, '_reply', delay=_cp_rand.uniform(1.5, 3.5), force=True)
	except Exception as _cp_err:
		LOG_NOTE('BOT_CHAT_REPLY_ERR %r' % (_cp_err,))


_OFFH_DMG_FX = {'gen': None, 'gun': False, 'engine': False}


def _offh_dmg_fx_cfg():
	st = _OFFH_DMG_FX
	gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	if st['gen'] != gen:
		st['gen'] = gen
		try:
			from gui.mods.offhangar._constants import CONFIG_OPTIONS as _DF_CFG
			st['gun'] = bool(_DF_CFG.get('gun_damage_lock', True))
			st['engine'] = bool(_DF_CFG.get('native_engine_damage', True))
		except Exception:
			st['gun'] = st['engine'] = False
		LOG_DEBUG('DMG_FX_CFG gun_lock=%s engine=%s' % (
			'yes' if st['gun'] else 'no', 'yes' if st['engine'] else 'no'))
	return st


def _offh_gun_pitch_factor(mock, module_factor):
	"""Gun elevation speed multiplier: 0 destroyed gun, 0.5 damaged, 1 whole/flag off."""
	try:
		if mock is None or not _offh_dmg_fx_cfg()['gun']:
			return 1.0
		if getattr(mock, 'is_gun_destroyed', False):
			return 0.0
		f = float(module_factor(mock, 'aim_time'))
		if f > 1.0:
			return 1.0 / f
	except Exception:
		pass
	return 1.0


def _offh_set_power_scale(mock, factor):
	"""Store crew x module mobility factor for physics_core (native enginePower)."""
	try:
		if mock is not None and _offh_dmg_fx_cfg()['engine']:
			mock._offh_power_scale = max(0.15, min(1.0, float(factor)))
	except Exception:
		pass


_OFFH_PERF_SAMPLE_EVERY = 8
_OFFH_PERF_REPORT_SECONDS = 15.0
_OFFH_AI_ORDER_REFRESHES_PER_FRAME = 2
_OFFH_AI_NAV_REFRESHES_PER_FRAME = 2
_OFFH_AI_DRIVER_REFRESHES_PER_FRAME = 2
_OFFH_AI_TREE_REFRESHES_PER_FRAME = 1
_OFFH_AI_CONTACT_TARGETS_PER_FRAME = 2
_OFFH_AI_COVER_CANDIDATES_PER_FRAME = 1
_OFFH_AI_ARTILLERY_CHORDS_PER_FRAME = 3
_OFFH_AI_CONTACT_FULL_INTERVAL = 5.0
# Per-bot LOD: a bot farther than this (metres) from the player skips
# presentation-only per-frame work (exhaust smoke, motion sound, dust).
# Its model is distance-culled anyway, so nothing visible changes while the
# per-bot particle/audio work disappears for most of the roster.
_OFFH_BOT_LOD_FAR_M = 220.0
_OFFH_BOT_LOD_FAR2 = _OFFH_BOT_LOD_FAR_M * _OFFH_BOT_LOD_FAR_M
# LOD v2 (config: lod_level 0/1/2).  Cached per battle generation so an F11
# change or a restart picks it up, and so the per-frame cost is one dict hit.
_OFFH_LOD_CACHE = {}


def _offh_lod_params():
	"""Return (far_m, far_order_interval, contacts_dt, targets_per_frame),
	dynamically adapted to real-time map load to target 100+ FPS."""
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	map_load = int(_OFFH_HW_GOV.get('map_load', 1) or 1)
	if _OFFH_LOD_CACHE.get('gen') == gen and _OFFH_LOD_CACHE.get('map_load') == map_load and _OFFH_LOD_CACHE.get('params'):
		return _OFFH_LOD_CACHE['params']
	level = 1
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _LOD_CFG
		level = int(_LOD_CFG.get('lod_level', 1) or 1)
	except Exception:
		level = 1
	if level < 0:
		level = 0
	elif level > 2:
		level = 2
	eff_load = max(level, map_load)
	# v7.0 Low-Overhead Spotting Ring Buffer:
	# Check 2 vehicles every 32ms (~30 Hz = 60 vehicles/sec) + instant priority for nearby enemies (<180m).
	# Keeps contacts + LOS under 0.20 ms/frame instead of 4.2 ms/frame!
	if eff_load <= 0:
		params = (135.0, 0.22, 0.036, 2)
	elif eff_load == 1:
		params = (115.0, 0.26, 0.044, 2)
	else:
		params = (95.0, 0.30, 0.052, 2)
	_logged_gen = _OFFH_LOD_CACHE.get('logged_gen')
	_OFFH_LOD_CACHE['gen'] = gen
	_OFFH_LOD_CACHE['map_load'] = map_load
	_OFFH_LOD_CACHE['params'] = params
	if _logged_gen != gen:
		_OFFH_LOD_CACHE['logged_gen'] = gen
		try:
			LOG_NOTE('LOD level=%d map_load=%d far_m=%.0f far_order=%.2fs contacts_dt=%.3f '
				'targets_per_frame=%d' % (level, map_load, params[0], params[1], params[2],
					params[3]))
		except Exception:
			pass
	return params


_OFFH_HW_GOV = {
	'tier': 0,
	'map_load': 1,
	'fps_ema': 85.0,
	'cb_ms_ema': 4.0,
	'last_eval': 0.0,
	'init_done': False,
	'exhaust_sq': 7225.0,
	'muzzle_sq': 160000.0,
	'gwave_sq': 12100.0,
	'hit_sq': 160000.0,
	'susp_scale': 0.75,
	'max_burning_wrecks': 4,
}


def _offh_auto_hw_governor(frame_dt=None, now=None, mock_vehicles=None):
	"""Automatic Hardware & 100-FPS Map-Load Governor: dynamically scales AI/spotting
	cadence, suspension LOD, and distant particle density based on real-time frame time
	and map complexity so both light and heavy maps target 100+ FPS."""
	g = _OFFH_HW_GOV
	if not g['init_done']:
		g['init_done'] = True
		workers = 4
		try:
			_mc = globals().get('_OFFH_MT_COORD')
			if _mc is None:
				try:
					from gui.mods.offhangar.offh_multithread import get_coordinator as _gc_hw
				except Exception:
					from gui.mods.offhangar.native.offh_multithread import get_coordinator as _gc_hw
				_mc = _gc_hw()
				globals()['_OFFH_MT_COORD'] = _mc
				try:
					if hasattr(_mc, 'apply_d3d9_low_latency'):
						_mc.apply_d3d9_low_latency(1)
				except Exception:
					pass
			workers = int(getattr(getattr(_mc, 'native', None), '_worker_count', 4) or 4)
		except Exception:
			workers = 4
		if workers <= 2:
			g['tier'] = 2
			g['map_load'] = 2
			g['fps_ema'] = 45.0
		else:
			g['tier'] = 0
			g['map_load'] = 1
			g['fps_ema'] = 85.0
	if frame_dt is not None and 0.002 < float(frame_dt) < 0.25:
		inst_fps = 1.0 / float(frame_dt)
		g['fps_ema'] = g['fps_ema'] * 0.92 + inst_fps * 0.08
	if now is not None:
		_bst = globals().get('g_offh_battle_start_time')
		if _bst is not None and (float(now) - float(_bst)) < 3.5:
			g['last_eval'] = float(now)
			g['cb_ms_ema'] = 4.0
			g['fps_ema'] = 85.0
			return g
	if now is not None and (float(now) - float(g['last_eval'])) >= 2.0:
		g['last_eval'] = float(now)
		fps = g['fps_ema']
		cb_ms = float(g.get('cb_ms_ema', 4.0) or 4.0)
		old_tier = g['tier']
		old_ml = g.get('map_load', 1)
		# 100-FPS Map-Load controller: adjusts AI/LOS cadence to keep callback <= 4.2ms and FPS >= 90-100
		if fps >= 85.0 and cb_ms <= 4.2:
			g['map_load'] = 0
		elif fps < 60.0 or cb_ms > 7.5:
			g['map_load'] = 2
		elif fps < 75.0 or cb_ms > 5.5:
			g['map_load'] = max(1, old_ml)
		elif old_ml == 2 and (fps >= 65.0 or cb_ms <= 5.0):
			g['map_load'] = 1
		# Hardware visual/suspension tier (with 8-FPS hysteresis to eliminate oscillation)
		if old_tier == 0 and fps < 48.0:
			g['tier'] = 1 if fps >= 34.0 else 2
		elif old_tier == 1:
			if fps >= 58.0 or cb_ms <= 4.2:
				g['tier'] = 0
			elif fps < 34.0:
				g['tier'] = 2
		elif old_tier == 2 and fps >= 46.0:
			g['tier'] = 1
		tier = g['tier']
		if tier == 0:
			g['exhaust_sq'] = 7225.0
			g['muzzle_sq'] = 160000.0
			g['gwave_sq'] = 12100.0
			g['hit_sq'] = 160000.0
			g['susp_scale'] = 0.75
			g['max_burning_wrecks'] = 4
		elif tier == 1:
			g['exhaust_sq'] = 3600.0
			g['muzzle_sq'] = 90000.0
			g['gwave_sq'] = 6400.0
			g['hit_sq'] = 90000.0
			g['susp_scale'] = 0.45
			g['max_burning_wrecks'] = 3
		else:
			g['exhaust_sq'] = 1600.0
			g['muzzle_sq'] = 40000.0
			g['gwave_sq'] = 2500.0
			g['hit_sq'] = 40000.0
			g['susp_scale'] = 0.0
			g['max_burning_wrecks'] = 2
		if tier != old_tier or g['map_load'] != old_ml:
			LOG_NOTE('AUTO_HW_GOVERNOR tier=%d (%s) map_load=%d fps_ema=%.1f cb_ms=%.2f susp_scale=%.2f' % (
				tier, ('HIGH' if tier == 0 else ('MEDIUM' if tier == 1 else 'WEAK_PC_NO_SUSP')),
				g['map_load'], fps, cb_ms, g['susp_scale']))
	return g


_OFFH_AI_DIAGNOSTICS_INTERVAL = 4.0
# v4.64: mid-air lateral drift (the sideways momentum carried through a jump/
# fall - see the player and bot airborne blocks in the bot loop) used to decay
# by a flat *0.995 EVERY TICK, not every second. That made the drag rate
# itself depend on framerate: ~0.86/s actual decay at 30fps vs ~0.74/s at
# 60fps, and it would swing again on any mid-battle FPS dip. 0.995 at a
# reference 30fps tick works out to this per-SECOND decay; raising it to the
# power of the current tick's own dt reproduces that same decay at any
# framerate, so the drift feels identical whether the game is running smooth
# or chugging.
_OFFH_AIR_LAT_DECAY_PER_SEC = 0.995 ** 30.0
_OFFH_AI_COVER_OFFSETS = (
	(0.0, 0.0), (14.0, 0.0),
	(10.0, 13.0), (10.0, -13.0),
)


def _offh_ai_cache_deadline(now, entity_id, interval, salt=0, stagger=False):
	"""Spread the first expiry, then preserve the legacy per-update interval."""
	interval = max(0.001, float(interval))
	deadline = float(now) + interval
	if not stagger:
		return deadline
	# LAN battles contain at most 29 bots. A prime multiplier distributes adjacent
	# entity ids over all slots instead of making the whole line-up expire together.
	# Only the initial cache receives this phase; adding it after every update would
	# lower each bot's decision frequency.
	phase = (((abs(int(entity_id)) * 17 + int(salt) * 11) % 29) /
	         29.0) * interval
	return deadline + phase


def _offh_ai_refresh_due(selected, cache_matches, cache_fresh,
		deadline, now, horizon):
	"""v8.7: Strict per-frame quota enforcement without out-of-turn burst spikes."""
	if not cache_matches:
		return True
	if selected:
		return not cache_fresh
	if not cache_fresh and float(now) >= float(deadline) + max(1.25, float(horizon) * 2.5):
		return True
	return False


def _offh_ai_budget_from_ordered(ordered, frame_index, quota, salt=0):
	"""Select from one already-normalised entity-id sequence."""
	count = len(ordered)
	quota = max(0, int(quota or 0))
	if not count or not quota:
		return set()
	if quota >= count:
		return set(ordered)
	start = (int(frame_index) * quota + int(salt)) % count
	return set(ordered[(start + offset) % count] for offset in range(quota))


def _offh_ai_budget_ids(entity_ids, frame_index, quota, salt=0):
	"""Select one deterministic round-robin slice without starving any bot."""
	ordered = sorted(set(int(value) for value in (entity_ids or ())))
	return _offh_ai_budget_from_ordered(ordered, frame_index, quota, salt)


def _offh_ai_frame_budget_plan(entity_ids, frame_dt=(1.0 / 30.0)):
	"""v8.7: Co-scheduled round-robin budget over ALIVE bots so order+nav+driver refresh on the SAME bot slice per frame."""
	generation = int(globals().get('g_offh_battle_gen', 0) or 0)
	state = globals().get('g_offh_ai_frame_budget')
	if state is None or int(state.get('generation', -1)) != generation:
		state = {'generation': generation, 'frame': -1, 'c_main': 0, 'c_tree': 7}
		globals()['g_offh_ai_frame_budget'] = state
	state['frame'] = int(state.get('frame', -1)) + 1
	_mv_map = globals().get('G_MOCK_VEHICLES') or globals().get('mock_vehicles') or {}
	_alive_ids = [
		int(v) for v in (entity_ids or ())
		if _mv_map.get(v) is None or (getattr(_mv_map.get(v), 'isAlive', True) and (getattr(_mv_map.get(v), 'health', 1) or 0) > 0)
	]
	ordered = sorted(set(_alive_ids if _alive_ids else [int(v) for v in (entity_ids or ())]))
	count = len(ordered)
	frame_dt = max(1.0 / 120.0, min(0.25, float(frame_dt or 0.0)))
	_phase = int(state['frame']) & 1
	_b_start_fb = globals().get('g_offh_battle_start_time')
	_early_rollout = False
	try:
		import BigWorld as _bw_fb
		if _b_start_fb is not None and (float(_bw_fb.time()) - float(_b_start_fb)) < 8.5:
			_early_rollout = True
	except Exception:
		pass
	_hw_tier_fb = int((globals().get('_OFFH_HW_GOV') or {}).get('tier', 0) or 0)
	_dt_ratio = max(0.5, min(3.0, float(frame_dt or 0.0166667) / 0.0166667))
	# Responsive quota scaled by hardware governor tier so all 29 bots refresh orders, nav, and steering without frame spikes!
	if _early_rollout or int(state['frame']) < 48:
		_drv_q = 5
		_ord_q = 4
		_nav_q = 3
	elif _hw_tier_fb >= 1 or int(_OFFH_HW_GOV.get('map_load', 1) or 1) >= 2:
		_drv_q = 4
		_ord_q = 3
		_nav_q = 2
	else:
		_drv_q = 4
		_ord_q = 3
		_nav_q = 3
	if not count:
		_drv_set = set()
		_ord_set = set()
		_nav_set = set()
		_tree_set = set()
	else:
		cur = int(state.get('c_main', 0)) % count
		state['c_main'] = (cur + _drv_q) % count
		_drv_list = [ordered[(cur + i) % count] for i in range(min(count, _drv_q))]
		_drv_set = set(_drv_list)
		_ord_set = set(_drv_list[:_ord_q])
		_nav_set = set(_drv_list[-_nav_q:])
		if _phase == 1:
			tcur = int(state.get('c_tree', 0)) % count
			state['c_tree'] = (tcur + 1) % count
			_tree_set = set([ordered[tcur]])
		else:
			_tree_set = set()
	def _horizon(avg_quota):
		avg_quota = max(1, int(avg_quota))
		frames = max(1, (count + avg_quota - 1) // avg_quota)
		return frame_dt * frames
	return {
		'order': _ord_set,
		'nav': _nav_set,
		'driver': _drv_set,
		'tree': _tree_set,
		'order_horizon': _horizon(_ord_q),
		'nav_horizon': _horizon(_nav_q),
		'driver_horizon': _horizon(_drv_q),
	}


def _offh_perf_clock():
	try:
		return time.clock()
	except Exception:
		try:
			return time.perf_counter()
		except Exception:
			return time.time()


def _offh_perf_state():
	state = globals().get('g_offh_perf_state')
	generation = int(globals().get('g_offh_battle_gen', 0) or 0)
	if state is None or int(state.get('generation', -1)) != generation:
		state = {
			'generation': generation,
			'wall_start': time.time(),
			'frames': 0,
			'frame_seconds': 0.0,
			'sample_frames': 0,
			'active': False,
			'times': {},
			'calls': {},
		}
		globals()['g_offh_perf_state'] = state
	return state


def _offh_perf_frame_begin(bot_count):
	if not globals().get('_offh_vm_tuned', False):
		globals()['_offh_vm_tuned'] = True
		try:
			import sys as _sys_vm, gc as _gc_vm
			if hasattr(_sys_vm, 'setcheckinterval'):
				_sys_vm.setcheckinterval(10000)
			if hasattr(_gc_vm, 'set_threshold'):
				_gc_vm.set_threshold(50000, 50, 50)
		except Exception:
			pass
	state = _offh_perf_state()
	state['frames'] += 1
	state['bot_count'] = int(bot_count or 0)
	state['active'] = (state['frames'] % _OFFH_PERF_SAMPLE_EVERY) == 0
	if not state['active']:
		return None
	state['sample_frames'] += 1
	return _offh_perf_clock()


def _offh_perf_start():
	state = globals().get('g_offh_perf_state')
	if state is None or not state.get('active', False):
		return None
	return _offh_perf_clock()


def _offh_perf_stop(name, started, calls=1):
	if started is None:
		return
	state = globals().get('g_offh_perf_state')
	if state is None or not state.get('active', False):
		return
	elapsed = max(0.0, _offh_perf_clock() - started)
	times = state['times']
	counts = state['calls']
	times[name] = float(times.get(name, 0.0) or 0.0) + elapsed
	counts[name] = int(counts.get(name, 0) or 0) + int(calls or 0)


def _offh_perf_count(name, calls=1):
	"""Count sampled work items without adding another high-resolution clock."""
	state = globals().get('g_offh_perf_state')
	if state is None or not state.get('active', False):
		return
	counts = state['calls']
	counts[name] = int(counts.get(name, 0) or 0) + int(calls or 0)


def _offh_perf_call(name, callback, *args):
	started = _offh_perf_start()
	try:
		return callback(*args)
	finally:
		_offh_perf_stop(name, started)


def _offh_proc_tag():
	"""Which PROCESS is writing this line: 'worker' or 'client'.

	Both processes append to the SAME python.log, and `role=` is the SIMULATION
	role, not the process: when the headless worker disappears the visible client
	is promoted to bot authority and starts logging role=authority as well, so the
	two become indistinguishable. That is not theoretical - in the 04.10 13:4x
	session the worker vanished mid-battle and the log held 55 role=authority
	windows with no way to tell which process wrote which, which blocked the
	diagnosis of both the worker's death and the client's lag. The tag comes from
	the launcher's environment variable and cannot change during a process's life.
	Called once per PERF window (5 s), so no caching is needed.
	"""
	try:
		import os
		if os.environ.get('OFFHANGAR_WORKER_MODE') == 'authority_worker':
			return 'worker'
	except Exception:
		pass
	return 'client'


def _offh_arena_period(player):
	"""`arena.period` as a string, or '?' - for the PERF line and the mute marker.

	Why it is worth a permanent field: `period` gates THREE things at once - the
	player's own engine/track sounds are stopped while period != 3 (see the
	"Check prebattle period: mute engine/track sounds during countdown" block),
	`_sync_bot_motion_sounds` has the same gate for every bot, and bot shooting is
	blocked (`BOT_SHOOT_GATE blocked: arena.period=%s (needs 3)`). In LAN mode the
	client JOINS the server's countdown at whatever remains ("LAN server countdown
	joined with 26.8 second(s) remaining"), and the 04.10 log proved period was
	still 2 at some point during a battle. Whether that is a short window at the
	start or the period is stuck for the whole battle decides between two completely
	different fixes, so it is measured every PERF window instead of guessed.
	Read-only, main thread.
	"""
	try:
		arena = getattr(player, 'arena', None)
		if arena is None:
			return '?'
		return str(getattr(arena, 'period', '?'))
	except Exception:
		return '?'


def _offh_perf_role(player):
	try:
		client = getattr(player, '_offhangar_network_client', None)
		if client is None or not getattr(client, 'ready', False):
			return 'offline'
		from gui.mods.offhangar.network_battle import network_is_authority
		return 'authority' if network_is_authority(player) else 'replica'
	except Exception:
		return 'unknown'


def _offh_perf_frame_end(started, frame_dt, player):
	state = _offh_perf_state()
	try:
		state['frame_seconds'] += max(0.0, min(float(frame_dt), 0.5))
	except Exception:
		pass
	if started is not None:
		try:
			_cb_ms_cur = max(0.0, (_offh_perf_clock() - started) * 1000.0)
			_OFFH_HW_GOV['cb_ms_ema'] = float(_OFFH_HW_GOV.get('cb_ms_ema', 4.0) or 4.0) * 0.90 + _cb_ms_cur * 0.10
		except Exception:
			pass
	_offh_perf_stop('callback', started)
	state['active'] = False
	now = time.time()
	wall = max(0.001, now - float(state.get('wall_start', now)))
	if wall < _OFFH_PERF_REPORT_SECONDS:
		return
	samples = max(1, int(state.get('sample_frames', 0) or 0))
	frames = max(1, int(state.get('frames', 0) or 0))
	frame_ms = 1000.0 * float(state.get('frame_seconds', 0.0) or 0.0) / frames
	times = state.get('times', {}) or {}
	calls = state.get('calls', {}) or {}
	callback_ms = 1000.0 * float(times.get('callback', 0.0) or 0.0) / samples
	callback_share = 100.0 * callback_ms / max(0.1, frame_ms)
	ordered = ('player_loop', 'player_setup', 'player_physics', 'player_aim',
	           'player_pose', 'player_gun', 'player_gun_marker',
	           'marker_vehicle_candidates', 'player_effects',
	           'network_smoothing', 'ai_setup', 'contacts',
	           'contact_build', 'contact_targets', 'contact_foliage', 'contact_cover',
	           'contact_payload', 'contact_diagnostics', 'contact_publish',
	           'artillery_arc', 'artillery_rays',
	           'nav_tick', 'ai_order', 'order_refresh',
		           'order_deferred', 'nav_server', 'nav_target', 'nav_refresh', 'nav_deferred',
	           'bot_loop',
	           'driver', 'driver_refresh', 'driver_deferred',
		           'direction', 'direction_baked', 'direction_exact', 'physics',
		           'physics_state', 'native_simulation', 'native_physics',
		           'physics_motion', 'physics_ground',
	           'physics_safety', 'physics_rays',
	           'drive_pitch_reuse', 'drive_pitch_exact', 'tilt_support_reuse',
	           'bot_effects', 'kinematics', 'bot_audio',
	           'nav_paused', 'tactic_route', 'tactic_hold', 'tactic_manoeuvre',
	           'driver_drive', 'driver_avoid', 'driver_wait',
	           'driver_traffic_wait', 'driver_recovery',
	           'driver_arrived',
	           'traffic_snapshot', 'traffic_index', 'traffic_candidates',
	           'pose_water', 'terrain_support', 'terrain_tilt',
	           'tree_scan', 'tree_deferred',
	           'wall_collision', 'wall_fast', 'wall_exact',
	           'tank_collision', 'tank_collision_empty', 'collision_candidates',
	           'player_collision_error',
	           'pose_commit', 'visibility', 'los', 'network_publish', 'post_bot',
		           'mt_harvest', 'mt_harvest_calls', 'mt_harvest_ready',
		           'mt_harvest_empty', 'mt_harvest_vehicles', 'mt_submit',
		           'mt_submit_calls', 'mt_submit_ok', 'mt_submit_vehicles')
	parts = []
	for name in ordered:
		elapsed = float(times.get(name, 0.0) or 0.0)
		count = int(calls.get(name, 0) or 0)
		if elapsed <= 0.0 and count <= 0:
			continue
		parts.append('%s=%.2fms/%.1fc' % (
			name, 1000.0 * elapsed / samples, float(count) / samples))
	try:
		from gui.mods.offhangar.logging import LOG_NOTE as _perf_log
		_perf_log('PERF window=%.1fs proc=%s role=%s bots=%d period=%s fps=%.1f frame=%.2fms '
		          'callback=%.2fms(%.0f%%) samples=%d %s' % (
			wall, _offh_proc_tag(), _offh_perf_role(player),
			int(state.get('bot_count', 0) or 0), _offh_arena_period(player),
			float(frames) / wall, frame_ms, callback_ms, callback_share,
			samples, ' '.join(parts)))
	except Exception:
		pass
	state['wall_start'] = now
	state['frames'] = 0
	state['frame_seconds'] = 0.0
	state['sample_frames'] = 0
	state['times'] = {}
	state['calls'] = {}


def _offh_record_spawn_timing(player, prepare_seconds, wait_seconds, build_seconds):
	"""Report compact aggregate spawn costs without logging every vehicle."""
	generation = int(globals().get('g_offh_battle_gen', 0) or 0)
	state = globals().get('g_offh_spawn_timing')
	if state is None or int(state.get('generation', -1)) != generation:
		state = {'generation': generation, 'count': 0, 'prepare': 0.0,
			'wait': 0.0, 'build': 0.0, 'max_prepare': 0.0,
			'max_wait': 0.0, 'max_build': 0.0}
		globals()['g_offh_spawn_timing'] = state
	state['count'] += 1
	state['prepare'] += max(0.0, float(prepare_seconds or 0.0))
	state['wait'] += max(0.0, float(wait_seconds or 0.0))
	state['build'] += max(0.0, float(build_seconds or 0.0))
	state['max_prepare'] = max(state['max_prepare'], float(prepare_seconds or 0.0))
	state['max_wait'] = max(state['max_wait'], float(wait_seconds or 0.0))
	state['max_build'] = max(state['max_build'], float(build_seconds or 0.0))
	expected = int(getattr(player, '_offh_auto_spawn_expected', 0) or 0)
	if state['count'] % 5 != 0 and (not expected or state['count'] < expected):
		return
	try:
		from gui.mods.offhangar.logging import LOG_NOTE as _spawn_log
		count = max(1, state['count'])
		_spawn_log('SPAWN PERF ready=%d/%s prepare=%.0fms(avg)/%.0fms(max) '
			'load_wait=%.0fms(avg)/%.0fms(max) '
			'build=%.0fms(avg)/%.0fms(max)' % (
			state['count'], expected or '?', 1000.0 * state['prepare'] / count,
			1000.0 * state['max_prepare'], 1000.0 * state['wait'] / count,
			1000.0 * state['max_wait'], 1000.0 * state['build'] / count,
			1000.0 * state['max_build']))
	except Exception:
		pass


def _offh_vehicle_model_paths(type_descriptor):
	"""Return the four undamaged component paths used by retail 0.8.2."""
	return (
		type_descriptor.chassis['models']['undamaged'],
		type_descriptor.hull['models']['undamaged'],
		type_descriptor.turret['models']['undamaged'],
		type_descriptor.gun['models']['undamaged'],
	)


def _offh_fetch_vehicle_models(type_descriptor, callback):
	"""Fetch one independent model set through the retail client path.

	VehicleAppearance.__fetchModels in the 0.8.2 client calls
	BigWorld.fetchModel once for each component.  loadResourceListBG is useful for
	bulk dependency warm-up, but calling it again per vehicle makes this DX9
	client clone warm models on the game thread and can stall for seconds.
	"""
	import BigWorld
	paths = _offh_vehicle_model_paths(type_descriptor)
	refs = {}
	remaining = [len(paths)]
	finished = [False]

	def _component_ready(path, model):
		if finished[0]:
			return
		refs[path] = model
		remaining[0] -= 1
		if remaining[0] <= 0:
			finished[0] = True
			callback(refs)

	for path in paths:
		try:
			BigWorld.fetchModel(path,
				lambda model, _path=path: _component_ready(_path, model))
		except Exception:
			# Complete the aggregate callback even when one resource is broken. The
			# normal spawn unpacker then reports the exact failed vehicle instead of
			# leaving the whole lineup permanently pending.
			_component_ready(path, None)

def _get_destr_authority():
	"""offhangar.destructibles_authority, with the same execfile fallback
	the package bootstrap uses (the module ships without a .pyc)."""
	global _g_destr_authority
	if _g_destr_authority is not None:
		return _g_destr_authority
	try:
		from gui.mods.offhangar import destructibles_authority as _da
		_g_destr_authority = _da
		return _da
	except Exception:
		pass
	import sys, os, types
	full_name = 'gui.mods.offhangar.destructibles_authority'
	if full_name in sys.modules:
		_g_destr_authority = sys.modules[full_name]
		return _g_destr_authority
	candidates = []
	try:
		candidates.append(os.path.dirname(os.path.abspath(__file__)))
	except Exception:
		pass
	candidates.append(os.path.join('res_mods', '0.8.2', 'scripts', 'client', 'gui', 'mods', 'offhangar'))
	for _base_d in list(candidates):
		candidates.append(os.path.join(_base_d, 'physics'))
	for _dir in candidates:
		py_path = os.path.join(_dir, 'destructibles_authority.py')
		if os.path.exists(py_path):
			mod = types.ModuleType(full_name)
			mod.__file__ = py_path
			sys.modules[full_name] = mod
			try:
				execfile(py_path, mod.__dict__)
			except Exception:
				del sys.modules[full_name]
				raise
			_g_destr_authority = mod
			return mod
	raise ImportError('destructibles_authority not found')

g_offline_models = []
g_offline_enemies = []
def _add_model(m):
	global g_offline_models
	g_offline_models.append(m)
	import BigWorld
	BigWorld.addModel(m)


def _offh_assign_entity_model_root(entity, model, handoff=None):
	"""Mirror VehicleAppearance's single root-motor handoff."""
	if handoff is None:
		handoff = {}
	try:
		if not bool(handoff.get('assigned', False)):
			entity.model = model
			if getattr(entity, 'model', None) is not model:
				return False
			handoff['assigned'] = True
			motors = list(model.motors)
			try:
				handoff['default_motor'] = motors[0]
			except IndexError:
				handoff['complete'] = True
				return True
		default_motor = handoff.get('default_motor')
		if default_motor is None:
			return bool(handoff.get('complete', False))
		motors = list(model.motors)
		if not any(motor is default_motor for motor in motors):
			if motors:
				return False
			handoff['default_motor'] = None
			handoff['complete'] = True
			return True
		model.delMotor(default_motor)
		motors = list(model.motors)
		if (any(motor is default_motor for motor in motors) or motors):
			return False
		handoff['default_motor'] = None
		handoff['complete'] = True
		return True
	except Exception:
		return False


def _offh_cursor_shown():
	'''True while a modal GUI (ESC menu) owns the mouse: its clicks must not
	drive in-battle actions such as the post-mortem vehicle cycle.'''
	try:
		import BigWorld
		p = BigWorld.player()
		if p is not None and getattr(p, '_offhangar_gui_visible', False):
			return True
		aih = getattr(p, 'inputHandler', None)
		if aih is not None and getattr(aih, '_AvatarInputHandler__detachCount', 0) < 0:
			return True
	except Exception:
		pass
	return False


def _offh_mock_team(mock, default=-1):
	"""Team of a bot mock, read the way `_offh_is_ally` reads it.

	`mock.team` is NOT that field: the first HITRES run printed `st=None tt=None`
	for every hit, and because `None == None` each of them was reported as
	`friendly=True`.  That made the friendly-fire question look answered when the
	numbers were an artifact.  Bots carry `_bot_team`, or `publicInfo['team']`.
	"""
	try:
		_t = getattr(mock, '_bot_team', None)
		if _t is None:
			_pi = getattr(mock, 'publicInfo', None)
			if _pi is not None:
				_t = _pi.get('team', None)
		if _t is None:
			_t = getattr(mock, 'team', None)
		if _t is None:
			return default
		return int(_t)
	except Exception:
		return default


def _offh_player_team(player, default=-1):
	"""Team of the local player: `_offhangar_team` first (that is the attribute
	`_offh_is_ally` compares against), then `team`, then the default."""
	try:
		_t = getattr(player, '_offhangar_team', None)
		if _t is None:
			_t = getattr(player, 'team', None)
		if _t is None:
			return default
		return int(_t)
	except Exception:
		return default


def _offh_shell_label(shell):
	"""Short shell label for the log; `name` is not always present (the first
	HITRES run printed `shell=?` for every hit)."""
	try:
		if shell is None:
			return '?'
		_n = getattr(shell, 'name', None)
		if _n:
			return str(_n)
		_c = getattr(shell, 'caliber', None)
		if _c:
			return 'cal%s' % _c
		_i = getattr(shell, 'id', None)
		return '?' if _i is None else 'id%s' % _i
	except Exception:
		return '?'


_offh_hit_trace_n = [0]


def _offh_hit_trace(src, shooter_id, shooter_team, target_id, target_team, dist,
		shell_name, hit_res, pen_res, armor, eff_armor, dmg, hp_after, friendly):
	"""One log line per RESOLVED shell hit, under the flag `hit_result_trace`.

	A full 30-minute battle log carried NO hit marker at all (0 lines for 1051 bot
	shots), so "nobody but me took damage" could not be told apart from "the log
	simply does not say".  This records both teams, the distance, the shell, the
	penetration outcome and the damage actually applied - the two things the
	friendly-fire question and the damage balance both need.  `hit_res` keeps the
	convention already used next to the call sites: 0 = ricochet/bounce,
	1 = no penetration, 2 = penetration.

	Deliberately additive: it only reads values the caller already computed and
	swallows its own exceptions, so a formatting problem can never eat a hit.
	"""
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _HRC
		if not _HRC.get('hit_result_trace', False):
			return
		_offh_hit_trace_n[0] += 1
		LOG_NOTE('HITRES src=%s sh=%s st=%s tg=%s tt=%s dist=%.1f shell=%s res=%s pen=%s armor=%.1f eff=%.1f dmg=%s hp=%s friendly=%s n=%d' % (
			src, shooter_id, shooter_team, target_id, target_team,
			float(dist or 0.0), shell_name, hit_res, pen_res,
			float(armor or 0.0), float(eff_armor or 0.0), dmg, hp_after,
			friendly, _offh_hit_trace_n[0]))
	except Exception:
		pass


def _offh_is_ally(mock):
	'''True when this mock shares the player's team. Friendly fire IS possible
	(the shot loop does not filter by team), and sound_notifications.xml carries
	separate ally_* events - reporting a team-mate as an enemy kill is wrong.'''
	try:
		import BigWorld
		_pt = getattr(BigWorld.player(), '_offhangar_team', 1)
		_t = getattr(mock, '_bot_team', None)
		if _t is None:
			_pi = getattr(mock, 'publicInfo', None)
			_t = _pi.get('team', 2) if _pi else 2
		return _t == _pt
	except Exception:
		return False


def _offh_resolve_hull_hit(shot, dist_m, all_hits):
	'''Find the first STRUCTURAL plate behind any spaced armour.

	Returns (result, eff_armor, pierce, spaced_mm, angle_cos) where result is the
	_offh_penetration verdict for that plate, or None when the round never reaches
	structure - i.e. the track absorbed it.

	Tracks and external devices carry vehicleDamageFactor 0.0: they are not the
	hull, so they must not take hull damage. What they DO is cost penetration on
	the way through, which is why a shot that clips the track at a shallow angle
	(long path, thick effective plate) is swallowed while a square-on hit carries
	into the hull behind it.

	HEAT is a special case, as in the game: the shaped charge detonates on the
	first spaced plate it touches and the jet does not survive the standoff, so a
	track absorbs it outright regardless of the angle.'''
	import math
	if not all_hits:
		return None
	shell = (shot.get('shell') or {}) if hasattr(shot, 'get') else {}
	kind = shell.get('kind', 'ARMOR_PIERCING')
	spaced = 0.0
	try:
		_ordered = sorted(all_hits, key=lambda h: h[0])
	except Exception:
		_ordered = all_hits
	for _h in _ordered:
		try:
			_d, _ac, _mat = _h[0], _h[1], _h[2]
		except Exception:
			continue
		if _mat is None:
			continue
		_vdf = getattr(_mat, 'vehicleDamageFactor', 1.0)
		_arm = float(getattr(_mat, 'armor', 0.0) or 0.0)
		if _vdf == 0.0:
			# spaced armor (tracks, gun barrel, mantlet edges, viewports): attenuate penetration instead of auto-killing HEAT!
			_a = abs(float(_ac))
			if _a > 1.0: _a = 1.0
			if _a < 0.15: _a = 0.15
			spaced += (_arm / _a) * (1.35 if kind == 'HOLLOW_CHARGE' else 1.0)
			continue
		if _arm <= 0.0:
			continue
		_res, _eff, _p = _offh_penetration(shot, dist_m, _arm, _ac, spaced)
		return (_res, _eff, _p, spaced, _ac)
	return None


def _offh_postmortem_grading():
	'''Retail's desaturated postmortem look, forced past the quality gate.

	g_postProcessing.enable('postmortem') on its own is not enough on this client.
	Two separate faults:

	* Every _Effect is gated by __isSupported, which needs __curQuality to be IN
	  the effect's qualityMask range - and _fromMaskToQualityRange only ever
	  produces 0/1/2. python.log reports "The quality = 4 was selected", so
	  NOTHING is supported: enable() pushes an empty chain and silently produces
	  no grading at all. That is why the grey look vanished after a graphics
	  settings change and why no error was ever logged.
	* enable() only APPENDS to __curEffects; WG relies on the OUTGOING control
	  mode's disable() to clear it. We switch to arcade first, so without an
	  explicit disable() the chain came out as arcade + postmortem mixed.

	The chains themselves are loaded at startup - WGPostProcessing.init() calls
	effect.create() for every mode regardless of quality - so when the supported
	path yields nothing, push the loaded chains straight through.'''
	try:
		import PostProcessing
		from post_processing import g_postProcessing as _pp
	except Exception as _ppi:
		LOG_DEBUG('postmortem grading: no post_processing (%s)' % str(_ppi))
		return
	try: _pp.disable()
	except Exception: pass
	try: _pp.enable('postmortem')
	except Exception as _ppe:
		LOG_DEBUG('postmortem grading enable err:', str(_ppe))
		return
	_cur = getattr(_pp, '_WGPostProcessing__curEffects', None) or []
	_set = getattr(_pp, '_WGPostProcessing__settings', None) or {}
	for _e in _cur:
		try:
			if _e._Effect__isSupported(_set):
				return         # quality gate passed - retail path already did the work
		except Exception:
			pass
	_chain = []
	for _e in _cur:
		# 'advanced' effects need MRT, which __isSupported hard-refuses in this
		# build; map-depended ones build their chain per arena in enable().
		if getattr(_e, '_Effect__isAdvanced', False) or getattr(_e, '_Effect__isMapDepended', False):
			continue
		_c = getattr(_e, '_Effect__chain', None)
		if not _c:
			continue
		_chain += list(_c)
		_ct = getattr(_e, '_Effect__ctrl', None)
		if _ct is not None:
			try: _ct.enable()
			except Exception: pass
	if _chain:
		try:
			PostProcessing.chain(_chain)
			LOG_DEBUG('postmortem grading forced past the quality gate: %d effects' % len(_chain))
		except Exception as _pce:
			LOG_DEBUG('postmortem grading chain err:', str(_pce))
	else:
		LOG_DEBUG('postmortem grading: no loaded chain to force')


def _module_ui_name(name):
	'''Damage-panel device name = extra name minus 'Health'; tracks keep their side.

	The battle scope defines its own and publishes it over this one. This module-level
	copy exists because _offh_knock_out_everything is module-level too: without it the
	name lookup raised NameError and took the whole panel block down with it.'''
	return name[:-6] if name.endswith('Health') else name


class _OffhAliveState(object):
	'''Alive flag that answers to BOTH `mock.isAlive()` and `if mock.isAlive:`.

	The mocks used to carry a method that always returned True, and every death
	path then overwrote it with a plain bool. From that moment WG's own code
	broke on the tank: gui/Scaleform/Battle.py DamagePanel._setup does
	`if not vehicle.isAlive():`, which on a bool raises

	    TypeError: 'bool' object is not callable

	and takes the whole panel setup with it - that traceback appears 13 times in
	one battle log, every time the panel binds to a dead mock (postmortem, and
	each spectator switch). Our own code reads the same attribute as a value in
	a dozen places, so it has to work both ways.'''
	__slots__ = ('value',)

	def __init__(self, value=True):
		self.value = bool(value)

	def set(self, value):
		self.value = bool(value)

	def __call__(self):
		return self.value

	def __nonzero__(self):      # Python 2 truth test
		return self.value

	__bool__ = __nonzero__      # and Python 3, for the desktop self-tests

	def __repr__(self):
		return 'alive' if self.value else 'dead'



def _get_replay_machinima():
	"""Load gui.mods.offhangar.replay_machinima with execfile fallback for WoT 0.8.2."""
	global _g_replay_machinima
	if _g_replay_machinima is not None:
		return _g_replay_machinima
	if globals().get('_g_replay_machinima_failed', False):
		raise ImportError('replay_machinima not found (cached)')
	try:
		from gui.mods.offhangar import replay_machinima as _rm_mod
		_g_replay_machinima = _rm_mod
		return _rm_mod
	except Exception:
		pass
	import sys, os, types
	full_name = 'gui.mods.offhangar.replay_machinima'
	if full_name in sys.modules:
		_g_replay_machinima = sys.modules[full_name]
		return _g_replay_machinima
	candidates = []
	try:
		candidates.append(os.path.dirname(os.path.abspath(__file__)))
	except Exception:
		pass
	candidates.append(os.path.join('res_mods', '0.8.2', 'scripts', 'client', 'gui', 'mods', 'offhangar'))
	for _base_d in list(candidates):
		candidates.append(os.path.join(_base_d, 'network'))
		candidates.append(os.path.join(_base_d, 'ui'))
	for _dir in candidates:
		py_path = os.path.join(_dir, 'replay_machinima.py')
		if os.path.exists(py_path):
			mod = types.ModuleType(full_name)
			mod.__file__ = py_path
			sys.modules[full_name] = mod
			try:
				execfile(py_path, mod.__dict__)
			except Exception:
				del sys.modules[full_name]
				raise
			_g_replay_machinima = mod
			return mod
	globals()['_g_replay_machinima_failed'] = True
	raise ImportError('replay_machinima not found')


def _offh_is_sandbox_machinima_mode(player=None):
	"""True when battle replays or Sandbox / Machinima mode is enabled in config."""
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _SM_CFG
		if bool(_SM_CFG.get('sandbox_machinima_mode', False)):
			return True
		if bool(_SM_CFG.get('enable_battle_replays', True)) or bool(_SM_CFG.get('record_replays', True)):
			return True
	except Exception:
		pass
	return True

def _offh_trigger_track_drift(veh_mock, was_left, was_right, now_left, now_right, speed, is_airborne, now_time):
	"""Trigger momentum drift toward newly broken track if moving fast on ground."""
	if is_airborne or abs(speed) < 4.5:
		return
	broken_side = 0
	if now_left and not was_left:
		broken_side = -1
	elif now_right and not was_right:
		broken_side = 1
	if broken_side != 0:
		if speed < -0.5:
			broken_side = -broken_side
		dur = max(0.4, min(0.85, abs(speed) / 14.0))
		veh_mock._offh_track_veer_until = now_time + dur
		veh_mock._offh_track_veer_side = broken_side
		veh_mock._offh_track_veer_start = now_time
		veh_mock._offh_track_veer_dur = dur
		veh_mock._offh_track_veer_initial_speed = abs(speed)


def _offh_set_alive(mock, value):
	'''Set a mock's alive flag without ever turning it back into a plain bool.'''
	state = getattr(mock, 'isAlive', None)
	if isinstance(state, _OffhAliveState):
		state.set(value)
	else:
		try:
			mock.isAlive = _OffhAliveState(value)
		except Exception:
			pass
	if not value:
		try:
			mock._last_steer = 0.0
			mock._last_throttle = 0.0
			mock._veh_turn_velocity = 0.0
			_st = getattr(mock, '_offh_native_bot_physics_state', None)
			if _st is not None:
				from gui.mods.offhangar.physics import physics_core as _pc_d
				_pc_d._set_drive_input(_st, 0, 0)
		except Exception:
			pass


class _SynthDeviceExtra(object):
	'''Stand-in for a vehicle-type extra, carrying the one field the crit loop
	reads off it.'''
	__slots__ = ('name',)

	def __init__(self, name):
		self.name = name


class _SynthMaterial(object):
	'''Stand-in for the MaterialInfo of an INTERIOR device hit.

	0.8.2 ships no collision geometry for the interior: all 1975 collision meshes
	in this client carry only armor_N, gun, the two tracks, surveyingDevice and
	gunBreech (the interior kinds survive on two leftover models and no crewman
	kind exists at all). WG resolved those hits server-side against a model that
	was never distributed, so the crit loop is handed one of these instead. The
	values are the era common/vehicle.xml entry for a device material: armor 0,
	damageKind 1 (device), vehicleDamageFactor 0 (the hull damage is already
	accounted for by the penetrating shot) and the real hit chances, which is
	what device_damage.saving_throw reads.'''
	__slots__ = ('extra', 'armor', 'damageKind', 'vehicleDamageFactor',
	             'chanceToHitByProjectile', 'chanceToHitByExplosion')

	def __init__(self, name):
		from gui.mods.offhangar import device_damage as _dd
		self.extra = _SynthDeviceExtra(name)
		self.armor = 0
		self.damageKind = 1
		self.vehicleDamageFactor = 0.0
		self.chanceToHitByProjectile = _dd.fallback_chance(name, False)
		# Crew is the one group where the two differ: 0.33 by shell, 0.15 by blast.
		self.chanceToHitByExplosion = _dd.fallback_chance(name, True)


def _offh_interior_zone(target_mock, all_hits, start_pos, end_pos=None, td=None):
	'''Which interior compartment the shell entered: 'turret', 'hullFront',
	'hullRear' or 'hullSide'.

	The turret case is read straight off the component the shell crossed - that
	geometry IS in the collision model. The hull case is placed from the real
	entry point: the distance of the first structural plate along the shot
	segment gives a world point, the tank's inverse matrix turns it into hull
	coordinates, and device_damage.interior_zone splits it against THIS tank's
	own turret-ring position and half width (both on the descriptor). So "behind
	the ring" means behind that tank's actual ring, not a fixed fraction.

	If any of that is unavailable the bearing to the shooter decides, which is
	coarse but never wrong about a shot coming from directly astern.'''
	import Math
	_comp = None
	_dist = None
	try:
		for _h in sorted(all_hits, key=lambda _x: _x[0]):
			_m = _h[2]
			if _m is None:
				continue
			# The plate that stopped or admitted the round: structural, with thickness.
			if getattr(_m, 'vehicleDamageFactor', 1.0) != 0.0 and float(getattr(_m, 'armor', 0.0) or 0.0) > 0.0:
				_comp = _h[3]
				_dist = _h[0]
				break
	except Exception:
		_comp = None
	try:
		if _comp is not None and hasattr(_comp, 'get'):
			if str(_comp.get('itemTypeName', '')) in ('vehicleTurret', 'vehicleGun'):
				return 'turret'
	except Exception:
		pass
	# Entry point in the tank's own frame, compared against its own geometry.
	try:
		if td is None:
			td = getattr(target_mock, 'typeDescriptor', None)
		if td is not None and _dist is not None and end_pos is not None:
			_dx = float(end_pos.x) - float(start_pos.x)
			_dy = float(end_pos.y) - float(start_pos.y)
			_dz = float(end_pos.z) - float(start_pos.z)
			_dl = (_dx * _dx + _dy * _dy + _dz * _dz) ** 0.5
			if _dl > 0.001:
				_s = float(_dist) / _dl
				_wp = Math.Vector3(float(start_pos.x) + _dx * _s,
				                   float(start_pos.y) + _dy * _s,
				                   float(start_pos.z) + _dz * _s)
				_inv = Math.Matrix(target_mock.matrix)
				_inv.invert()
				_lp = _inv.applyPoint(_wp)
				# Vehicle origin sits on the chassis; the hull model is offset from it.
				_hp = td.chassis['hullPosition']
				_ring = td.hull['turretPositions'][0]
				_bb = td.hull['hitTester'].bbox
				_hw = max(abs(float(_bb[0].x)), abs(float(_bb[1].x)))
				from gui.mods.offhangar import device_damage as _DDz
				return _DDz.interior_zone(float(_lp.x) - float(_hp.x),
				                          float(_lp.z) - float(_hp.z),
				                          float(_ring.z), _hw)
	except Exception as _ze:
		LOG_DEBUG('interior zone from geometry failed, using bearing:', str(_ze))
	try:
		_pos = target_mock.position
		_fwd = Math.Matrix(target_mock.matrix).applyVector(Math.Vector3(0.0, 0.0, 1.0))
		_fx, _fz = float(_fwd.x), float(_fwd.z)
		_fl = (_fx * _fx + _fz * _fz) ** 0.5
		_tx = float(start_pos.x) - float(_pos.x)
		_tz = float(start_pos.z) - float(_pos.z)
		_tl = (_tx * _tx + _tz * _tz) ** 0.5
		if _fl > 0.001 and _tl > 0.001:
			_cos = (_fx * _tx + _fz * _tz) / (_fl * _tl)
			if _cos >= 0.5:
				return 'hullFront'      # within 60 deg of the nose
			if _cos <= -0.5:
				return 'hullRear'
	except Exception:
		pass
	return 'hullSide'


_OFFH_VOICE_BURST = [None]


def _offh_voice_burst_pick(pending):
	'''The one line worth saying out of a single strike: a destroyed module or a
	downed crewman outranks a mere scratch, ties go to the first report.'''
	best = None
	best_rank = -1
	for snd in pending:
		rank = 2 if (snd.endswith('_destroyed') or snd.endswith('_killed')) else 1
		if rank > best_rank:
			best_rank = rank
			best = snd
	return best


def _offh_ignite(target_mock, is_player_target, reason):
	'''Set a vehicle alight and tell the damage panel about it.'''
	target_mock.is_on_fire = True
	try:
		import BigWorld as _bwig
		target_mock._fire_started = _bwig.time()
	except Exception:
		target_mock._fire_started = None
	LOG_DEBUG('FIRE IGNITED ON: %s (%s)' % (getattr(target_mock, 'id', 'PLAYER'), reason))
	if not is_player_target:
		return
	try:
		import gui.WindowsManager
		bw = gui.WindowsManager.g_windowsManager.battleWindow
		if bw is not None and hasattr(bw, 'damagePanel'):
			bw.damagePanel.onFireInVehicle(True)
	except Exception as _fe:
		LOG_DEBUG('FIRE UI UPDATE ERR:', str(_fe))
	try:
		def _auto_extinguish_player_cb():
			try:
				if not getattr(target_mock, 'is_on_fire', False) or getattr(target_mock, 'health', 0) <= 0:
					return
				for _fc in _gun_state.get('consumables', []):
					_fc_name = str(_fc.get('name', '') or '').lower()
					_fc_cd = int(_fc.get('cd', 0) or 0)
					_is_auto_ext = (_fc.get('tag') == 'extinguisher' and ('auto' in _fc_name or ((_fc_cd >> 8) & 0xFFFF) == 4))
					if _is_auto_ext and not _fc.get('used'):
						LOG_NOTE('PLAYER_AUTO_EXTINGUISHER triggered slot=%s name=%s' % (_fc.get('slot'), _fc_name))
						_offh_activate_equipment(_fc.get('slot'))
						return
			except Exception:
				pass
		BigWorld.callback(0.25, _auto_extinguish_player_cb)
	except Exception:
		pass


def _offh_extinguish(target_mock, is_player_target, reason, hull_about_to_change=False):
	'''End a fire and bring the fuel tank back to its regen cap.

	The fuel tank has no repair bar in the game - a destroyed one is red for as
	long as the tank burns and turns orange the moment the fire is out, whether
	the crew smothered it or an extinguisher did. That step is here rather than
	in the repair tick, because it is the FIRE ending that restores it, not time
	spent repairing.'''
	if not getattr(target_mock, 'is_on_fire', False):
		return
	target_mock.is_on_fire = False
	target_mock._fire_started = None
	# FIRE_FX: is_on_fire is only the LOGICAL flag - the live particle handle in
	# mock._fire_fx is a separate thing that _sync_burn_and_death normally tears
	# down on its OWN next tick by noticing the flag changed. That is one tick
	# too late for a caller that is about to swap/delete the hull the effect is
	# attached to in this SAME call (the F7 trainer dead-respawn does exactly
	# that, right after this function returns, and by then health is ALREADY
	# back to full - so a plain "health<=0" died check would wrongly take the
	# non-death branch and try to fade the smoke onto a hull about to be
	# deleted). detach_all (not the "hull already gone" pun on the died=
	# param name) is what _stop_fire_effect actually needs here: cut the
	# effect completely rather than hand it a hull reference that will not
	# survive this same call. hull_about_to_change lets a caller that is
	# mid hull-swap force that, independent of current HP.
	try:
		_fx_before = getattr(target_mock, '_fire_fx', None)
		if _fx_before is not None:
			_fx_hull_id = id(_fx_before.get('hull'))
			_fx_detach_all = hull_about_to_change or (getattr(target_mock, 'health', 1) <= 0)
			LOG_NOTE('FIRE_FX extinguish-stop mock=%s reason=%s hull=0x%x detach_all=%s' % (
				getattr(target_mock, 'id', 'PLAYER'), reason, _fx_hull_id, _fx_detach_all))
			_stop_fire_effect(target_mock, died=_fx_detach_all)
	except Exception as _ffx_e:
		LOG_DEBUG('FIRE_FX extinguish-stop err:', str(_ffx_e))
	LOG_DEBUG('FIRE OUT ON: %s (%s)' % (getattr(target_mock, 'id', 'PLAYER'), reason))
	if is_player_target:
		try:
			import gui.WindowsManager
			bw = gui.WindowsManager.g_windowsManager.battleWindow
			if bw is not None and hasattr(bw, 'damagePanel'):
				bw.damagePanel.onFireInVehicle(False)
		except Exception as _xe:
			LOG_DEBUG('FIRE UI CLEAR ERR:', str(_xe))
	# Fuel tank: destroyed -> back at the regen cap, which reads as 'repaired'.
	try:
		from gui.mods.offhangar import device_damage as _DDx
		td = _device_td(target_mock)
		hp_map = getattr(target_mock, 'devices_hp', None)
		if hp_map is None or td is None:
			return
		name = 'fuelTankHealth'
		cap = _DDx.device_regen_hp(td, name)
		if cap is None or hp_map.get(name, cap) >= cap:
			return
		hp_map[name] = cap
		destroyed = getattr(target_mock, '_destroyed_devices', None)
		if destroyed is not None:
			destroyed.discard(name)
		states = getattr(target_mock, '_module_states', None)
		max_hp = _DDx.device_max_hp(td, name)
		new_state = _DDx.device_state(cap, max_hp)
		if states is not None:
			states[name] = new_state
		_push_device_ui(target_mock, is_player_target, name, cap, max_hp, state='repaired')
	except Exception as _fx:
		LOG_DEBUG('fuel tank restore after fire failed:', str(_fx))


def _offh_module_test_mode():
	'''config module_test_mode: a bench for the module model.

	Bot shells still roll every module and crew crit exactly as they normally
	would - same era saving throws, same HP pools, same repair - but they take
	no hull HP off the player, an ammo rack does not detonate the tank, and fire
	does not drain. So a crit can be watched, repaired, re-broken and listened to
	without the run ending after four shells. Nothing about the crit model
	itself is altered; only the consequences that would end the test.'''
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _TCFG
		return bool(_TCFG.get('module_test_mode', False))
	except Exception:
		return False


def _offh_internal_layout(td):
	'''Per-vehicle interior layout from the adopted profile data, or None.

	None means "fall back to the measured zone model": the feature is switched
	off, the adopted modules are absent, or this tank has no profile. Their
	build_layout() keeps its own cache keyed by type + configuration, so calling
	it per shot is cheap after the first hit on a given tank.'''
	if td is None:
		return None
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _LCFG
		if not bool(_LCFG.get('internal_layout_profiles', True)):
			return None
	except Exception:
		pass
	try:
		from gui.mods.offhangar import internal_hit_layouts as _IHL
	except Exception as _le:
		if not globals().get('_offh_layout_import_logged'):
			globals()['_offh_layout_import_logged'] = True
			LOG_DEBUG('internal_hit_layouts unavailable, using zone model:', str(_le))
		return None
	try:
		return _IHL.build_layout(td, log_build=False)
	except Exception as _be:
		LOG_DEBUG('build_layout failed:', str(_be))
		return None


def _offh_internal_ray_hits(target_mock, td, start_pos, end_pos, covered=()):
	'''Interior modules and crew the shell REALLY passed through.

	Returns [(entry_distance, extraName)] sorted front to back, or None when no
	layout is available. The profile boxes live in their parent component's own
	space, so the segment goes through exactly the two transforms
	Vehicle.getComponents applies: world -> vehicle -> component, which also
	accounts for the current turret yaw and gun pitch.

	`covered` lists extra names the real collision model already produced for
	this shot. Their layout drops any entity it finds in the per-vehicle
	material table, but surveyingDevice is only in the GLOBAL table, so without
	this the optics would be scored twice - once from geometry, once from the
	profile.'''
	layout = _offh_internal_layout(td)
	if not layout:
		return None
	targets = layout.get('targets') or ()
	if not targets:
		return None
	import Math
	from gui.mods.offhangar import internal_geometry as _IG
	inv = Math.Matrix(target_mock.matrix)
	inv.invert()
	_vs = inv.applyPoint(Math.Vector3(start_pos.x, start_pos.y, start_pos.z))
	_ve = inv.applyPoint(Math.Vector3(end_pos.x, end_pos.y, end_pos.z))
	_vdir = _ve - _vs
	_vlen = _vdir.length
	if _vlen > 1e-4 and _vlen < 5.5:
		_ve = _vs + _vdir * (5.5 / _vlen)
	local = {}
	for compDescr, compMatrix in target_mock.getComponents():
		name = None
		for candidate in ('chassis', 'hull', 'turret', 'gun'):
			if compDescr is getattr(td, candidate, None):
				name = candidate
				break
		if name is None:
			continue
		_ls = compMatrix.applyPoint(_vs)
		_le = compMatrix.applyPoint(_ve)
		local[name] = ((_ls.x, _ls.y, _ls.z), (_le.x, _le.y, _le.z))
	hits = []
	for target in targets:
		seg = local.get(target.get('parent'))
		if seg is None:
			continue
		entity = target.get('entity')
		if not entity:
			continue
		name = str(entity) + 'Health'
		if name in covered:
			continue
		interval = _IG.target_interval(seg[0], seg[1], target)
		if interval is None:
			continue
		hits.append((float(interval[0]), name))
	hits.sort()
	# ONE roll per device, not per box. The profiles model a module as several
	# boxes - an ammo rack is typically three (hull floor left, hull floor right,
	# turret ready rack) - and a shell through the fighting compartment crosses
	# two of them. Scoring both would give that module twice the saving throw WG
	# gives it. The log showed exactly that: 'ammoBayHealth@0.04,
	# ammoBayHealth@0.04' from a single strike. Keep the nearest box per device.
	seen = set()
	unique = []
	for dist, name in hits:
		if name in seen:
			continue
		seen.add(name)
		unique.append((dist, name))
	return unique


