_OFFH_SNIPER_AUDIO_STATE = {
	'active': False,
	'saved_vols': {},
}


def _offh_ensure_battle_sound_volumes():
	'''Ensure FMOD 'gui' category volume is never left muted at 0.0 after
	WindowsManager.showBattle() calls enableLobbySounds(False), while preserving
	Sniper Mode interior acoustic ducking when active.'''
	try:
		import SoundGroups as _sg_v
		_inst = getattr(_sg_v, 'g_instance', None)
		if _inst is None:
			return
		_g_vol = float(_inst.getVolume('gui') or 0.0)
		if _g_vol <= 0.01:
			_g_vol = 1.0
		_inst.setVolume('gui', _g_vol, False)
		if _OFFH_SNIPER_AUDIO_STATE.get('active', False):
			return
		for _cat in ('vehicles', 'effects', 'voice', 'ambient'):
			try:
				_cv = float(_inst.getVolume(_cat) or 0.0)
				if _cv > 0.01:
					_inst.setVolume(_cat, _cv, False)
			except Exception:
				pass
	except Exception:
		pass


class _FModSniperAcoustics(object):
	FMOD_DSP_TYPE_LOWPASS = 3
	FMOD_DSP_LOWPASS_CUTOFF = 0
	FMOD_DSP_LOWPASS_RESONANCE = 1

	def __init__(self):
		self._fmodex = None
		self._fmod_event = None
		self._system = None
		self._dsp_units = {}
		self._channel_groups = {}
		self._initialized = False

	def init(self):
		if self._initialized:
			return True
		try:
			import ctypes
			from ctypes import c_int, c_float, c_void_p, byref, POINTER
			self._fmodex = ctypes.windll.LoadLibrary('fmodex.dll')
			self._fmod_event = ctypes.windll.LoadLibrary('fmod_event_net.dll')

			self._fmodex.FMOD_ChannelGroup_GetSystemObject.argtypes = [c_void_p, POINTER(c_void_p)]
			self._fmodex.FMOD_ChannelGroup_GetSystemObject.restype = c_int
			self._fmodex.FMOD_ChannelGroup_Set3DOcclusion.argtypes = [c_void_p, c_float, c_float]
			self._fmodex.FMOD_ChannelGroup_Set3DOcclusion.restype = c_int
			self._fmodex.FMOD_ChannelGroup_AddDSP.argtypes = [c_void_p, c_void_p, c_void_p]
			self._fmodex.FMOD_ChannelGroup_AddDSP.restype = c_int

			self._fmodex.FMOD_System_CreateDSPByType.argtypes = [c_void_p, c_int, POINTER(c_void_p)]
			self._fmodex.FMOD_System_CreateDSPByType.restype = c_int
			self._fmodex.FMOD_DSP_SetParameter.argtypes = [c_void_p, c_int, c_float]
			self._fmodex.FMOD_DSP_SetParameter.restype = c_int
			self._fmodex.FMOD_DSP_SetActive.argtypes = [c_void_p, c_int]
			self._fmodex.FMOD_DSP_SetActive.restype = c_int

			try:
				self._fmod_event.FMOD_EventCategory_GetChannelGroup.argtypes = [c_void_p, POINTER(c_void_p)]
				self._fmod_event.FMOD_EventCategory_GetChannelGroup.restype = c_int
			except AttributeError:
				self._fmod_event._FMOD_EventCategory_GetChannelGroup = getattr(self._fmod_event, '_FMOD_EventCategory_GetChannelGroup@8')
				self._fmod_event._FMOD_EventCategory_GetChannelGroup.argtypes = [c_void_p, POINTER(c_void_p)]
				self._fmod_event._FMOD_EventCategory_GetChannelGroup.restype = c_int

			self._initialized = True
			return True
		except Exception:
			return False

	def _get_category_channel_group(self, category_name):
		if category_name in self._channel_groups:
			return self._channel_groups[category_name]
		try:
			import ctypes
			from ctypes import c_int, c_void_p, byref
			import _FMOD
			cat_obj = _FMOD.EventCategory(category_name)
			if not cat_obj:
				return None
			p_cat = ctypes.c_void_p.from_address(id(cat_obj) + 8).value
			if not p_cat:
				return None
			p_group = c_void_p(0)
			_fn = getattr(self._fmod_event, 'FMOD_EventCategory_GetChannelGroup', None) or getattr(self._fmod_event, '_FMOD_EventCategory_GetChannelGroup', None)
			if _fn is None:
				return None
			res = _fn(p_cat, byref(p_group))
			if res != 0 or not p_group.value:
				return None
			if not self._system:
				p_sys = c_void_p(0)
				if self._fmodex.FMOD_ChannelGroup_GetSystemObject(p_group, byref(p_sys)) == 0:
					self._system = p_sys.value
			self._channel_groups[category_name] = p_group.value
			return p_group.value
		except Exception:
			return None

	def apply_sniper_muffling(self, enable=True, cutoff_hz=1000.0, resonance=1.25, occlusion=0.75):
		if not self._initialized and not self.init():
			return False
		try:
			import ctypes
			from ctypes import c_float, c_void_p, byref
			for cat in ('vehicles', 'ambient'):
				group = self._get_category_channel_group(cat)
				if not group:
					continue
				try:
					direct_occ = occlusion if enable else 0.0
					reverb_occ = (occlusion * 0.5) if enable else 0.0
					self._fmodex.FMOD_ChannelGroup_Set3DOcclusion(group, c_float(direct_occ), c_float(reverb_occ))
				except Exception:
					pass
				try:
					if enable:
						if cat not in self._dsp_units and self._system:
							p_dsp = c_void_p(0)
							if self._fmodex.FMOD_System_CreateDSPByType(self._system, self.FMOD_DSP_TYPE_LOWPASS, byref(p_dsp)) == 0:
								self._dsp_units[cat] = p_dsp.value
								self._fmodex.FMOD_ChannelGroup_AddDSP(group, p_dsp.value, None)
						p_dsp_val = self._dsp_units.get(cat)
						if p_dsp_val:
							self._fmodex.FMOD_DSP_SetParameter(p_dsp_val, self.FMOD_DSP_LOWPASS_CUTOFF, c_float(cutoff_hz))
							self._fmodex.FMOD_DSP_SetParameter(p_dsp_val, self.FMOD_DSP_LOWPASS_RESONANCE, c_float(resonance))
							self._fmodex.FMOD_DSP_SetActive(p_dsp_val, 1)
					else:
						p_dsp_val = self._dsp_units.get(cat)
						if p_dsp_val:
							self._fmodex.FMOD_DSP_SetActive(p_dsp_val, 0)
				except Exception:
					pass
			return True
		except Exception:
			return False

_OFFH_FMOD_ACOUSTICS = _FModSniperAcoustics()


def _offh_apply_sniper_audio_mode(is_sniper, engine_state=None):
	'''Apply authentic WoT 0.8.2 Sniper Mode interior muffled acoustics
	without artificial volume ducking. Uses native FMOD DSP Lowpass filter, 3D Occlusion,
	FMOD interior reverb ('SewerPipe'), and native interior cabin sounds.'''
	st = _OFFH_SNIPER_AUDIO_STATE
	try:
		import BigWorld as _bw_s, SoundGroups as _sg_s
		_inst = getattr(_sg_s, 'g_instance', None)
		if _inst is None:
			return
		_was_sniper_active = bool(st.get('active', False))
		st['active'] = bool(is_sniper)
		try:
			if hasattr(_inst, 'changePlayMode'):
				_inst.changePlayMode(1 if is_sniper else 0)
		except Exception:
			pass
		# Native FMOD DSP Low-Pass Equalizer + 3D Occlusion
		try:
			_OFFH_FMOD_ACOUSTICS.apply_sniper_muffling(bool(is_sniper), cutoff_hz=1000.0, resonance=1.25, occlusion=0.75)
		except Exception:
			pass
		# Cabin reverb
		try:
			if is_sniper:
				_bw_s.wg_setAmbientReverb('SewerPipe')
			else:
				_arena_s = getattr(_bw_s.player(), 'arena', None)
				_preset_s = getattr(getattr(_arena_s, 'arenaType', None), 'defaultReverbPreset', 'Plain')
				_bw_s.wg_setAmbientReverb(_preset_s if _preset_s else 'Plain')
		except Exception:
			pass
		_s_objs = []
		if isinstance(engine_state, dict):
			for _sk in ('snd1', 'snd2'):
				_so = engine_state.get(_sk)
				if _so is not None:
					_s_objs.append(_so)
		try:
			_pl_cur = _bw_s.player()
			for _pk in ('_p_eng_snd', '_p_trd_snd'):
				_po_s = getattr(_pl_cur, _pk, None)
				if _po_s is not None and _po_s not in _s_objs:
					_s_objs.append(_po_s)
		except Exception:
			pass
		for _sobj in _s_objs:
			if hasattr(_sobj, 'param'):
				for _pn, _pval in (('sniper', 1.0 if is_sniper else 0.0), ('inside', 1.0 if is_sniper else 0.0), ('cam_dist', 0.0 if is_sniper else 12.0)):
					try:
						_po = _sobj.param(_pn)
						if _po is not None:
							_po.value = _pval
					except Exception:
						pass
	except Exception:
		pass

def _offh_play_persistent_sound(path, model=None):
	"""Play a 2D or 3D sound event without exhausting the FMOD channel/event pool.
	- 2D events (/GUI/..., /ingame_voice/...) reuse a single cached FMOD.getSound(path)
	  instance per path so repeated notifications never leak FMOD event handles.
	- 3D events purge finished handles and cap active persistent 3D sounds at 6 max."""
	if not path:
		return False
	import BigWorld
	_p_str = str(path)
	_is_2d = (
		_p_str.startswith('/GUI/') or
		_p_str.startswith('/ingame_voice/') or
		_p_str.startswith('GUI/') or
		_p_str.startswith('ingame_voice/')
	)
	_ring = globals().get('g_offh_live_sounds')
	if _ring is None:
		_ring = []
		globals()['g_offh_live_sounds'] = _ring
	# Always purge finished 3D sounds first so FMOD channels are freed immediately
	_alive_ring = []
	for _old_s in _ring:
		try:
			if getattr(_old_s, 'isPlaying', False):
				_alive_ring.append(_old_s)
		except Exception:
			pass
	del _ring[:]
	_ring.extend(_alive_ring)
	if _is_2d or model is None:
		_cache_2d = globals().get('g_offh_2d_snd_cache')
		if not isinstance(_cache_2d, dict):
			_cache_2d = {}
			globals()['g_offh_2d_snd_cache'] = _cache_2d
		if _is_2d:
			try:
				_offh_ensure_battle_sound_volumes()
			except Exception:
				pass
			try:
				import FMOD
				_s2 = _cache_2d.get(_p_str)
				if _s2 is None and hasattr(FMOD, 'getSound'):
					_s2 = FMOD.getSound(_p_str)
					if _s2 is not None:
						_cache_2d[_p_str] = _s2
				if _s2 is not None:
					try:
						if getattr(_s2, 'isPlaying', False) and hasattr(_s2, 'stop'):
							_s2.stop()
					except Exception:
						pass
					_s2.play()
					return True
			except Exception:
				pass
			try:
				import SoundGroups
				_sg = getattr(SoundGroups, 'g_instance', None)
				if _sg is not None and hasattr(_sg, 'FMODplaySound'):
					_s2 = _cache_2d.get(_p_str)
					if _s2 is not None:
						try:
							if getattr(_s2, 'isPlaying', False):
								_s2.stop()
						except Exception:
							pass
						_s2.play()
						return True
					_s2 = _sg.FMODplaySound(_p_str)
					if _s2 is not None:
						_cache_2d[_p_str] = _s2
						return True
			except Exception:
				pass
			try:
				BigWorld.playSound(_p_str)
				return True
			except Exception:
				return False
	# 3D sound playback with rate-limit and strict 6-handle cap
	_now = 0.0
	try:
		_now = float(BigWorld.time())
	except Exception:
		pass
	_last_3d = globals().get('g_offh_3d_snd_last_t')
	if not isinstance(_last_3d, dict):
		_last_3d = {}
		globals()['g_offh_3d_snd_last_t'] = _last_3d
	_k_3d = (_p_str, id(model) if model is not None else 0)
	if _now > 0.0 and (_now - float(_last_3d.get(_k_3d, -10.0))) < 0.04:
		return True
	while len(_ring) >= 8:
		_evict = _ring.pop(0)
		try:
			if hasattr(_evict, 'stop'):
				_evict.stop()
		except Exception:
			pass
	_candidates = []
	_au_set = globals().setdefault('_offh_always_upd_model_ids', set())
	if model is not None:
		_candidates.append(model)
	else:
		_p = BigWorld.player()
		_fm = globals().get('g_offh_hit_carrier')
		_fm_mat = globals().get('g_offh_hit_carrier_mat')
		if _fm is None and _p is not None and hasattr(_p, 'newFakeModel'):
			try:
				_fm = _p.newFakeModel()
				_fm_mat = Math.Matrix()
				_fm_mat.setIdentity()
				_fm.addMotor(BigWorld.Servo(_fm_mat))
				BigWorld.addModel(_fm)
				_offh_register_always_update_model(_fm)
				globals()['g_offh_hit_carrier'] = _fm
				globals()['g_offh_hit_carrier_mat'] = _fm_mat
			except Exception:
				_fm = None
		if _fm is not None:
			try:
				_cam_s = BigWorld.camera()
				_cpos_s = getattr(_cam_s, 'position', None) if _cam_s is not None else None
				if _cpos_s is None and _cam_s is not None and getattr(_cam_s, 'matrix', None) is not None:
					_cpos_s = Math.Matrix(_cam_s.matrix).translation
				if _cpos_s is None and _p is not None and hasattr(_p, 'getOwnVehiclePosition'):
					_cpos_s = _p.getOwnVehiclePosition()
				if _cpos_s is None and _p is not None and getattr(_p, 'position', None) is not None:
					_cpos_s = _p.position
				if _cpos_s is not None:
					if _fm_mat is not None:
						_fm_mat.setTranslate(_cpos_s)
					_fm.position = _cpos_s
			except Exception:
				pass
			_candidates.append(_fm)
		_mvs_s = globals().get('G_MOCK_VEHICLES') or {}
		_pm_s = _mvs_s.get(getattr(_p, 'playerVehicleID', -1)) if _p is not None else None
		if _pm_s is not None:
			for _ma in ('_chassis_model', '_hull_model', 'model'):
				_cand_m = getattr(_pm_s, _ma, None)
				if _cand_m is not None and _cand_m not in _candidates:
					_candidates.append(_cand_m)
	for _m in _candidates:
		if _m is None:
			continue
		if id(_m) not in _au_set:
			_au_set.add(id(_m))
			_offh_register_always_update_model(_m)
		for _cand_p in _offh_expand_082_sound_paths(_p_str):
			if hasattr(_m, 'playSound'):
				try:
					_s = _m.playSound(_cand_p)
					if _s is not None:
						_ring.append(_s)
						_last_3d[_k_3d] = _now
						return True
				except Exception:
					pass
			if hasattr(_m, 'getSound'):
				try:
					_s = _m.getSound(_cand_p)
					if _s is not None:
						_s.play()
						_ring.append(_s)
						_last_3d[_k_3d] = _now
						return True
				except Exception:
					pass
	if model is not None:
		# Never play a 3D bot sound as a 2D global sound in the player's ears if the bot model isn't ready!
		return False
	try:
		BigWorld.playSound(_p_str)
		_last_3d[_k_3d] = _now
		return True
	except Exception:
		return False


def _offh_hit_sound(path, min_gap=0.08):
	'''Play a hit sound on ONE shared carrier model and keep its PySound reference alive.'''
	try:
		import BigWorld
		_now = BigWorld.time()
		_last = globals().setdefault('g_offh_hit_snd_t', {})
		if _now - (_last.get(path, 0.0) or 0.0) < min_gap:
			return
		_last[path] = _now
		_offh_play_persistent_sound(path, model=None)
	except Exception as _hse:
		LOG_DEBUG('hit sound err:', str(_hse))

def _offh_resolve_sound(candidates, fallback):
	'''Resolve a candidate FMOD event path once per battle, falling back to a
	confirmed event. Resolved choices are logged (SOUND_TRAIL) so silent tiers
	show up in the log instead of being guessed.'''
	cache = globals().setdefault('g_offh_snd_cache', {})
	key = '|'.join(candidates)
	if key in cache:
		return cache[key]
	chosen = fallback
	try:
		_fm = globals().get('g_offh_hit_carrier')
		if _fm is None:
			try:
				import BigWorld
				_fm = BigWorld.player().newFakeModel()
				BigWorld.addModel(_fm)
				globals()['g_offh_hit_carrier'] = _fm
			except Exception:
				_fm = None
		if _fm is not None:
			for _c in candidates:
				try:
					if _fm.getSound(_c):
						chosen = _c
						break
				except Exception:
					pass
	except Exception:
		pass
	cache[key] = chosen
	try:
		from gui.mods.offhangar.logging import LOG_NOTE as _srn
		_srn('SOUND_TRAIL resolve [%s] -> %s' % (', '.join(candidates), chosen))
	except Exception:
		pass
	return chosen


# v4.66: EVERY event path in this file used to live under a made-up
# '/hits/hits/...' root that does not exist anywhere in this client's real
# FMOD project (hits.fev). Confirmed by extracting and `strings`-ing the
# user's own hits.fev: the actual top-level groups are '/hits_n_impacts/...',
# '/surface_hits/...', '/explosions/...' and '/tank_death' - none of them
# nest a second 'hits' folder under themselves. That is why every single
# SOUND_TRAIL resolve line in every log this session ever fell through to
# the same generic crit-hit fallback: the candidates were never real event
# names to begin with, so _offh_resolve_sound's probe against the live
# carrier model always failed for all of them. Real events confirmed to
# exist in hits.fev: /hits_n_impacts/tank_hit_armor_crit,
# /hits_n_impacts/tank_hit_armor_crit_large, tank_hit_armor_ricochet,
# tank_hit_armor_not_pierce(_small), tank_hit_armor_pierce, hit_treads,
# collision_with_an_obstacle, hit_water_{small,mid,large},
# hit_ground_small, sand_fall, armor_hit_fougasse, /tank_death. There is no
# separate 'heavy'/'light' crit tier under hits_n_impacts (that distinction
# does not exist in this project) - tank_hit_armor_crit_large is the closest
# real "bigger hit" tier, so it is used for the heavy-caliber case instead of
# probing three non-existent candidate names.
_OFFH_082_SOUND_FALLBACKS = {
	'/hits/hits/hit_treads': ('/hits/hits/hit_treads', '/hits/hits_n_impacts/hit_treads', '/hits_n_impacts/hit_treads', '/hits/hits/tank_hit_armor_pierce_main_crit'),
	'/hits_n_impacts/hit_treads': ('/hits/hits/hit_treads', '/hits/hits_n_impacts/hit_treads', '/hits_n_impacts/hit_treads', '/hits/hits/tank_hit_armor_pierce_main_crit'),
	'/hits/hits_n_impacts/hit_treads': ('/hits/hits/hit_treads', '/hits/hits_n_impacts/hit_treads', '/hits_n_impacts/hit_treads', '/hits/hits/tank_hit_armor_pierce_main_crit'),
	'/hits_n_impacts/tank_hit_armor_ricochet': ('/hits/hits/tank_hit_armor_ricochet', '/hits_n_impacts/tank_hit_armor_ricochet', '/hits/hits_n_impacts/tank_hit_armor_ricochet'),
	'/hits_n_impacts/armor_hit_fougasse': ('/hits/hits/tank_hit_armor_pierce_fougasse_main', '/hits/hits/tank_hit_armor_pierce_fougasse_large', '/hits_n_impacts/armor_hit_fougasse'),
	'/hits_n_impacts/tank_hit_armor_crit': ('/hits/hits/tank_hit_armor_pierce_main_crit', '/hits/hits/tank_hit_armor_large', '/hits_n_impacts/tank_hit_armor_crit'),
	'/hits/hits_n_impacts/tank_hit_armor_crit': ('/hits/hits/tank_hit_armor_pierce_main_crit', '/hits/hits/tank_hit_armor_large', '/hits/hits_n_impacts/tank_hit_armor_crit', '/hits_n_impacts/tank_hit_armor_crit'),
	'/hits_n_impacts/tank_hit_armor_crit_large': ('/hits/hits/tank_hit_armor_pierce_large_crit', '/hits/hits/tank_hit_armor_pierce_huge_crit', '/hits/hits/tank_hit_armor_large', '/hits_n_impacts/tank_hit_armor_crit_large'),
	'/hits/hits_n_impacts/tank_hit_armor_crit_large': ('/hits/hits/tank_hit_armor_pierce_large_crit', '/hits/hits/tank_hit_armor_pierce_huge_crit', '/hits/hits/tank_hit_armor_large', '/hits/hits_n_impacts/tank_hit_armor_crit_large'),
	'/hits_n_impacts/tank_hit_armor_not_pierce_small': ('/hits/hits/tank_hit_armor_not_pierce_small', '/hits/hits/tank_hit_armor_not_pierce_medium', '/hits_n_impacts/tank_hit_armor_not_pierce_small'),
	'/hits_n_impacts/tank_hit_armor_not_pierce': ('/hits/hits/tank_hit_armor_not_pierce_main', '/hits/hits/tank_hit_armor_not_pierce_large', '/hits_n_impacts/tank_hit_armor_not_pierce'),
	'/hits_n_impacts/tank_hit_armor_pierce': ('/hits/hits/tank_hit_armor_pierce_main', '/hits/hits/tank_hit_armor_pierce_large', '/hits_n_impacts/tank_hit_armor_pierce'),
	'/hits/hits_n_impacts/tank_hit_armor_pierce': ('/hits/hits/tank_hit_armor_pierce_main', '/hits/hits/tank_hit_armor_pierce_large', '/hits/hits_n_impacts/tank_hit_armor_pierce', '/hits_n_impacts/tank_hit_armor_pierce'),
	'/hits_n_impacts/collision_with_an_obstacle': ('/tanks/tanks_physics/common_tank/heavy_hit', '/tanks/tanks_physics/common_tank/light_hit', '/hits_n_impacts/collision_with_an_obstacle'),
}

def _offh_expand_082_sound_paths(sound_path):
	_sp = str(sound_path or '')
	if not _sp:
		return ()
	_fb = _OFFH_082_SOUND_FALLBACKS.get(_sp)
	if _fb is not None:
		return _fb
	return (_sp,)

def _offh_hit_event(damage, caliber, shot_result=2, is_he=False, is_crit=False, max_hp=1500.0):
	'''v11.0: Authentic 0.8.2 hit sound from shot_effects.xml (/hits/hits/...) with automatic fallback to modded /hits_n_impacts/...'''
	try:
		caliber = float(caliber or 0.0)
	except Exception:
		caliber = 0.0
	try:
		dmg_val = float(damage or 0.0)
	except Exception:
		dmg_val = 0.0
	if caliber <= 45.0:
		_sz = 'small'
	elif caliber <= 75.0:
		_sz = 'medium'
	elif caliber <= 107.0:
		_sz = 'main'
	elif caliber <= 130.0:
		_sz = 'large'
	else:
		_sz = 'huge'
	_foug_sz = 'medium' if _sz == 'small' else _sz
	if int(shot_result) == 0:
		return '/hits/hits/tank_hit_armor_ricochet'
	if dmg_val <= 0.0:
		if is_he:
			return '/hits/hits/tank_hit_armor_pierce_fougasse_%s' % _foug_sz
		if is_crit or int(shot_result) == 4:
			return '/hits/hits/tank_hit_armor_pierce_%s_crit' % _sz
		return '/hits/hits/tank_hit_armor_not_pierce_%s' % _sz
	if is_he:
		if is_crit or int(shot_result) == 4:
			return '/hits/hits/tank_hit_armor_pierce_fougasse_%s_crit' % _foug_sz
		return '/hits/hits/tank_hit_armor_pierce_fougasse_%s' % _foug_sz
	if is_crit or int(shot_result) == 4:
		return '/hits/hits/tank_hit_armor_pierce_%s_crit' % _sz
	return '/hits/hits/tank_hit_armor_pierce_%s' % _sz


def _offh_get_servo_carrier(carrier_key='g_offh_track_carrier', pos=None):
	'''Return a Servo-driven fake model whose C++ world transform is actively updated to `pos` for FMOD 3D.'''
	import BigWorld as _sc_bw, Math as _sc_math
	_pl = _sc_bw.player()
	_fm = globals().get(carrier_key)
	_mat_key = carrier_key + '_mat'
	_fm_mat = globals().get(_mat_key)
	if _fm is None and _pl is not None and hasattr(_pl, 'newFakeModel'):
		try:
			_fm = _pl.newFakeModel()
			_fm_mat = _sc_math.Matrix()
			_fm_mat.setIdentity()
			_sc_bw.addModel(_fm)
			try:
				_fm.addMotor(_sc_bw.Servo(_fm_mat))
			except Exception:
				pass
			_offh_register_always_update_model(_fm)
			globals()[carrier_key] = _fm
			globals()[_mat_key] = _fm_mat
		except Exception:
			_fm = None
	if _fm is not None and pos is not None:
		try:
			_vpos = _sc_math.Vector3(pos)
			if _fm_mat is not None:
				_fm_mat.setTranslate(_vpos)
			_fm.position = _vpos
		except Exception:
			pass
	return _fm


def _offh_play_direct_3d(model_obj, sound_path):
	'''Play a 3D FMOD sound directly on `model_obj` without rate-limit suppression and retain its handle.'''
	if model_obj is None or not sound_path:
		return False
	import BigWorld as _pd_bw
	_ring = globals().setdefault('g_offh_persistent_sounds', [])
	while len(_ring) >= 12:
		_ev_old = _ring.pop(0)
		try:
			if hasattr(_ev_old, 'stop'):
				_ev_old.stop()
		except Exception:
			pass
	_offh_register_always_update_model(model_obj)
	for _cand_sp in _offh_expand_082_sound_paths(sound_path):
		if hasattr(model_obj, 'getSound'):
			try:
				_s = model_obj.getSound(str(_cand_sp))
				if _s is not None:
					_s.play()
					_ring.append(_s)
					return True
			except Exception:
				pass
		if hasattr(model_obj, 'playSound'):
			try:
				_s = model_obj.playSound(str(_cand_sp))
				if _s is not None:
					_ring.append(_s)
					return True
			except Exception:
				pass
	return False


def _offh_attach_node_track_sound(mock, chassis_model, ev_list):
	'''Replicate vanilla 0.8.2 VehicleAppearance.__initTrackDamageSounds (line 1365):
	fakeModel = BigWorld.player().newFakeModel()
	self.__trailParticleNodes[i].attach(fakeModel)
	sound = fakeModel.getSound('/hits/hits/hit_treads'); sound.play()'''
	if chassis_model is None:
		return False
	try:
		import BigWorld as _va_bw
		_pl = _va_bw.player()
		if _pl is None or not hasattr(_pl, 'newFakeModel'):
			return False
		_fm_node = getattr(mock, '_offh_va_track_fm', None) if mock is not None else None
		if _fm_node is None:
			_fm_node = _pl.newFakeModel()
			_attached = False
			for _nn in ('', 'V', 'HP_Track_LFront', 'HP_Track_RFront'):
				try:
					_nd = chassis_model.node(_nn)
					if _nd is not None:
						_nd.attach(_fm_node)
						_attached = True
						break
				except Exception:
					pass
			if not _attached:
				try:
					_va_bw.addModel(_fm_node)
					_fm_node.position = chassis_model.position
				except Exception:
					return False
			if mock is not None:
				mock._offh_va_track_fm = _fm_node
		for _ep in ev_list:
			if _offh_play_direct_3d(_fm_node, _ep):
				return True
	except Exception:
		pass
	return False


