_OFFH_HELPERS_REENABLE_CFG = {}


_OFFH_RESULTS_STORE_CFG = {}


def _offh_results_store_cfg():
	"""True when offline battle results go through a per-battle store (flag `results_store_by_id`).

	Old behaviour, two defects: (1) the K flow replaced `battleResultsCache.get` with a
	closure over THAT battle's dict and never put the original back (`orig_br_get` was
	saved and never used), and every battle used arenaUniqueID 999 - so every later
	request in the session got the first patched battle's numbers; (2)
	`trigger_battle_results` built a full results dict and never installed it, then
	asked the window for arena 999 - it showed whatever the last K flow had left, or
	went to the real (serverless) cache.  With the flag each battle gets its own id,
	the dict is stored under it, and a single wrapper answers stored ids and passes
	every other id to the original `get`.  Shipped false = the old behaviour.
	"""
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if _OFFH_RESULTS_STORE_CFG.get('gen') == gen:
		return _OFFH_RESULTS_STORE_CFG['on']
	on = False
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _RS_CFG
		on = bool(_RS_CFG.get('results_store_by_id', True))
	except Exception:
		on = True
	_OFFH_RESULTS_STORE_CFG['gen'] = gen
	_OFFH_RESULTS_STORE_CFG['on'] = on
	return on


def _offh_patch_battle_results_cache_obj(cache):
	"""Ensure both BattleResultsCache class and the given cache instance serve g_offh_results_store."""
	try:
		from account_helpers.BattleResultsCache import BattleResultsCache as _BRC_Cls
		if not getattr(_BRC_Cls.get, '_offh_results_store', False):
			_cls_orig = _BRC_Cls.get
			def _cls_store_get(self, arenaUniqueID, callback, _orig=_cls_orig):
				import BigWorld, cPickle
				import AccountCommands as _AC_brc
				_res_ok = getattr(_AC_brc, 'RES_STREAM', 1)
				_st_map = globals().get('g_offh_results_store', {}) or {}
				_aid_key = arenaUniqueID
				if isinstance(_aid_key, str):
					try:
						_aid_key = cPickle.loads(_aid_key)
					except Exception:
						pass
				stored = _st_map.get(_aid_key)
				if stored is None:
					try:
						stored = _st_map.get(int(_aid_key))
					except Exception:
						stored = None
				if stored is None and _st_map:
					try:
						stored = _st_map[max(_st_map.keys())]
					except Exception:
						stored = None
				if stored is not None:
					try:
						LOG_NOTE('RESULTS_STORE_GET (cls) arena=%r -> found=True keys=%d' % (arenaUniqueID, len(stored)))
					except Exception:
						pass
					if callable(callback):
						BigWorld.callback(0.15, lambda: callback(_res_ok, stored))
						return
					LOG_NOTE('RESULTS_STORE_GET callback_missing arena=%r; forwarding to stock cache' % (arenaUniqueID,))
					return _orig(self, arenaUniqueID, callback)
				return _orig(self, arenaUniqueID, callback)
			_cls_store_get._offh_results_store = True
			_cls_store_get._offh_orig = _cls_orig
			_BRC_Cls.get = _cls_store_get
	except Exception:
		pass
	if cache is not None and not getattr(cache.get, '_offh_results_store', False):
		orig_get = cache.get
		def _store_get(arenaUniqueID, callback, _orig=orig_get):
			import BigWorld, cPickle
			import AccountCommands as _AC_brc2
			_res_ok = getattr(_AC_brc2, 'RES_STREAM', 1)
			_st_map = globals().get('g_offh_results_store', {}) or {}
			_aid_key = arenaUniqueID
			if isinstance(_aid_key, str):
				try:
					_aid_key = cPickle.loads(_aid_key)
				except Exception:
					pass
			stored = _st_map.get(_aid_key)
			if stored is None:
				try:
					stored = _st_map.get(int(_aid_key))
				except Exception:
					stored = None
			if stored is None and _st_map:
				try:
					stored = _st_map[max(_st_map.keys())]
				except Exception:
					stored = None
			if stored is None:
				return _orig(arenaUniqueID, callback)
			try:
				LOG_NOTE('RESULTS_STORE_GET (inst) arena=%r -> found=True keys=%d' % (arenaUniqueID, len(stored)))
			except Exception:
				pass
			if callable(callback):
				BigWorld.callback(0.15, lambda: callback(_res_ok, stored))
			else:
				LOG_NOTE('RESULTS_STORE_GET callback_missing arena=%r; forwarding to stock cache' % (arenaUniqueID,))
				return _orig(arenaUniqueID, callback)
		_store_get._offh_results_store = True
		_store_get._offh_orig = orig_get
		cache.get = _store_get


def _offh_results_install(player, results):
	"""Store `results` under a fresh per-battle id and make the cache answer it.

	Returns the id to pass to the results window.  Fail-safe: on any error returns
	the id already in the dict (999 in today's code) and leaves the cache untouched.
	"""
	fallback = results.get('arenaUniqueID', 999) if hasattr(results, 'get') else 999
	try:
		store = globals().setdefault('g_offh_results_store', {})
		if len(store) > 2:
			for _old_k in sorted(store.keys())[:-2]:
				store.pop(_old_k, None)
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
		arena_id = 990000 + gen
		while arena_id in store and store[arena_id] is not results:
			arena_id += 1000
		results['arenaUniqueID'] = arena_id
		store[arena_id] = results
		cache = getattr(player, 'battleResultsCache', None)
		_offh_patch_battle_results_cache_obj(cache)
		LOG_NOTE('RESULTS_STORE installed arena=%s stored=%d gen=%d' % (arena_id, len(store), gen))
		return arena_id
	except Exception as _rs_err:
		try:
			LOG_NOTE('RESULTS_STORE failed err=%r' % (_rs_err,))
		except Exception:
			pass
		return fallback


_OFFH_RESULTS_WINDOW_CFG = {}


def _offh_results_window_cfg():
	"""True when the battle-results window may be shown over the hangar.

	Shipped default is TRUE because that is today's behaviour: the timeout exit
	path builds a mock results dict and schedules
	`WindowsManager.g_windowsManager.showBattleResults(mock_arena_id)` 3.5 s later
	(`offline_battle.py:13046-13052`), i.e. deliberately over the hangar.

	Why it became switchable - four sessions compared after the client died twice
	with `0xC0000005 @ 0x00C66B43 (Read @ 0x00000000)`:
	  13:5x  exit via `_run`→`_end_now`→synthetic K → died between +3.0 s and +4.0 s
	  16:0x  same route (`crosshair_hide_on_exit=off`, so that diff was ruled out)
	         → died in the SAME window, log ends at `after_bnp+3.0s load=1.0`
	  12:36  exit via `_retry`→`_sweep_continuation` → reached +15.0 s, clean close
	  00:2x  same sweep route → reached +15.0 s, clean close
	The results callback is scheduled BEFORE `_leaveArena` (`:13046` precedes the
	synthetic K at `:13106`), so its 3.5 s expire inside that +3.0…+4.0 s window, and
	only the `_end_now` route schedules it at all - the sweep route never builds the
	results dict. Correlation 2/2 against 0/2.
	NOT PROVEN: `WindowsManager.py` is absent from `dev_ref/stock_082` and from the mod,
	so `showBattleResults` lives in the client's .pkg and its body could not be read.
	The mechanism inside it is therefore unverified; this flag is the experiment that
	decides it. false = do not schedule the window (the exit keeps everything else).
	"""
	try:
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
	except Exception:
		gen = 0
	if _OFFH_RESULTS_WINDOW_CFG.get('gen') == gen:
		return _OFFH_RESULTS_WINDOW_CFG['on']
	on = True
	try:
		from gui.mods.offhangar._constants import CONFIG_OPTIONS as _RW_CFG
		on = bool(_RW_CFG.get('hangar_show_battle_results', True))
	except Exception:
		on = True
	_OFFH_RESULTS_WINDOW_CFG['gen'] = gen
	_OFFH_RESULTS_WINDOW_CFG['on'] = on
	try:
		LOG_DEBUG('RESULTS_WINDOW_CFG show=%s' % ('yes' if on else 'no'))
	except Exception:
		pass
	return on


def _safe_find_battle_results_wnd(arena_id):
	try:
		from gui.WindowsManager import g_windowsManager
		wl = getattr(g_windowsManager, 'window', None)
		if wl is None:
			return None
		wl_member = wl.getMember('windowLayout')
		if wl_member is None:
			return None
		wl_member.resync()
		ch = getattr(wl_member, 'children', None)
		if ch is None:
			return None
		key = 'battleResultsWnd' + str(int(arena_id))
		try:
			if key in ch:
				return getattr(getattr(ch[key], 'form', None), 'form', None)
		except Exception:
			pass
		try:
			for k in ch:
				if 'battleResultsWnd' in str(k):
					return getattr(getattr(ch[k], 'form', None), 'form', None)
		except Exception:
			pass
	except Exception:
		pass
	return None


class _BattleResultsWindowProxy(object):
	def __init__(self, brm, arena_id, real_wnd=None):
		self._brm = brm
		self._arena_id = int(arena_id)
		self._real_wnd = real_wnd

	def setCommonData(self, data):
		_aid = self._arena_id
		_brm = self._brm
		_coerced = _offh_coerce_br_strings(data)
		def _deliver(attempt=0):
			real = self._real_wnd or _safe_find_battle_results_wnd(_aid)
			if real is None and _brm is not None:
				try:
					w = _brm.getBattleResultsWindow(_aid)
					if isinstance(w, _BattleResultsWindowProxy):
						real = w._real_wnd or _safe_find_battle_results_wnd(_aid)
					else:
						real = w
				except Exception:
					pass
			if real is not None:
				try:
					real.setCommonData(_coerced)
					LOG_NOTE('BATTLE_RESULTS setCommonData SUCCESS delivered to Flash arena=%s (attempt %d)' % (_aid, attempt))
					return
				except Exception as _e:
					LOG_NOTE('BATTLE_RESULTS setCommonData call err=%r' % (_e,))
			if attempt < 40:
				import BigWorld
				BigWorld.callback(0.1, lambda: _deliver(attempt + 1))
			else:
				LOG_NOTE('BATTLE_RESULTS timed out waiting for Flash setCommonData arena=%s' % (_aid,))
		_deliver(0)

	def __getattr__(self, name):
		real = self._real_wnd or _safe_find_battle_results_wnd(self._arena_id)
		if real is not None and hasattr(real, name):
			return getattr(real, name)
		return None

	def __setattr__(self, name, value):
		if name in ('_brm', '_arena_id', '_real_wnd'):
			super(_BattleResultsWindowProxy, self).__setattr__(name, value)
		else:
			real = self._real_wnd or _safe_find_battle_results_wnd(self._arena_id)
			if real is not None:
				try:
					setattr(real, name, value)
				except Exception:
					pass
			super(_BattleResultsWindowProxy, self).__setattr__(name, value)


def _offh_patch_get_medal_dict_bug():
	"""Ensure dossiers_utils.getMedalDict(achievementType, rank=None, rareAchieveId=None),
	BattleResultsManager.requestCommonData(self, callback, arenaUniqueID), and
	BattleResultsWindow.setCommonData never raise TypeError or fail on plain int strings."""
	try:
		import cPickle
		from gui.Scaleform.utils import dossiers_utils as _du_mod
		from gui.Scaleform import BattleResults as _br_mod
		_orig_gmd = getattr(_du_mod, 'getMedalDict', None)
		if callable(_orig_gmd) and not getattr(_orig_gmd, '_offh_gmd_patched', False):
			def _safe_getMedalDict(achievementType, rank=None, rareAchieveId=None, descr=None, **kw):
				if isinstance(achievementType, (int, long)):
					try:
						from dossiers1 import RECORD_NAMES as _rn_map
						achievementType = _rn_map[int(achievementType)]
					except Exception:
						achievementType = str(achievementType)
				return _orig_gmd(achievementType, rank=rank, rareAchieveId=rareAchieveId)
			_safe_getMedalDict._offh_gmd_patched = True
			_du_mod.getMedalDict = _safe_getMedalDict
			if hasattr(_br_mod, 'getMedalDict'):
				_br_mod.getMedalDict = _safe_getMedalDict
		_brm_cls = getattr(_br_mod, 'BattleResultsManager', None)
		if _brm_cls is not None and not getattr(_brm_cls, '_offh_setcommon_patched', False):
			_orig_gbrw = getattr(_brm_cls, 'getBattleResultsWindow', None)
			if callable(_orig_gbrw):
				def _safe_getBattleResultsWindow(self_brm, arenaUniqueID):
					try:
						_aid = int(arenaUniqueID)
					except Exception:
						try:
							_aid = int(cPickle.loads(str(arenaUniqueID)))
						except Exception:
							_aid = arenaUniqueID
					_aid_int = int(_aid)
					real_wnd = None
					try:
						real_wnd = _orig_gbrw(self_brm, _aid_int)
						if isinstance(real_wnd, _BattleResultsWindowProxy):
							real_wnd = real_wnd._real_wnd
					except Exception:
						pass
					if real_wnd is None:
						real_wnd = _safe_find_battle_results_wnd(_aid_int)
					return _BattleResultsWindowProxy(self_brm, _aid_int, real_wnd)
				_brm_cls.getBattleResultsWindow = _safe_getBattleResultsWindow
			_orig_obrwl = getattr(_brm_cls, 'onBattleResultsWndLoaded', None)
			if callable(_orig_obrwl):
				def _safe_onBattleResultsWndLoaded(self_brm, cid, arenaUniqueId, *a, **kw):
					return _orig_obrwl(self_brm, cid, arenaUniqueId, *a, **kw)
				_brm_cls.onBattleResultsWndLoaded = _safe_onBattleResultsWndLoaded
			_orig_rcd = getattr(_brm_cls, 'requestCommonData', None)
			if callable(_orig_rcd):
				def _safe_requestCommonData(self_brm, *args, **kw):
					return _orig_rcd(self_brm, *args, **kw)
				_brm_cls.requestCommonData = _safe_requestCommonData
			_orig_obrs = getattr(_brm_cls, 'onBattleResultsShow', None)
			if callable(_orig_obrs):
				def _safe_onBattleResultsShow(self_brm, callbackID, arenaUniqueID=None, *a, **kw):
					_auid = arenaUniqueID
					try:
						_auid = int(cPickle.loads(str(_auid)))
					except Exception:
						try:
							_auid = int(str(_auid).strip())
						except Exception:
							pass
					_auid_int = int(_auid) if _auid is not None else 990000
					return _orig_obrs(self_brm, callbackID, str(_auid_int), *a, **kw)
				_brm_cls.onBattleResultsShow = _safe_onBattleResultsShow
			_brm_cls._offh_setcommon_patched = True
	except Exception:
		pass


	# пошёл нахуй этот ненавистный код, лишь бы результаты уже показались
def _offh_open_battle_results_when_hangar_ready(arena_unique_id, attempt=0):
	"""Safely open the Post-Battle Results window once the Hangar Flash UI is loaded and ready."""
	try:
		import BigWorld
		import cPickle as _br_pickle
		from gui import WindowsManager
		from gui.Scaleform.Waiting import Waiting
		_offh_patch_get_medal_dict_bug()
		wm = getattr(WindowsManager, 'g_windowsManager', None)
		window = getattr(wm, 'window', None) if wm is not None else None
		iface = getattr(window, 'currentInterface', None) if window is not None else getattr(wm, '_WindowsManager__currentInterface', None)
		main_iface = getattr(window, '_CommonPage__mainInterface', None) if window is not None else None
		if window is not None:
			try:
				if Waiting.isVisible() and attempt >= 2:
					Waiting.close()
			except Exception:
				pass
		if (window is None or iface != 'hangar' or main_iface is None or attempt < 3) and attempt < 10:
			BigWorld.callback(0.45, lambda: _offh_open_battle_results_when_hangar_ready(arena_unique_id, attempt + 1))
			return
		_aid_int = int(arena_unique_id)
		_aid_pickled = _br_pickle.dumps(int(_aid_int))
		try:
			from gui.Scaleform.BattleResultsWindow import BattleResultsWindow as _BRW_Cls
			if not getattr(_BRW_Cls, '_offh_brw_init_wrapped', False):
				_orig_brw_init = _BRW_Cls.__init__
				def _safe_brw_init(self_brw, arenaUniqueID, *a_brw, **k_brw):
					try:
						if isinstance(arenaUniqueID, basestring):
							try:
								arenaUniqueID = int(_br_pickle.loads(str(arenaUniqueID)))
							except Exception:
								if str(arenaUniqueID).strip().isdigit():
									arenaUniqueID = int(str(arenaUniqueID).strip())
						elif isinstance(arenaUniqueID, (int, long)):
							arenaUniqueID = int(arenaUniqueID)
					except Exception:
						pass
					return _orig_brw_init(self_brw, arenaUniqueID, *a_brw, **k_brw)
				_BRW_Cls.__init__ = _safe_brw_init
				_BRW_Cls._offh_brw_init_wrapped = True
		except Exception:
			pass
		_pl_now = BigWorld.player()
		if _pl_now is not None:
			_offh_patch_battle_results_cache_obj(getattr(_pl_now, 'battleResultsCache', None))
		if window is not None:
			_br_mgr = getattr(window, 'battleResults', None)
			if _br_mgr is None:
				try:
					from gui.Scaleform.BattleResults import BattleResultsManager as _BRM_Cls
					_br_mgr = _BRM_Cls()
					setattr(window, 'battleResults', _br_mgr)
				except Exception:
					_br_mgr = None
			if _br_mgr is not None and getattr(window, 'proxy', None) is not None:
				try:
					_br_mgr.populateUI(window.proxy)
				except Exception:
					try:
						_br_mgr.uiHolder = window.proxy
					except Exception:
						pass
			_opened = False
			if _br_mgr is not None:
				for _mname in ('show', '_BattleResultsManager__showBattleResults'):
					_mfn = getattr(_br_mgr, _mname, None)
					if callable(_mfn):
						try:
							_mfn(_aid_int)
							_opened = True
							LOG_NOTE('RESULTS_WINDOW called battleResults.%s(int=%s)' % (_mname, _aid_int))
							break
						except Exception as _m_e1:
							LOG_NOTE('RESULTS_WINDOW %s(int) err=%r' % (_mname, _m_e1))
			if not _opened and getattr(window, 'proxy', None) is not None:
				try:
					window.proxy.call('common.showBattleResults', [str(_aid_int)])
					_opened = True
					LOG_NOTE('RESULTS_WINDOW invoked Scaleform common.showBattleResults(int=%d)' % (_aid_int,))
				except Exception:
					pass
			if not _opened and wm is not None and hasattr(wm, 'showBattleResults'):
				try:
					wm.showBattleResults(_aid_int)
				except Exception:
					pass
	except Exception as _obr_err:
		try:
			LOG_NOTE('RESULTS_WINDOW open err=%r attempt=%d' % (_obr_err, attempt))
		except Exception:
			pass


def _offh_build_and_schedule_battle_results(player, forced_winner=None, finish_reason=None, loaded_td=None):
	"""Build complete, authentic WoT 0.8.2 post-battle statistics synchronously BEFORE arena teardown,
	and schedule the results window in the Hangar."""
	try:
		import BigWorld, time as _t_res
		if player is None or not hasattr(player, 'arena') or player.arena is None:
			return None
		gen = int(globals().get('g_offh_battle_gen', 0) or 0)
		if globals().get('_offh_results_built_gen') == gen:
			return globals().get('_offh_results_built_arena_id')
		globals()['_offh_results_built_gen'] = gen

		import battle_results_shared
		mock_arena_id = 990000 + gen
		v_id = int(getattr(player, 'playerVehicleID', 1) or 1)
		p_team = int(getattr(player, '_offhangar_team', getattr(player, 'team', 1)) or 1)
		p_name = str(getattr(player, 'name', 'Player') or 'Player')
		p_dbid = int(getattr(player, 'databaseID', 1) or 1)
		_td = loaded_td or getattr(player, 'vehicleTypeDescriptor', None)
		p_cd = int(getattr(getattr(_td, 'type', None), 'compactDescr', 0) or 0)
		if p_cd == 0 and hasattr(player, 'arena') and v_id in getattr(player.arena, 'vehicles', {}):
			_vt = player.arena.vehicles[v_id].get('vehicleType')
			if _vt is not None:
				p_cd = int(getattr(getattr(_vt, 'type', None), 'compactDescr', 0) or 0)
				if _td is None:
					_td = _vt
		p_tier = int(getattr(getattr(_td, 'type', None), 'level', getattr(_td, 'level', 8)) or 8)
		p_max_health = int(getattr(_td, 'maxHealth', 1000) or 1000)
		_mock_vehicles = globals().get('G_MOCK_VEHICLES', {}) or {}
		_player_mock = _mock_vehicles.get(v_id)
		if _player_mock is not None:
			p_max_health = int(getattr(_player_mock, 'maxHealth', p_max_health) or p_max_health)
			p_health = max(0, int(round(float(getattr(_player_mock, 'health', 0) or 0))))
			if getattr(player, '_is_dead', False) or not bool(getattr(_player_mock, 'isAlive', True)):
				p_health = 0
		else:
			p_health = max(0, int(getattr(getattr(player, 'vehicle', None), 'health', p_max_health) or 0))
		_p_killer_id = _offh_killer_id(_player_mock, v_id) if p_health <= 0 else 0

		now_bw = float(BigWorld.time())
		_feedback_values = None
		try:
			from gui.mods.offhangar import battle_feedback as _offh_fb_res
			if _offh_stats_for(player) is not None:
				_feedback_values = _offh_fb_res.result_values(_offh_stats_for(player), now_bw)
		except Exception:
			_feedback_values = None

		_b_start_t = float(globals().get('g_offh_battle_started_at', 0.0) or 0.0)
		battle_duration = int(max(5.0, (now_bw - _b_start_t) if _b_start_t > 0.0 else float((_feedback_values or {}).get('lifeTime', 120) or 120)))

		_p_pbid_res = int(((getattr(player.arena, 'vehicles', {}) or {}).get(v_id) or {}).get('prebattleID', 0) or 0)
		players_dict = {
			p_dbid: {'name': p_name, 'clanDBID': 0, 'clanAbbrev': '', 'prebattleID': _p_pbid_res, 'team': p_team, 'igrType': 0}
		}
		vehicles_dict = {}
		personal_details = {}
		total_dmg_dealt = 0
		total_frags = 0
		total_hits = 0

		allied_alive = 1 if p_health > 0 else 0
		enemy_alive = 0
		allied_frags = 0
		enemy_frags = 0 if p_health > 0 else 1
		allied_dmg_sum = 0
		enemy_dmg_sum = 0

		for vid, vinfo in (getattr(player.arena, 'vehicles', {}) or {}).items():
			if int(vid) == v_id:
				continue
			bm = _mock_vehicles.get(vid)
			bot_team = int(getattr(bm, '_bot_team', vinfo.get('team', 2)) or 2) if bm is not None else int(vinfo.get('team', 2) or 2)
			bot_name = str(vinfo.get('name', 'Bot_%s' % vid))
			bot_dbid = int(vid) if int(vid) != p_dbid else (int(vid) + 50000)
			btd = getattr(bm, 'typeDescriptor', None) if bm is not None else None
			if btd is None:
				btd = vinfo.get('vehicleType', None)
			btd_type = getattr(btd, 'type', None)
			bot_cd = int(getattr(btd_type, 'compactDescr', 0) or 0)
			bot_tier = int(getattr(btd_type, 'level', getattr(btd, 'level', 7)) or 7)
			bot_max_hp = int(getattr(bm, 'maxHealth', getattr(btd, 'maxHealth', 1000)) or 1000)
			if bm is not None:
				bot_hp = max(0, int(round(float(getattr(bm, 'health', 0) or 0))))
				is_killed = (bot_hp <= 0) or (not bool(getattr(bm, 'isAlive', True))) or bool(getattr(bm, '_is_killed', False))
				if is_killed:
					bot_hp = 0
			else:
				is_killed = not bool(vinfo.get('isAlive', True))
				bot_hp = 0 if is_killed else bot_max_hp

			if bot_team == p_team:
				if not is_killed:
					allied_alive += 1
				else:
					enemy_frags += 1
			else:
				if not is_killed:
					enemy_alive += 1
				else:
					allied_frags += 1

			_b_pbid_res = int(vinfo.get('prebattleID', 0) or 0)
			players_dict[bot_dbid] = {'name': bot_name, 'clanDBID': 0, 'clanAbbrev': '', 'prebattleID': _b_pbid_res, 'team': bot_team, 'igrType': 0}

			_dmg_from_player = int(getattr(bm, 'damage_from_player', 0) or 0) if bm is not None else 0
			_hits_from_player = int(getattr(bm, 'hits_from_player', 0) or 0) if bm is not None else 0
			dmg_received = max(0, bot_max_hp - bot_hp)
			killer_id = int(_offh_killer_id(bm, 0) or 0) if is_killed else 0
			player_killed_this = bool(is_killed and (killer_id == v_id or (_dmg_from_player > 0 and killer_id == 0)))
			if player_killed_this and bot_team == p_team:
				player_killed_this = False
			if player_killed_this:
				killer_id = v_id

			total_dmg_dealt += _dmg_from_player
			total_hits += _hits_from_player
			if player_killed_this:
				total_frags += 1

			bot_dmg_dealt = int(getattr(bm, '_stats_damage_dealt', 0) or 0) if bm is not None else 0
			bot_shots = int(getattr(bm, '_stats_shots', 0) or 0) if bm is not None else 0
			bot_hits = int(getattr(bm, '_stats_hits', 0) or 0) if bm is not None else 0
			bot_pierced = int(getattr(bm, '_stats_pierced', bot_hits) or 0) if bm is not None else 0
			bot_he_hits = int(getattr(bm, '_stats_he_hits', 0) or 0) if bm is not None else 0
			bot_spotted = int(getattr(bm, '_stats_spotted', 0) or 0) if bm is not None else 0
			bot_damaged_cnt = len(getattr(bm, '_stats_damaged_set', ()) or ()) if bm is not None else (1 if bot_dmg_dealt > 0 else 0)
			bot_shots_rec = int(getattr(bm, '_stats_shots_received', 0) or 0) if bm is not None else (max(1, int(dmg_received / 320)) if dmg_received > 0 else 0)
			bot_life_t = int(min(battle_duration, max(10, float(getattr(bm, '_death_at_rel', battle_duration) or battle_duration))))

			if bot_team == p_team:
				allied_dmg_sum += bot_dmg_dealt
			else:
				enemy_dmg_sum += bot_dmg_dealt

			vehicles_dict[vid] = {
				'health': bot_hp, 'credits': 0, 'xp': 0,
				'shots': bot_shots, 'hits': bot_hits, 'he_hits': bot_he_hits, 'pierced': bot_pierced,
				'damageDealt': bot_dmg_dealt, 'damageAssisted': 0,
				'damageReceived': dmg_received, 'shotsReceived': bot_shots_rec,
				'spotted': bot_spotted, 'damaged': bot_damaged_cnt, 'kills': 0,
				'tdamageDealt': 0, 'tkills': 0, 'isTeamKiller': False,
				'capturePoints': int(getattr(bm, '_stats_capture_pts', 0) or 0),
				'droppedCapturePoints': int(getattr(bm, '_stats_dropped_pts', 0) or 0),
				'mileage': int(max(25, bot_life_t * 4.2)), 'lifeTime': bot_life_t,
				'killerID': killer_id, 'achievements': [], 'repair': 0, 'freeXP': 0,
				'details': {}, 'accountDBID': bot_dbid, 'team': bot_team,
				'typeCompDescr': bot_cd, 'gold': 0, '_tier': bot_tier, '_max_hp': bot_max_hp,
			}
			_crits_from_player = int(getattr(bm, 'crits_from_player', 0) or 0) if bm is not None else 0
			if _dmg_from_player > 0 or _crits_from_player > 0 or player_killed_this:
				personal_details[vid] = {
					'spotted': 1 if bool(getattr(bm, '_spotted_by_player', False)) else 0,
					'killed': 1 if player_killed_this else 0,
					'hits': max(1, _hits_from_player),
					'he_hits': 0,
					'pierced': max(1, _hits_from_player) if _dmg_from_player > 0 else 0,
					'damageDealt': _dmg_from_player,
					'damageAssisted': 0,
					'crits': _crits_from_player,
					'fire': int(getattr(bm, 'fire_from_player', 0) or 0) if bm is not None else 0,
				}

		if _feedback_values is not None:
			total_dmg_dealt = max(total_dmg_dealt, int(_feedback_values.get('damageDealt', 0) or 0))
			total_hits = max(total_hits, int(_feedback_values.get('hits', 0) or 0))
			total_frags = max(total_frags, int(_feedback_values.get('kills', 0) or 0))
			if _feedback_values.get('details'):
				personal_details = _feedback_values['details']

		allied_dmg_sum += total_dmg_dealt

		# Determine winnerTeam and finishReason accurately (including on early K press!)
		_fw = forced_winner if forced_winner is not None else globals().pop('G_OFFH_FORCED_WINNER', None)
		if _fw is not None:
			winner_team = int(_fw)
			fin_reason = int(finish_reason or (1 if winner_team != 0 else 3))
		else:
			if enemy_alive == 0 and allied_alive > 0:
				winner_team = p_team
				fin_reason = 1
			elif allied_alive == 0 and enemy_alive > 0:
				winner_team = 3 - p_team
				fin_reason = 1
			elif allied_frags > enemy_frags:
				winner_team = p_team
				fin_reason = 1
			elif enemy_frags > allied_frags:
				winner_team = 3 - p_team
				fin_reason = 1
			elif allied_dmg_sum > enemy_dmg_sum + 250:
				winner_team = p_team
				fin_reason = 1
			elif enemy_dmg_sum > allied_dmg_sum + 250:
				winner_team = 3 - p_team
				fin_reason = 1
			else:
				winner_team = 0
				fin_reason = 3

		# Play Victory / Defeat / Draw music immediately before leaving arena
		try:
			import MusicController
			if hasattr(MusicController, 'g_musicController') and MusicController.g_musicController:
				_mc = MusicController.g_musicController
				try: _mc.stop()
				except Exception: pass
				if winner_team == p_team:
					evt = getattr(MusicController, 'MUSIC_EVENT_COMBAT_VICTORY', getattr(MusicController, 'MUSIC_EVENT_VICTORY', 'music_victory'))
				elif winner_team != 0:
					evt = getattr(MusicController, 'MUSIC_EVENT_COMBAT_LOSE', getattr(MusicController, 'MUSIC_EVENT_LOSE', 'music_lose'))
				else:
					evt = getattr(MusicController, 'MUSIC_EVENT_COMBAT_DRAW', getattr(MusicController, 'MUSIC_EVENT_DRAW', 'music_draw'))
				try: _mc.play(evt)
				except Exception: pass
		except Exception:
			pass

		p_shots = int((_feedback_values or {}).get('shots', globals().get('G_OFFHANGAR_SHOTS_FIRED', total_hits)) or 0)
		p_pierced = int((_feedback_values or {}).get('pierced', total_hits) or 0)
		p_he_hits = int((_feedback_values or {}).get('he_hits', 0) or 0)
		p_assist = int((_feedback_values or {}).get('damageAssisted', 0) or 0)
		p_dmg_rec = int((_feedback_values or {}).get('damageReceived', max(0, p_max_health - p_health)) or 0)
		p_shots_rec = int((_feedback_values or {}).get('shotsReceived', max(1, int(p_dmg_rec / 300)) if p_dmg_rec > 0 else 0) or 0)
		p_spotted = int((_feedback_values or {}).get('spotted', len(personal_details)) or 0)
		p_damaged = int((_feedback_values or {}).get('damaged', len(personal_details)) or 0)
		p_cap = int((_feedback_values or {}).get('capturePoints', 0) or 0)
		p_drop_cap = int((_feedback_values or {}).get('droppedCapturePoints', 0) or 0)
		p_mileage = int((_feedback_values or {}).get('mileage', max(50, int(battle_duration * 3.5))) or 0)
		p_life_time = int((_feedback_values or {}).get('lifeTime', battle_duration) or battle_duration)

		vehicles_dict[v_id] = {
			'health': p_health, 'credits': 0, 'xp': 0,
			'shots': p_shots, 'hits': total_hits, 'he_hits': p_he_hits, 'pierced': p_pierced,
			'damageDealt': total_dmg_dealt, 'damageAssisted': p_assist,
			'damageReceived': p_dmg_rec, 'shotsReceived': p_shots_rec,
			'spotted': p_spotted, 'damaged': p_damaged, 'kills': total_frags,
			'tdamageDealt': 0, 'tkills': 0, 'isTeamKiller': False,
			'capturePoints': p_cap, 'droppedCapturePoints': p_drop_cap,
			'mileage': p_mileage, 'lifeTime': p_life_time,
			'killerID': _p_killer_id, 'achievements': [], 'repair': 0, 'freeXP': 0,
			'details': {}, 'accountDBID': p_dbid, 'team': p_team,
			'typeCompDescr': p_cd, 'gold': 0, '_tier': p_tier, '_max_hp': p_max_health,
		}

		# Tally kills from killerID across all vehicles
		for v_iter_id, v_iter_data in vehicles_dict.items():
			k_id = int(v_iter_data.get('killerID', 0) or 0)
			if k_id and k_id in vehicles_dict and k_id != v_iter_id and k_id != v_id:
				vehicles_dict[k_id]['kills'] = int(vehicles_dict[k_id].get('kills', 0) or 0) + 1
		vehicles_dict[v_id]['kills'] = total_frags

		# Compute authentic WoT 0.8.2 XP, Credits & Battle Hero Achievements for every vehicle in the battle!
		for vid_k, vdata in vehicles_dict.items():
			_vt_lvl = int(vdata.pop('_tier', 8) or 8)
			_vm_hp = int(vdata.pop('_max_hp', 1500) or 1500)
			vdata['_tier_saved'] = _vt_lvl
			vdata['_max_hp_saved'] = _vm_hp
			_v_win = (int(vdata.get('team', 1)) == winner_team and winner_team != 0)
			_v_alive = int(vdata.get('health', 0) or 0) > 0
			_v_dmg = int(vdata.get('damageDealt', 0) or 0)
			_v_ass = int(vdata.get('damageAssisted', 0) or 0)
			_v_kls = int(vdata.get('kills', 0) or 0)
			_v_spt = int(vdata.get('spotted', 0) or 0)
			_v_dmd = int(vdata.get('damaged', 0) or 0)
			_v_cap = int(vdata.get('capturePoints', 0) or 0)
			_v_dcp = int(vdata.get('droppedCapturePoints', 0) or 0)
			_raw_xp = (
				35.0 + _vt_lvl * 8.0 + (35.0 if _v_alive else 0.0) +
				_v_dmg * (0.14 + 0.008 * _vt_lvl) +
				_v_ass * 0.075 + _v_spt * 24.0 + _v_dmd * 14.0 +
				_v_kls * (48.0 + _vt_lvl * 5.0) +
				_v_cap * 2.5 + _v_dcp * 3.0 +
				min(110.0, battle_duration * 0.30))
			if _v_win:
				_raw_xp *= 1.50
			_final_xp = max(25, int(round(_raw_xp * (1.50 if vid_k == v_id else 1.0))))
			_free_xp = max(1, int(round(_final_xp * 0.05)))
			_raw_cred = (
				(2200.0 + _vt_lvl * 1250.0) * (1.50 if _v_win else 1.0) +
				_v_dmg * (12.5 + _vt_lvl * 1.35) +
				_v_ass * 6.0 + _v_spt * 500.0 + _v_kls * 1400.0 +
				(_v_cap + _v_dcp) * 160.0)
			_final_cred = max(1500, int(round(_raw_cred * (1.50 if vid_k == v_id else 1.0))))
			_rep_cost = max(0, int(round(max(0, _vm_hp - int(vdata.get('health', 0) or 0)) * (1.8 + _vt_lvl * 1.45))))
			vdata['xp'] = _final_xp
			vdata['freeXP'] = _free_xp
			vdata['credits'] = _final_cred
			vdata['repair'] = _rep_cost

		# Award authentic WoT 0.8.2 Battle Hero & Epic medals (achievements) across all vehicles
		_max_kills_all = max([int(_vd.get('kills', 0) or 0) for _vd in vehicles_dict.values()] + [0])
		_max_dmg_all = max([int(_vd.get('damageDealt', 0) or 0) for _vd in vehicles_dict.values()] + [0])
		_max_dmg_rec_alive = max([int(_vd.get('damageReceived', 0) or 0) for _vd in vehicles_dict.values() if int(_vd.get('health', 0) or 0) > 0 and int(_vd.get('shotsReceived', 0) or 0) >= 11] + [0])
		_max_dmd_all = max([int(_vd.get('damaged', 0) or 0) for _vd in vehicles_dict.values()] + [0])
		_max_spt_all = max([int(_vd.get('spotted', 0) or 0) for _vd in vehicles_dict.values()] + [0])
		_ACH_NAMES_RU = {
			34: 'Воин',
			35: 'Стальная стена',
			36: 'Снайпер',
			37: 'Захватчик',
			38: 'Коса смерти',
			39: 'Защитник',
			40: 'Поддержка',
			41: 'Разведчик',
			42: 'Дозорный',
			52: 'Камикадзе',
			59: 'Стрелок',
			60: 'Бронебойщик',
		}
		for _vid_a, _vd_a in vehicles_dict.items():
			_vd_a.pop('_tier_saved', None)
			_vd_a.pop('_max_hp_saved', None)
			_ach_list = []
			_vk = int(_vd_a.get('kills', 0) or 0)
			_vdmg = int(_vd_a.get('damageDealt', 0) or 0)
			_vshots = int(_vd_a.get('shots', 0) or 0)
			_vhits = int(_vd_a.get('hits', 0) or 0)
			_vpierced = int(_vd_a.get('pierced', 0) or 0)
			_vdmd = int(_vd_a.get('damaged', 0) or 0)
			_vspt = int(_vd_a.get('spotted', 0) or 0)
			_vass = int(_vd_a.get('damageAssisted', 0) or 0)
			_vcap = int(_vd_a.get('capturePoints', 0) or 0)
			_vdcp = int(_vd_a.get('droppedCapturePoints', 0) or 0)
			_vdrec = int(_vd_a.get('damageReceived', 0) or 0)
			_vsrec = int(_vd_a.get('shotsReceived', 0) or 0)
			_valive = int(_vd_a.get('health', 0) or 0) > 0
			_vwin = (int(_vd_a.get('team', 1)) == winner_team and winner_team != 0)
			# 34: Warrior (Воин) >= 6 kills
			if _vk >= 6 and _vk == _max_kills_all:
				_ach_list.append(34)
			# 35: Steel Wall (Стальная стена) >= 1000 dmg received + >= 11 hits + survived
			if _valive and _vdrec >= 1000 and _vsrec >= 11 and _vdrec == _max_dmg_rec_alive:
				_ach_list.append(35)
			# 36: Sniper (Снайпер) >= 85% hit ratio, >= 10 shots, >= 1000 dmg
			if _vshots >= 10 and _vdmg >= 1000 and (float(_vhits) / float(max(1, _vshots))) >= 0.85:
				_ach_list.append(36)
			# 37: Invader (Захватчик) >= 80 capture points on win
			if _vwin and _vcap >= 80:
				_ach_list.append(37)
			# 39: Defender (Защитник) >= 70 dropped capture points
			if _vdcp >= 70:
				_ach_list.append(39)
			# 40: Confederate (Поддержка) >= 6 enemies damaged (more than anyone else)
			if _vdmd >= 6 and _vdmd == _max_dmd_all and 34 not in _ach_list:
				_ach_list.append(40)
			# 41: Scout (Разведчик) >= 9 enemies spotted on win
			if _vwin and _vspt >= 9 and _vspt == _max_spt_all:
				_ach_list.append(41)
			# 42: Patrol Duty (Дозорный) >= 6 spotted or >= 1500 assist
			if (_vspt >= 6 or _vass >= 1500) and 41 not in _ach_list:
				_ach_list.append(42)
			# 59: Sharpshooter (Стрелок) & 60: Master Gunner (Бронебойщик) for strong accuracy/penetration streaks
			if _vid_a == v_id:
				if _vhits >= 10 and (float(_vhits) / float(max(1, _vshots))) >= 0.80:
					_ach_list.append(59)
				if _vpierced >= 5 and (float(_vpierced) / float(max(1, _vhits))) >= 0.80:
					_ach_list.append(60)
				if _vk >= 3 and 34 not in _ach_list:
					_ach_list.append(38)
			_vd_a['achievements'] = _ach_list

		p_vdata = vehicles_dict[v_id]
		_p_mark_of_mastery = 4 if p_vdata['xp'] >= 1200 else (3 if p_vdata['xp'] >= 900 else (2 if p_vdata['xp'] >= 650 else (1 if p_vdata['xp'] >= 450 else 0)))
		_p_popups = []
		for _aid_pop in p_vdata.get('achievements', []):
			_p_popups.append((int(_aid_pop), 1))
		if _p_mark_of_mastery > 0:
			_p_popups.append((79, int(_p_mark_of_mastery)))
		_ammo_cost_credits = int(max(0, p_shots) * (180 + p_tier * 95))
		personal_dict = dict(p_vdata)
		personal_dict.update({
			'details': personal_details,
			'xpPenalty': 0, 'creditsPenalty': 0,
			'creditsContributionIn': 0, 'creditsContributionOut': 0,
			'tmenXP': int(p_vdata['xp']),
			'eventCredits': 0, 'eventGold': 0, 'eventXP': 0, 'eventFreeXP': 0, 'eventTMenXP': 0,
			'autoRepairCost': int(p_vdata['repair']),
			'autoLoadCost': (_ammo_cost_credits, 0),
			'autoEquipCost': (0, 0),
			'isPremium': True,
			'premiumXPFactor10': 15, 'premiumCreditsFactor10': 15,
			'dailyXPFactor10': 10, 'aogasFactor10': 10,
			'markOfMastery': _p_mark_of_mastery,
			'dossierPopUps': _p_popups,
		})

		mock_res = {
			'arenaUniqueID': mock_arena_id,
			'personal': personal_dict,
			'common': {
				'arenaTypeID': getattr(player.arena, 'arenaTypeID', 1),
				'arenaCreateTime': _t_res.time() - battle_duration,
				'winnerTeam': winner_team,
				'finishReason': fin_reason,
				'duration': battle_duration,
				'bonusType': 1,
				'guiType': 1,
				'vehLockMode': 0,
			},
			'players': players_dict,
			'vehicles': vehicles_dict,
		}

		if hasattr(battle_results_shared, 'VEH_FULL_RESULTS'):
			for k in battle_results_shared.VEH_FULL_RESULTS:
				if k not in mock_res['personal']:
					mock_res['personal'][k] = [] if 'list' in k or k == 'achievements' else (0 if k != 'details' else {})
		if hasattr(battle_results_shared, 'VEH_BASE_RESULTS'):
			for k in battle_results_shared.VEH_BASE_RESULTS:
				for v in mock_res['vehicles']:
					if k not in mock_res['vehicles'][v]:
						mock_res['vehicles'][v][k] = [] if 'list' in k or k == 'achievements' else (0 if k != 'details' else {})

		mock_arena_id = _offh_results_install(player, mock_res)
		globals()['_offh_results_built_arena_id'] = mock_arena_id
		try:
			from gui.mods.offhangar.ui.data import record_persistent_battle_outcome
			record_persistent_battle_outcome(
				veh_cd=p_cd,
				is_win=(winner_team == p_team and winner_team != 0),
				is_draw=(winner_team == 0),
				survived=(p_health > 0),
				xp=int(p_vdata['xp']),
				shots=p_shots,
				hits=total_hits,
				pierced=p_pierced,
				damage_dealt=total_dmg_dealt,
				damage_assisted=p_assist,
				damage_received=p_dmg_rec,
				shots_received=p_shots_rec,
				spotted=p_spotted,
				frags=total_frags,
				capture_points=p_cap,
				dropped_capture_points=p_drop_cap,
				mileage=p_mileage,
				life_time=p_life_time,
				mark_of_mastery=_p_mark_of_mastery,
				achievements=list(p_vdata.get('achievements', []))
			)
		except Exception as _rec_e:
			LOG_NOTE('BATTLE_RESULTS persistent stats record err: %s' % (_rec_e,))
		try:
			_is_p_win = (winner_team == p_team and winner_team != 0)
			_is_p_draw = (winner_team == 0)
			_br_fmt_data = {
				'arenaUniqueID': int(mock_arena_id),
				'arenaTypeID': int(getattr(getattr(player, 'arena', None), 'arenaTypeID', 1) or 1),
				'arenaCreateTime': float(_t_res.time() - battle_duration),
				'vehTypeCompDescr': int(p_cd),
				'isWinner': 1 if _is_p_win else (0 if _is_p_draw else -1),
				'xp': int(p_vdata.get('xp', 0)),
				'xpPenalty': 0,
				'dailyXPFactor': 1,
				'credits': int(p_vdata.get('credits', 0)),
				'creditsPenalty': 0,
				'creditsContributionIn': 0,
				'creditsContributionOut': 0,
				'gold': int(p_vdata.get('gold', 0)),
				'repair': int(p_vdata.get('repair', 0)),
				'vehTypeUnlockTime': 0,
				'popUpRecords': list(_p_popups),
			}
			def _push_native_battle_results_notification(_data_dict=_br_fmt_data):
				try:
					_br_type_idx = 11
					try:
						from chat_shared import SYS_MESSAGE_TYPE as _SMT_br
						_br_type_idx = int(_SMT_br.battleResults.index())
					except Exception:
						_br_type_idx = 11
					class _NativeBRMsg(object):
						def __init__(self, d, t_idx):
							self.data = d
							self.type = t_idx
							self.isHighImportance = False
							self.active = True
							self.personal = False
							self.sentTime = __import__('time').time()
					_msg_obj = _NativeBRMsg(_data_dict, _br_type_idx)
					_pushed_sc = False
					try:
						from messenger.gui import MessengerDispatcher as _MD_br
						_sc = getattr(getattr(_MD_br, 'g_instance', None), 'serviceChannel', None)
						if _sc is not None and hasattr(_sc, '_ServiceChannelManager__addServerMessage'):
							_sc._ServiceChannelManager__addServerMessage(_msg_obj)
							_pushed_sc = True
					except Exception as _sc_e:
						LOG_NOTE('BATTLE_RESULTS __addServerMessage err: %s' % (_sc_e,))
						_pushed_sc = False
					if not _pushed_sc:
						from messenger.formatters.service_channel import BattleResultsFormatter as _BRFmt
						_fmt_res = _BRFmt().format(_msg_obj)
						_f_text = _fmt_res.get('text') if isinstance(_fmt_res, dict) else (
							_fmt_res[0] if isinstance(_fmt_res, tuple) and len(_fmt_res) >= 1 else str(_fmt_res))
						if _f_text:
							from gui import SystemMessages as _SM_br
							_sm_t = getattr(_SM_br, 'SM_TYPE', None)
							_mt = getattr(_sm_t, 'BattleResults', getattr(_sm_t, 'Information', 'Information')) if _sm_t else 'Information'
							_SM_br.pushMessage(_f_text, _mt)
					LOG_NOTE('BATTLE_RESULTS native notification pushed arena=%s sc=%s' % (_data_dict.get('arenaUniqueID'), _pushed_sc))
				except Exception as _n_err:
					LOG_NOTE('BATTLE_RESULTS native formatter err: %s' % (_n_err,))
			BigWorld.callback(2.60, _push_native_battle_results_notification)
		except Exception as _sm_e:
			LOG_NOTE('BATTLE_RESULTS SystemMessages push err: %s' % (_sm_e,))
		LOG_NOTE('BATTLE_RESULTS built arena=%s winner=%d player_team=%d dur=%ds dmg=%d kills=%d credits=%d xp=%d alive=%d/%d medals=%s' % (
			mock_arena_id, winner_team, p_team, battle_duration, total_dmg_dealt, total_frags,
			p_vdata['credits'], p_vdata['xp'], allied_alive, enemy_alive, p_vdata.get('achievements', [])))
		if _offh_results_window_cfg():
			BigWorld.callback(2.20, lambda: _offh_open_battle_results_when_hangar_ready(mock_arena_id, 0))
		return mock_arena_id
	except Exception as _br_err:
		import traceback
		LOG_ERROR('BATTLE_RESULTS build failed: %s\n%s' % (_br_err, traceback.format_exc()))
		return None


