								if _np_pose is not None:
									_np_p = _np_pose['position']
									_prev_px, _prev_pz, _prev_pyaw = float(veh_pos[0]), float(veh_pos[2]), float(veh_yaw[0])
									veh_pos[0] = float(_np_p[0]); veh_pos[1] = float(_np_p[1]); veh_pos[2] = float(_np_p[2])
									veh_yaw[0] = float(_np_pose['yaw'])
									_raw_v = float(_np_pose['velocity'])
