									# and WGVehicleFilter2.placingCompensationMatrix stay 100% synchronized!
									_sm_p_np = float(_np_pose['pitch'])
									_sm_r_np = float(_np_pose['roll'])
									player._offh_hull_p = _sm_p_np
									player._offh_hull_r = _sm_r_np
									_np_mock.pitch = _sm_p_np
									_np_mock.roll = _sm_r_np
									player._offh_np_attitude = (_sm_p_np, _sm_r_np)
									_p_ypr_early = (veh_yaw[0], _sm_p_np, _sm_r_np)
									_np_mock.matrix.setRotateYPR(_p_ypr_early)
									_np_mock.matrix.translation = _np_mock.position
									_nm_early = Math.Matrix()
									_nm_early.setRotateYPR(_p_ypr_early)
									_nm_early.translation = _np_mock.position
									chassis_mp.a = _nm_early
