					if _rm_inst.is_active:
						def _rp_sync_player_pose(_px, _py, _pz, _pyaw, _ppitch, _proll, _ptyaw, _pgpitch, _pvel, _php):
							veh_pos[0] = _px; veh_pos[1] = _py; veh_pos[2] = _pz
