									_scan_phase = float(_ai_now) * 0.42 + float(eid) * 1.73
									_scan_amp = 0.28 if float(getattr(m_veh, '_veh_velocity', 0.0) or 0.0) > 1.5 else 0.35
									_aim_target_yaw = _scan_center + math.sin(_scan_phase) * _scan_amp
